        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void editUserMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;
            string employeeExpenseDate = DateTime.Now.ToString("yyyy-MM-dd");

            CommanResponse comman = new CommanResponse();
            UserAccountMaster ilist = new UserAccountMaster();

            ilist.CompanyID = HttpContext.Current.Request.Params["CompanyIDss"];
            ilist.UserAccountId = Convert.ToInt32(HttpContext.Current.Request.Params["UserAccountId"]);
            ilist.UserAccountDateAndTime = Convert.ToDateTime(dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss"));
            ilist.UserAccountName = HttpContext.Current.Request.Params["UserAccountName"];
            ilist.UserRole = HttpContext.Current.Request.Params["UserRole"];
            ilist.UserAccountEmail = HttpContext.Current.Request.Params["UserAccountEmail"];
            ilist.UserAccountMobileNo = HttpContext.Current.Request.Params["UserAccountMobileNo"];
            ilist.AllowLogin = HttpContext.Current.Request.Params["AllowLogin"];
            String pictureStr = "";
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con1 = new SqlConnection(cs))
            {
                SqlCommand cmd1 = new SqlCommand();
                cmd1.Connection = con1;
                cmd1.CommandType = System.Data.CommandType.Text;
                cmd1.CommandText = " select * " +
                    " from UserAccountMaster where UserAccountId = " + ilist.UserAccountId + "";
                con1.Open();
                SqlDataReader rdr = cmd1.ExecuteReader();

                if (rdr.HasRows)
                {
                    string photo = "";

                    while (rdr.Read())
                    {
                        photo = rdr["UserAccountProfile"].ToString();
                    }


                    String imagePath = "";
                    if (request.Files.Count > 0)
                    {
                        string path = Server.MapPath(@"" + photo);
                        FileInfo filess = new FileInfo(path);
                        if (filess.Exists)
                        {
                            filess.Delete();
                        }

                        var photoT = request.Files["UserAccountProfile"]; //get file name
                        if (photoT != null && photoT.ContentLength != 0)
                        {
                            imagePath = "UserProfile/" + RandomString(6, true) + photoT.FileName;
                            photoT.SaveAs(HttpContext.Current.Server.MapPath(imagePath));
                        }

                        pictureStr = ", UserAccountProfile='" + imagePath + "'";
                    }

                }
                con1.Close();


                try
                {

                    int i = 0;
                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        SqlCommand cmd = new SqlCommand();
                        cmd.Connection = con;


                        string temp = "";
                        if (ilist.UserAccountEmail != "")
                        {
                            temp += ", UserAccountEmail='" + ilist.UserAccountEmail + "'";
                        }
                        if (ilist.UserAccountMobileNo != "")
                        {
                            temp += ", UserAccountMobileNo='" + ilist.UserAccountMobileNo + "'";
                        }

                        cmd.CommandType = System.Data.CommandType.Text;
                        cmd.CommandText = "Update UserAccountMaster set UserAccountDateAndTime='" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', UserAccountName='" + ilist.UserAccountName + "' " + temp + pictureStr + ", CompanyId='" + ilist.CompanyID + "', AllowLogin='" + ilist.AllowLogin + "' where UserAccountId='" + ilist.UserAccountId + "'";
                        con.Open();
                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
                        con.Close();

                        if (i > 0)
                        {
                            comman.Code = 201;
                            comman.Message = "Record has been updated successfully.";
                        }
                        else
                        {
                            comman.Code = 410;
                            comman.Message = "Problem has been occurred while submitting your data.";
                        }
                    }


                }
                catch (SqlException ex)
                {
                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        comman.Code = 405;
                        comman.Message = "Cannot insert duplicate values..";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                    }

                }


                JavaScriptSerializer js = new JavaScriptSerializer();
                js.MaxJsonLength = Int32.MaxValue;
                Context.Response.Write(js.Serialize(comman));
            }
        }

