            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;

                    cmd.CommandType = System.Data.CommandType.Text;
                    cmd.CommandText = "Select TOP 1 (ISNULL(Position,0) + 1) as Position from WeftColorMaster order by Position desc ";
                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();
                    int Position = 1;
                    if (rdr.Read())
                    {
                        Position = Convert.ToInt32(rdr["Position"].ToString());
                        //cmd.Dispose();
                        //con.Close();
                    }

                    rdr.Close();
                    cmd.CommandType = System.Data.CommandType.Text;
                    string sql = String.Format("Insert Into WeftColorMaster  (DateAndTime,WeftColor, IsActive, Position, CompanyId, UserAccountId) Values " +
                                    " ('" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @WeftColor, '" + ilist.IsActive + "', '" + Position + "', '" + ilist.CompanyId + "', '" + ilist.UserAccountId + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@WeftColor", SqlDbType.NVarChar).Value = ilist.WeftColor;

                    i = cmd.ExecuteNonQuery();


                    cmd.Dispose();
                    con.Close();


