        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignerMasterById(string id)
        {
            JavaScriptSerializer js;
            List<DesignerMaster> listUser = new List<DesignerMaster>();
            DesignerMasterResponse response = new DesignerMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select * from DesignerMaster where DesignerID = " + id;
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        DesignerMaster condition = new DesignerMaster();
                        condition.DesignerID = Convert.ToInt32(rdr["DesignerID"].ToString());
                        condition.DesignerCode = rdr["DesignerCode"].ToString().ToUpper();
                        condition.DesignerName = rdr["DesignerName"].ToString().ToUpper();
                        condition.Address = rdr["Address"].ToString().ToUpper();
                        condition.BankName = rdr["BankName"].ToString().ToUpper();
                        condition.BankAcNo = rdr["BankAcNo"].ToString().ToUpper();
                        condition.IFSCCode = rdr["IFSCCode"].ToString().ToUpper();
                        condition.AadharUpload = rdr["AadharUpload"].ToString();
                        condition.IsActive = Convert.ToInt32(rdr["IsActive"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listDesignerMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditDesignerMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;
            string employeeExpenseDate = DateTime.Now.ToString("yyyy-MM-dd");

            CommanResponse comman = new CommanResponse();
            DesignerMaster ilist = new DesignerMaster();

            ilist.DesignerID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignerID"]);
            ilist.UserAccountId = Convert.ToInt32(HttpContext.Current.Request.Params["UserAccountId"]);
            ilist.DateandTime = Convert.ToDateTime(dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss"));
            ilist.DesignerCode = HttpContext.Current.Request.Params["DesignerCode"];
            ilist.DesignerName = HttpContext.Current.Request.Params["DesignerName"];
            ilist.Address = HttpContext.Current.Request.Params["Address"];
            ilist.BankName = HttpContext.Current.Request.Params["BankName"];
            ilist.BankAcNo = HttpContext.Current.Request.Params["BankAcNo"];
            ilist.IFSCCode = HttpContext.Current.Request.Params["IFSCCode"];
            ilist.IsActive = Convert.ToInt32(HttpContext.Current.Request.Params["IsActive"]);



            String pictureStr = "";
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con1 = new SqlConnection(cs))
            {
                SqlCommand cmd1 = new SqlCommand();
                cmd1.Connection = con1;
                cmd1.CommandType = System.Data.CommandType.Text;
                cmd1.CommandText = " select * " +
                    " from DesignerMaster where DesignerID = " + ilist.DesignerID + "";
                con1.Open();
                SqlDataReader rdr = cmd1.ExecuteReader();

                if (rdr.HasRows)
                {
                    string photo = "";

                    while (rdr.Read())
                    {
                        photo = rdr["AadharUpload"].ToString();
                    }


                    String imagePath = "";
                    if (request.Files.Count > 0)
                    {
                        string path = Server.MapPath(@"" + photo);
                        FileInfo filess = new FileInfo(path);
                        if (filess.Exists)
                        {
                            filess.Delete();
                        }

                        var photoT = request.Files["AadharUpload"]; //get file name
                        if (photoT != null && photoT.ContentLength != 0)
                        {
                            imagePath = "AadharUpload/" + RandomString(6, true) + photoT.FileName;
                            photoT.SaveAs(HttpContext.Current.Server.MapPath(imagePath));
                        }

                        pictureStr = ", AadharUpload='" + imagePath + "'";
                    }
                }

                con1.Close();

                try
                {

                    int i = 0;
                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        SqlCommand cmd = new SqlCommand();
                        cmd.Connection = con;


                        cmd.CommandType = System.Data.CommandType.Text;
                        cmd.CommandText = "Update DesignerMaster set DateandTime = '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', DesignerCode='" + ilist.DesignerCode.ToUpper() + "', DesignerName='" + ilist.DesignerName.ToUpper() + "', Address='" + ilist.Address.ToUpper() + "', BankName='" + ilist.BankName.ToUpper() + "', BankAcNo='" + ilist.BankAcNo.ToUpper() + "', IFSCCode='" + ilist.IFSCCode.ToUpper() + "' " + pictureStr + ", IsActive='" + ilist.IsActive + "' where DesignerID = '" + ilist.DesignerID + "'";
                        con.Open();
                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
                        con.Close();

                        if (i > 0)
                        {
                            comman.Code = 201;
                            comman.Message = "Record has been updated successfully.";
                        }
                        else
                        {
                            comman.Code = 410;
                            comman.Message = "Problem has been occurred while submitting your data.";
                        }
                    }


                }
                catch (SqlException ex)
                {
                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        comman.Code = 405;
                        comman.Message = "Cannot insert duplicate values..";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                    }

                }

                JavaScriptSerializer js = new JavaScriptSerializer();
                js.MaxJsonLength = Int32.MaxValue;
                Context.Response.Write(js.Serialize(comman));
            }
        }
