        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertLocationMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;

            CommanResponse comman = new CommanResponse();
            LocationMaster ilist = new LocationMaster();
            ilist.LocationTitle = HttpContext.Current.Request.Params["LocationTitle"];
            ilist.LocationAddress = HttpContext.Current.Request.Params["LocationAddress"];
            ilist.IsActive = Convert.ToInt32(HttpContext.Current.Request.Params["IsActive"]);
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;


                    cmd.CommandType = System.Data.CommandType.Text;
                    string sql = String.Format("Insert Into LocationMaster  (DateAndTime, LocationTitle, LocationAddress, IsActive, CompanyId, UserAccountId) Values " +
                                    " ('" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @LocationTitle, @LocationAddress, '" + ilist.IsActive + "', '" + ilist.CompanyId + "', '" + ilist.UserAccountId + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@LocationTitle", SqlDbType.NVarChar).Value = ilist.LocationTitle;
                    cmd.Parameters.Add("@LocationAddress", SqlDbType.NVarChar).Value = ilist.LocationAddress;
                    con.Open();
                    i = cmd.ExecuteNonQuery();


                    cmd.Dispose();
                    con.Close();


                    if (i > 0)
                    {
                        comman.Code = 201;
                        comman.Message = "Godown has been saved successfully.";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Godown Type is already Exists.";
                    }
                }


            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }
            }
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getLocationMaster(string startFrom)
        {

            JavaScriptSerializer js;
            List<LocationMaster> listUser = new List<LocationMaster>();
            LocationMasterResponse response = new LocationMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select * " +
                    " from LocationMaster " +
                    " order by LocationID desc " +
                " OFFSET " + startFrom + " ROWS FETCH NEXT 10 ROWS ONLY ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        LocationMaster condition = new LocationMaster();
                        condition.LocationID = Convert.ToInt32(rdr["LocationID"].ToString());
                        condition.IsActive = Convert.ToInt32(rdr["IsActive"].ToString());
                        condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                        condition.DateAndTimes = Convert.ToDateTime(rdr["DateAndTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.LocationTitle = rdr["LocationTitle"].ToString();
                        condition.LocationAddress = rdr["LocationAddress"].ToString();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listLocationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
