        // View Design Entry Form
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnMaterialMaster()
        {

            JavaScriptSerializer js;
            List<YarnMaterialMaster> listUser = new List<YarnMaterialMaster>();
            YarnMaterialMasterResponse response = new YarnMaterialMasterResponse();

            var request = HttpContext.Current.Request;
            YarnMaterialMaster ilist = new YarnMaterialMaster();

            ilist.SearchYarnMaterial = HttpContext.Current.Request.Params["SearchYarnMaterial"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];



            if (ilist.SearchYarnMaterial != "")
            {
                ilist.SearchYarnMaterial = " where YMM.YarnMaterial LIKE '%" + ilist.SearchYarnMaterial + "%'  ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select YMM.*, UM.Unit, GSM.GSTSLABName from YarnMaterialMaster YMM " +
                    " LEFT JOIN UnitMaster UM ON UM.UnitId = YMM.UnitId " +
                    " LEFT JOIN GSTSLABMaster GSM ON GSM.GSTSLABId =  YMM.GSTSLABId" +
                    " " + ilist.SearchYarnMaterial + "" +
                    " order by YMM.Position DESC " +
                    " OFFSET " + ilist.startFrom + " ROWS FETCH NEXT 10 ROWS ONLY ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnMaterialMaster condition = new YarnMaterialMaster();
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.IsActive = Convert.ToInt32(rdr["IsActive"].ToString());
                        condition.Position = Convert.ToInt32(rdr["Position"].ToString());
                        condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"].ToString());
                        condition.DateandTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString();
                        condition.Denier = rdr["Denier"].ToString();
                        condition.UnitId = Convert.ToInt32(rdr["UnitId"].ToString());
                        condition.Unit = rdr["Unit"].ToString();
                        condition.GSTSLABId = Convert.ToInt32(rdr["GSTSLABId"].ToString());
                        condition.GSTSLABName = rdr["GSTSLABName"].ToString();
                        condition.HSNCode = rdr["HSNCode"].ToString();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listYarnMaterialMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;

        }
