        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void insertDesignColorMatchingFormMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);
            //Int64 EmployeeId, CourierDetailId;
            var request = HttpContext.Current.Request;
            string employeeExpenseDate = DateTime.Now.ToString("yyyy-MM-dd");

            CommanResponse comman = new CommanResponse();
            DesignColorMatchingForm ilist = new DesignColorMatchingForm();

            ilist.DateandTime = Convert.ToDateTime(dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss"));

            string UserAccountId = Context.Request.Cookies["UserIDs"].Value.Split('=')[1];
            string CompanyId = Context.Request.Cookies["CompanyID"].Value.Split('=')[1];
            string FinancialYearID = Context.Request.Cookies["FinacialYearDefaultID"].Value.Split('=')[1];
            ilist.DesignColorMatchingArray = HttpContext.Current.Request.Params["ColorFormArray"];

            if (UserAccountId == "" && CompanyId == "" && FinancialYearID == "")
            {
                comman.Code = 500;
                comman.Message = "Please Re-Login your Account.";
            }
            else
            {
                var myDetails = JsonConvert.DeserializeObject<DesignColorMatchingForm>(ilist.DesignColorMatchingArray);
                string Tdt = dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss");


                try
                {
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        SqlCommand cmd = new SqlCommand();
                        cmd.Connection = con;
                        cmd.CommandType = System.Data.CommandType.Text;



                        string sql = String.Format("Insert Into DesignColorMatchingFormMaster  (DateandTime, UserAccountId, CompanyId, FinancialYearID, DesignEntryFormID, TotalWarp, TotalWeft, ColorArray, WarpCheckBox, WeftCheckBox) OUTPUT INSERTED.DesignColorMatchingFormID Values " +
                                           " ('" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', '" + UserAccountId + "', '" + CompanyId + "', '" + FinancialYearID + "', '" + myDetails.DesignEntryFormID + "', '" + myDetails.TotalWarp + "', " +
                                           " '" + myDetails.TotalWeft + "' , '" + myDetails.ColorArray + "', '" + myDetails.WarpCheckBox + "', '" + myDetails.WeftCheckBox + "')");

                        cmd.CommandText = sql;

                        con.Open();
                        Int64 id = Convert.ToInt64(cmd.ExecuteScalar());

                        //con.Close();
                        if (id > 0)
                        {
                            if (myDetails.listDesignColorMatchingDetails.Count > 0)
                            {
                                foreach (DesignColorMatchingDetails each in myDetails.listDesignColorMatchingDetails)
                                {
                                    string MatchingID = each.WarpMatchingID + "/" + each.FeederMatchingID;
                                    string sqls = String.Format("Insert Into DesignColorMatchingDetails  (DesignColorMatchingFormID, MatchingNo, MatchingID, WarpMatchingID, Warp1, Warp2, Warp3, Warp4, Warp5, Warp6, Warp7, Warp8, Warp9, Warp10, " +
                                        "FeederMatchingID, Feeder1, Feeder2, Feeder3, Feeder4, Feeder5, Feeder6, Feeder7, Feeder8, Feeder9, Feeder10, Feeder11, Feeder12, Feeder13, Feeder14, Feeder15, Feeder16, Feeder17, Feeder18, Feeder19, Feeder20, Feeder21, Feeder22, Feeder23, Feeder24, Feeder25, Feeder26, Feeder27, Feeder28, Feeder29, Feeder30, ColorGroupID, UserAccountId) Values " +
                                           " ( '" + id + "' , '" + each.MatchingNo + "', '" + MatchingID + "' , " +
                                           "  '" + each.WarpMatchingID + "', '" + each.Warp1 + "', '" + each.Warp2 + "' , '" + each.Warp3 + "', '" + each.Warp4 + "', '" + each.Warp5 + "' , '" + each.Warp6 + "' , '" + each.Warp7 + "' , '" + each.Warp8 + "' , '" + each.Warp9 + "' , '" + each.Warp10 + "' , " +
                                           " '" + each.FeederMatchingID + "', '" + each.Feeder1 + "' , '" + each.Feeder2 + "', '" + each.Feeder3 + "', '" + each.Feeder4 + "' , '" + each.Feeder5 + "', '" + each.Feeder6 + "', '" + each.Feeder7 + "', '" + each.Feeder8 + "', '" + each.Feeder9 + "', '" + each.Feeder10 + "', " +
                                           " '" + each.Feeder11 + "' , '" + each.Feeder12 + "', '" + each.Feeder13 + "', '" + each.Feeder14 + "' , '" + each.Feeder15 + "', '" + each.Feeder16 + "', '" + each.Feeder17 + "', '" + each.Feeder18 + "', '" + each.Feeder19 + "', '" + each.Feeder20 + "',  " +
                                           " '" + each.Feeder21 + "' , '" + each.Feeder22 + "', '" + each.Feeder23 + "', '" + each.Feeder24 + "' , '" + each.Feeder25 + "', '" + each.Feeder26 + "', '" + each.Feeder27 + "', '" + each.Feeder28 + "', '" + each.Feeder29 + "', '" + each.Feeder30 + "',0,0 )");

                                    cmd.CommandText = sqls;
                                    cmd.ExecuteNonQuery();

                                }
                            }



                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {

                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
                }
                catch (SqlException ex)
                {
                    //comman.Code = 0;
                    //comman.Message = ex.ToString().ToUpper();
                    //insertUserMaster
                    //var sqlException = ex.InnerException as System.Data.SqlClient.SqlException;

                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        comman.Code = 405;
                        comman.Message = "This Invoice No is already exists.";

                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";

                    }

                }
            }





            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
