                        cmd.CommandText = "SELECT 1 FROM GodownManager WHERE MobileNo = @MobileNo and MobileNo != @tempMobileNo and CompanyId = (select CompanyId from companymaster where is_default = 1) ";
                        cmd.Parameters.Clear();
