                            "  Email = '" + ilist.Email + "', ManagerAddress =  @ManagerAddress,  " +
                            " IsActiveManager = '" + ilist.IsActiveManager + "' " +
                            " where GodownManagerID = '" + ilist.GodownManagerID + "' ");

