                        cmd.Parameters.Add("@GodownManagerName", SqlDbType.NVarChar).Value = ilist.GodownManagerName;
                        cmd.Parameters.Add("@ManagerAddress", SqlDbType.NVarChar).Value = ilist.ManagerAddress;

                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
