        [WebMethod]
        public List<string> GetAutoYarnCompanyName(string term)
        {
            List<string> listCountryName = new List<string>();
            string CS = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            string query = string.Format("select DISTINCT(CompanyName) from YarnRequirementDetail where CompanyName LIKE '%" + term + "%' Order By CompanyName");
            using (SqlConnection con = new SqlConnection(CS))
            {
                SqlCommand cmd = new SqlCommand(query, con);

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();
                while (rdr.Read())
                {
                    listCountryName.Add(rdr["CompanyName"].ToString());
                }
                return listCountryName;
            }
        }

