        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnPOMasterPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            var request = HttpContext.Current.Request;
            PagginationMaster ilist = new PagginationMaster();

            ilist.SearchString = HttpContext.Current.Request.Params["SearchRequirementNo"];


            string SearchString = "";
            if (ilist.SearchString != "")
            {
                SearchString = " and (YRM.PONo LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or SPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or BPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or CPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or SPPM.PartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' ) ";
            }



            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select COUNT(*) as Total, CAST(ceiling(CAST(COUNT(*) AS DECIMAL(7,2) ) / CAST(30 AS DECIMAL(7,2) )) AS DECIMAL(7,0)) as Paggination  " +
                    " from ( select YRM.*, SPM.PartyName as SupplierParty, BPM.PartyName as BillToParty, CPM.PartyName as CompanyParty, SPPM.PartyName as ShippedParty " +
                    " from YarnPOMaster YRM " +
                    "  LEFT JOIN PartyMaster SPM ON YRM.SupplierPartyID = SPM.PartyId " +
                    "  LEFT JOIN PartyMaster BPM ON YRM.BillToPartyID = BPM.PartyId" +
                    "  LEFT JOIN PartyMaster CPM ON YRM.CompanyPartyID = CPM.PartyId" +
                    "  LEFT JOIN PartyMaster SPPM ON YRM.ShippedToPartyID = SPPM.PartyId" +
                    " where YRM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " and YRM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1) " + SearchString + "" +
                    " ) as t1 ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();
                        condition.Total = Convert.ToInt32(rdr["Total"].ToString());
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }

