                LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId
                LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId
                LEFT JOIN GodownMaster GM ON YPM.GodownID = GM.GodownID
            WHERE YPM.YarnPOID = @YarnPOID";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@YarnPOID", yarnPOID);

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                YarnPOMaster item = new YarnPOMaster();

                                item.YarnPOID = Convert.ToInt32(rdr["YarnPOID"]);

                                if (rdr["DateandTime"] != DBNull.Value)
                                {
                                    item.DateandTime = Convert.ToDateTime(rdr["DateandTime"]);
                                    item.DateandTimes = item.DateandTime.ToString("dd-MM-yyyy");
                                }

                                if (rdr["PODate"] != DBNull.Value)
                                {
                                    item.PODate = Convert.ToDateTime(rdr["PODate"]);
                                    item.PODates = item.PODate.ToString("dd/MM/yyyy");
                                }

                                item.PONo = Convert.ToInt32(rdr["PONo"]);

                                item.BillToPartyName = Convert.ToString(rdr["BillToPartyName"]).ToUpper();
                                item.ShippedToPartyName = Convert.ToString(rdr["ShippedToPartyName"]).ToUpper();
                                item.SupplierPartyName = Convert.ToString(rdr["SupplierPartyName"]).ToUpper();
                                item.CompanyPartyName = Convert.ToString(rdr["CompanyPartyName"]).ToUpper();
                                item.SupplierMobileNo = Convert.ToString(rdr["SupplierMobileNo"]).ToUpper();
                                item.ShippedToBillingAddress = Convert.ToString(rdr["ShippedToBillingAddress"]).ToUpper();

                                item.GodownID = rdr["GodownID"] == DBNull.Value ? 0 : Convert.ToInt32(rdr["GodownID"]);
                                item.GodownTitle = Convert.ToString(rdr["GodownTitle"]).ToUpper();
                                item.GodownAddress = Convert.ToString(rdr["GodownAddress"]).ToUpper();

                                item.TotalQty = rdr["TotalQty"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalQty"]);
                                item.TotalRate = rdr["TotalRate"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalRate"]);
                                item.TotalAmount = rdr["TotalAmount"] == DBNull.Value ? 0 : Convert.ToDecimal(rdr["TotalAmount"]);

                                item.DeliveryTime = Convert.ToString(rdr["DeliveryTime"]).ToUpper();
                                item.PaymentCondition = Convert.ToString(rdr["PaymentCondition"]).ToUpper();
                                item.NotesRemarks = Convert.ToString(rdr["NotesRemarks"]).ToUpper();

                                listYarnPO.Add(item);
                            }
                        }
                    }

                    foreach (var item in listYarnPO)
                    {
                        string detailQuery = @"
                SELECT DISTINCT
                    YMM.YarnMaterialID,
                    YMM.YarnMaterial
                FROM YarnMaterialMaster YMM
                INNER JOIN
                (
                    SELECT
                        temp.YarnMaterialID
                    FROM
                    (
                        SELECT
                            ypd.*,
                            ISNULL(yim.Received,0) AS Received,
                            ISNULL(yim.IsComplete,0) AS IsComplete,
                            ypd.Qty - ISNULL(yim.Received,0) AS PendingQty
                        FROM YarnPODetails ypd
                        LEFT JOIN
                        (
                            SELECT
                                SUM(TotalWeight) AS Received,
                                YarnMaterialID,
                                YarnPODetailIDCompanyCode,
                                IsComplete
                            FROM YarnInwardMaster
                            WHERE YarnPOID = @YarnPOID
                              AND CompanyId =
                                (SELECT CompanyId
                                 FROM CompanyMaster
                                 WHERE is_default = 1)
                              AND FinancialYearID =
                                (SELECT FinancialYearID
                                 FROM FinancialYearMaster
                                 WHERE IsDefault = 1)
                              AND UserAccountId = @UserId
                            GROUP BY
                                YarnMaterialID,
                                YarnPODetailIDCompanyCode,
                                IsComplete
                        ) yim
                            ON ypd.YarnPODetailID = yim.YarnPODetailIDCompanyCode
                        WHERE ypd.YarnPOID = @YarnPOID
                    ) temp
                    WHERE temp.IsComplete = 0
                      AND temp.PendingQty > 0
                ) T
                ON YMM.YarnMaterialID = T.YarnMaterialID";

                        using (SqlCommand cmdDetail = new SqlCommand(detailQuery, con))
                        {
                            cmdDetail.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                            cmdDetail.Parameters.AddWithValue("@UserId", userId);

                            using (SqlDataReader rdrDetail = cmdDetail.ExecuteReader())
                            {
                                List<YarnPODetails> details = new List<YarnPODetails>();

                                while (rdrDetail.Read())
                                {
                                    YarnPODetails detail = new YarnPODetails();

                                    detail.YarnMaterialID =
                                        Convert.ToInt32(rdrDetail["YarnMaterialID"]);

                                    detail.YarnMaterial =
                                        Convert.ToString(rdrDetail["YarnMaterial"]).ToUpper();

                                    details.Add(detail);
                                }

                                item.listYarnPODetails = details;
                            }
                        }
                    }

                    response.Code = listYarnPO.Count > 0 ? 200 : 105;
                    response.Message = listYarnPO.Count > 0
                        ? "Success"
                        : "Opps! Purchase Order Not Exist.";

                    response.listYarnPOMaster = listYarnPO;
                }
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
                response.listYarnPOMaster = new List<YarnPOMaster>();
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string getJobberInwardMaster(string OutwardListNo)
        {
            try
            {
                JavaScriptSerializer js = new JavaScriptSerializer();
                js.MaxJsonLength = Int32.MaxValue;
                string conStr = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                string userId = "0";
                string challanNo = "";
                if (HttpContext.Current.Request.Cookies["UserIDs"] != null)
                {
                    userId = HttpContext.Current.Request.Cookies["UserIDs"].Value.Split('=')[1];
                }


                DataSet ds = new DataSet();
                using (SqlConnection con = new SqlConnection(conStr))
                {
                    con.Open();
                    string userRole = "";
                    int partyId = 0;

                    using (SqlCommand cmdParty = new SqlCommand("SELECT PartyId FROM UserAccountMaster WHERE UserAccountID=@UserAccountID", con))
                    {
                        cmdParty.Parameters.AddWithValue("@UserAccountID", userId);

                        object obj = cmdParty.ExecuteScalar();

                        if (obj != null && obj != DBNull.Value)
                        {
                            partyId = Convert.ToInt32(obj);
                        }
                    }
                    string partyQuery = @"
                        SELECT TOP 1
                            X.PartyId,
                            X.UserRole,
                            X.SourceType,
                            X.OutwardListNo
                        FROM
                        (
                            SELECT
                                YOM.YarnOutwardID AS OutwardID,
                             CAST(YOM.YarnOutwardID AS VARCHAR(50)) AS OutwardListNo,
                                YOM.PartyId,
                                U.UserRole,
                                'Admin' AS SourceType
                            FROM YarnOutwardMaster YOM
                            INNER JOIN UserAccountMaster U
                                ON U.PartyId = YOM.PartyId

                            UNION ALL

                            SELECT
                                JOM.JobberOutwardID AS OutwardID,
                                      CAST( JOM.OutwardListNo  AS VARCHAR(50)),
                                JOM.PartyId,
                                U.UserRole,
                                'JOBBER' AS SourceType
                            FROM JobberOutwardMaster JOM
                            INNER JOIN UserAccountMaster U
                                ON U.PartyId = JOM.PartyId
                        ) X
                        WHERE X.OutwardID = @OutwardListNo";
                    challanNo = GetNextChallanNo(partyId);
                    using (SqlCommand partyCmd = new SqlCommand(partyQuery, con))
                    {
                        partyCmd.Parameters.AddWithValue("@OutwardListNo", OutwardListNo);
                        SqlDataReader dr = partyCmd.ExecuteReader();
                        if (dr.Read())
                        {
                            userRole = dr["SourceType"].ToString();
                        }
                        dr.Close();
                    }
                    string query = "";
                    if (userRole == "Admin")
                    {
                        query = @"
                                -- MASTER
                                SELECT
                                YOM.*,
                                SPM.PartyName SupplierPartyName,
                                SPM.MobileNo SupplierMobileNo,
                                CM.CompanyName,
                                SPM.PartyPrefix,
                                CASE
                                WHEN ISNULL(SPM.ShippingAddress,'')=''
                                THEN SPM.BillingAddress
                                ELSE SPM.ShippingAddress
                                END ShippedToBillingAddress,
                                GM.GodownTitle,
                                GM.GodownAddress

                                FROM YarnOutwardMaster YOM
                                LEFT JOIN CompanyMaster CM ON CM.CompanyId=YOM.CompanyId
                                LEFT JOIN PartyMaster SPM ON SPM.PartyId=YOM.PartyId
                                LEFT JOIN GodownMaster GM ON GM.GodownID=YOM.GodownID
                                WHERE YOM.YarnOutwardID=@OutwardListNo
                                AND YOM.PartyId=@PartyId;
                                -- DETAIL
                                SELECT
                                YOD.OutwardListNo,
                                YOD.OutwardListDate,
                                PM.PartyName,
                                YMM.YarnMaterial,
                                YCM.YarnColor,
                                YOSD.BoxNo,
                                YOSD.BarcodeNo,
                                YOSD.NetWeight,
                                GM.GodownTitle,
                                GM.GodownAddress,
                                GL.LocationTitle

                                FROM YarnOutwardMaster YOD

                                LEFT JOIN YarnOutwardScanMaster YOSM
                                ON YOSM.YarnOutwardID=YOD.YarnOutwardID

                                LEFT JOIN YarnOutwardScanMasterDetails YOSD
                                ON YOSD.YarnOutwardScanID=YOSM.YarnOutwardScanID

                                LEFT JOIN PartyMaster PM
                                ON PM.PartyId=YOSD.PartyID

                                LEFT JOIN YarnMaterialMaster YMM
                                ON YMM.YarnMaterialID=YOSD.YarnMaterial

                                LEFT JOIN YarnColorMaster YCM
                                ON YCM.YarnColorID=YOSD.YarnColour

                                LEFT JOIN GodownLocationMaster GL
                                ON GL.GodownLocationID=YOSD.GodownLocationID

                                LEFT JOIN GodownMaster GM
                                ON GM.GodownID=GL.GodownID

                                WHERE YOD.YarnOutwardID=@OutwardListNo
                                AND YOD.PartyId=@PartyId

                                AND NOT EXISTS
                                (
                                SELECT 1
                                FROM JobberInwardDetail JD
                                INNER JOIN JobberInwardMaster JM
                                ON JM.JobberInwardId=JD.JobberInwardID

                                WHERE JM.ChallanNo=YOD.OutwardListNo
                                AND JM.PartyId=YOD.PartyId
                                AND JD.BarcodeNo=YOSD.BarcodeNo
                                )
                                ORDER BY YOSD.BoxNo;

                                SELECT *
                                FROM GodownMaster
                                WHERE PartyId=@PartyId
                                ORDER BY GodownTitle;
                                ";
                    }
                    else
                    {
                        query = @"
                            -- MASTER

                            SELECT
                            JOM.JobberOutwardID AS YarnOutwardID,
                            JOM.PartyId,
                            JOM.CompanyId,
                            JOM.GodownID,
                            JOM.FinancialYearID,
                            JOM.OutwardListNo,
                            JOM.OutwardListDate,
                            PM.PartyName SupplierPartyName,
                            PM.MobileNo SupplierMobileNo,
                            PM.PartyPrefix,
                            CM.CompanyName,
                            CASE
                            WHEN ISNULL(PM.ShippingAddress,'')=''
                            THEN PM.BillingAddress
                            ELSE PM.ShippingAddress
                            END ShippedToBillingAddress,
                            GM.GodownTitle,
                            GM.GodownAddress

                            FROM JobberOutwardMaster JOM

                            LEFT JOIN CompanyMaster CM
                            ON CM.CompanyId=JOM.CompanyId

                            LEFT JOIN PartyMaster PM
                            ON PM.PartyId=JOM.PartyId

                            LEFT JOIN GodownMaster GM
                            ON GM.GodownID=JOM.GodownID

                            WHERE JOM.JobberOutwardID=@OutwardListNo
                            AND JOM.PartyId=@PartyId;
                            -- DETAIL
                            SELECT
                            CAST(JOM.OutwardListNo AS VARCHAR(50)),
                            JOM.OutwardListDate,
                            PM.PartyName,
                            YMM.YarnMaterial,
                            YCM.YarnColor,
                             JOD.BoxNo,
                            JOD.BarcodeNo,
                            JOD.NetWeight,
                            GM.GodownTitle,
                            GM.GodownAddress,
                            GL.LocationTitle

                            FROM JobberOutwardMaster JOM

                            INNER JOIN JobberOutwardDetail JOD
                            ON JOD.JobberOutwardID=JOM.JobberOutwardID

                           

                            LEFT JOIN PartyMaster PM
                            ON PM.PartyId=JOM.PartyId

                            LEFT JOIN YarnMaterialMaster YMM
                            ON YMM.YarnMaterialID=JOD.YarnMaterialID

                            LEFT JOIN YarnColorMaster YCM
                            ON YCM.YarnColorID=JOD.YarnColorID

                            LEFT JOIN GodownLocationMaster GL
                            ON GL.GodownLocationID=JOM.GodownID

                            LEFT JOIN GodownMaster GM
                            ON GM.GodownID=GL.GodownID

                            WHERE JOM.JobberOutwardID=@OutwardListNo
                            AND JOM.PartyId=@PartyId
                            ORDER BY JOD.BoxNo;

                            SELECT * FROM GodownMaster
                            WHERE PartyId=@PartyId
                            ORDER BY GodownTitle;

                            ";
                    }
                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@OutwardListNo", OutwardListNo);
                        cmd.Parameters.AddWithValue("@PartyId", partyId);
                        SqlDataAdapter da = new SqlDataAdapter(cmd);
                        da.Fill(ds);
                    }

                }

                // All barcode already inward
                if (ds.Tables.Count < 2 || (ds.Tables[0].Rows.Count == 0 && ds.Tables[1].Rows.Count == 0))
                {

                    var notFoundResponse = new
                    {
                        Status = false,
                        Message = "No detail data found."
                    };
                    return js.Serialize(notFoundResponse);
                }

                if (ds.Tables[0].Rows.Count > 0 && ds.Tables[1].Rows.Count == 0)
                {
                    var alreadyAddedResponse = new
                    {
                        Status = false,
                        Message = "This Challan No already added.",
                        Master = new List<Dictionary<string, object>>(),
                        Detail = new List<Dictionary<string, object>>(),
                        Godown = new List<Dictionary<string, object>>()
                    };


                    return js.Serialize(alreadyAddedResponse);
                }

                var response = new
                {
                    Status = true,
                    Message = "",
                    ChallanNo = challanNo,
                    Master = ds.Tables.Count > 0
                        ? DataTableToList(ds.Tables[0])
                        : new List<Dictionary<string, object>>(),

                    Detail = ds.Tables.Count > 1
                        ? DataTableToList(ds.Tables[1])
                        : new List<Dictionary<string, object>>(),

                    Godown = ds.Tables.Count > 2
                        ? DataTableToList(ds.Tables[2])
                        : new List<Dictionary<string, object>>()
                };

                return js.Serialize(response);
            }
            catch (Exception ex)
            {
                JavaScriptSerializer js = new JavaScriptSerializer();

                return js.Serialize(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }
        public string GetNextChallanNo(int partyId)
        {
            string challanNo = "";

            string conStr = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(conStr))
            {
                con.Open();

                string query = @"
        SELECT
            ISNULL(PM.PartyPrefix,'JOB') +
            CAST(
                ISNULL(
                    MAX(
                        TRY_CAST(
                            REPLACE(JIM.ChallanNo, ISNULL(PM.PartyPrefix,'JOB'), '')
                        AS INT)
                    ),0
                ) + 1
            AS VARCHAR(20)) AS ChallanNo
        FROM PartyMaster PM
        LEFT JOIN JobberInwardMaster JIM
            ON PM.PartyId = JIM.PartyId
        WHERE PM.PartyId = @PartyId
        GROUP BY PM.PartyPrefix";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@PartyId", partyId);

                    object obj = cmd.ExecuteScalar();

                    if (obj != null)
                        challanNo = obj.ToString();
                }
            }

            return challanNo;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberInwardList(int IsComplete)
        {
            try
            {
                int PartyId = GetPartyId();

                DataTable dt = new DataTable();

                using (SqlConnection con = new SqlConnection(
                    ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
                {
                    string query = @"
                        ;WITH LatestJobberInward AS
                        (
                            SELECT *
                            FROM
                            (
                                SELECT *,
                                       ROW_NUMBER() OVER
                                       (
                                           PARTITION BY JobWorkOutwardId
                                           ORDER BY JobberInwardId DESC
                                       ) AS RN
                                FROM JobberInwardMaster
                            ) X
                            WHERE RN = 1
                        )

                        --=========================================================
                        -- ADMIN OUTWARD
                        --=========================================================
                        SELECT
                            'ADMIN' AS SourceType,

                            CAST(ISNULL(UM.UserAccountId, 0) AS VARCHAR(20))
                            + '|' +
                            CAST(ISNULL(YOM.YarnOutwardID, 0) AS VARCHAR(20))
                            + '|' +
                            CAST(ISNULL(PM.PartyId, 0) AS VARCHAR(20)) AS GeneratedLink,

                            YOM.YarnOutwardID,

                            -- Jobber Inward ID
                            LI.JobberInwardId AS JobberInwardId,

                            CAST(YOM.OutwardListNo AS VARCHAR(50)) AS ChallanNo,

                            CONVERT(VARCHAR(10), YOSM.ChallanDate, 103) AS AssignDate,

                            CONVERT(VARCHAR(10), LI.DateAndTime, 103) AS ReceivedDate,

                            PM.PartyName,

                            STRING_AGG(
                                ISNULL(YMM.YarnMaterial, ''),
                                ', '
                            ) AS YarnMaterial,

                            STRING_AGG(
                                ISNULL(YCM.YarnColor, ''),
                                ', '
                            ) AS YarnColor,

                            STRING_AGG(
                                CAST(ISNULL(YOSD.NetWeight, 0) AS VARCHAR(20)),
                                ', '
                            ) AS NetWeight,

                            COUNT(DISTINCT YOSD.BarcodeNo) AS TotalBox,

                            SUM(ISNULL(YOSD.NetWeight, 0)) AS TotalWeight,

                            ISNULL(LI.PendingWeight, 0) AS PendingWeight,

                            ISNULL(LI.TotalWeight, 0)
                                - ISNULL(LI.PendingWeight, 0) AS ReceivedWeight,

                            CASE
                                WHEN LI.JobberInwardId IS NOT NULL
                                     AND ISNULL(LI.PendingWeight, 0) = 0
                                THEN 'Accepted'
                                ELSE 'Pending'
                            END AS StatusName

                        FROM YarnOutwardMaster YOM

                        INNER JOIN PartyMaster PM
                            ON PM.PartyId = YOM.PartyId

                        LEFT JOIN UserAccountMaster UM
                            ON UM.PartyId = PM.PartyId

                        INNER JOIN YarnOutwardScanMaster YOSM
                            ON YOSM.YarnOutwardID = YOM.YarnOutwardID

                        INNER JOIN YarnOutwardScanMasterDetails YOSD
                            ON YOSD.YarnOutwardScanID = YOSM.YarnOutwardScanID

                        LEFT JOIN YarnMaterialMaster YMM
                            ON YMM.YarnMaterialID = YOSD.YarnMaterial

                        LEFT JOIN YarnColorMaster YCM
                            ON YCM.YarnColorID = YOSD.YarnColour

                        LEFT JOIN LatestJobberInward LI
                            ON LI.JobWorkOutwardId = YOM.YarnOutwardID

                        WHERE
                            (@PartyId = 0 OR YOM.PartyId = @PartyId)

                        GROUP BY
                            UM.UserAccountId,
                            PM.PartyId,
                            YOM.YarnOutwardID,
                            YOM.OutwardListNo,
                            YOSM.ChallanDate,
                            LI.DateAndTime,
                            PM.PartyName,
                            LI.JobberInwardId,
                            LI.TotalWeight,
                            LI.PendingWeight

                        HAVING
                        (
                            @IsComplete = 0
                            AND
                            (
                                LI.JobberInwardId IS NULL
                                OR ISNULL(LI.PendingWeight, 0) > 0
                            )
                        )
                        OR
                        (
                            @IsComplete = 1
                            AND
                            LI.JobberInwardId IS NOT NULL
                            AND ISNULL(LI.PendingWeight, 0) = 0
                        )

                        UNION ALL

                        --=========================================================
                        -- JOBBER OUTWARD
                        --=========================================================
                        SELECT

                            'JOBBER' AS SourceType,

                            CAST(ISNULL(UM.UserAccountId, 0) AS VARCHAR(20))
                            + '|'
                            + CAST(ISNULL(JOM.JobberOutwardID, 0) AS VARCHAR(20))
                            + '|'
                            + CAST(ISNULL(PM.PartyId, 0) AS VARCHAR(20)) AS GeneratedLink,

                            JOM.JobberOutwardID AS YarnOutwardID,

                            -- Jobber Inward ID
                            JIM.JobberInwardId AS JobberInwardId,

                            CAST(JOM.OutwardListNo AS VARCHAR(50)) AS ChallanNo,

                            CONVERT(VARCHAR(10), JOM.OutwardListDate, 103) AS AssignDate,

                            CONVERT(VARCHAR(10), JIM.DateAndTime, 103) AS ReceivedDate,

                            PM.PartyName,

                            STRING_AGG(
                                ISNULL(YMM.YarnMaterial, ''),
                                ', '
                            ) AS YarnMaterial,

                            STRING_AGG(
                                ISNULL(YCM.YarnColor, ''),
                                ', '
                            ) AS YarnColor,

                            STRING_AGG(
                                CAST(ISNULL(JOD.NoOfBox, 0) AS VARCHAR(20)),
                                ', '
                            ) AS NetWeight,

                            SUM(ISNULL(JOD.NoOfBox, 0)) AS TotalBox,

                            SUM(ISNULL(JOD.NoOfBox, 0)) AS TotalWeight,

                            CASE
                                WHEN MAX(
                                    CASE
                                        WHEN JIM.PartyId = JOM.PartyId
                                        THEN 1
                                        ELSE 0
                                    END
                                ) = 1
                                THEN 0
                                ELSE SUM(ISNULL(JOD.NoOfBox, 0))
                            END AS PendingWeight,

                            CASE
                                WHEN MAX(
                                    CASE
                                        WHEN JIM.PartyId = JOM.PartyId
                                        THEN 1
                                        ELSE 0
                                    END
                                ) = 1
                                THEN SUM(ISNULL(JOD.NoOfBox, 0))
                                ELSE 0
                            END AS ReceivedWeight,

                            CASE
                                WHEN MAX(
                                    CASE
                                        WHEN JIM.PartyId = JOM.PartyId
                                        THEN 1
                                        ELSE 0
                                    END
                                ) = 1
                                THEN 'Accepted'
                                ELSE 'Pending'
                            END AS StatusName

                        FROM JobberOutwardMaster JOM

                        INNER JOIN JobberOutwardDetail JOD
                            ON JOD.JobberOutwardID = JOM.JobberOutwardID

                        INNER JOIN PartyMaster PM
                            ON PM.PartyId = JOM.PartyId

                        LEFT JOIN UserAccountMaster UM
                            ON UM.PartyId = PM.PartyId

                        LEFT JOIN YarnMaterialMaster YMM
                            ON YMM.YarnMaterialID = JOD.YarnMaterialID

                        LEFT JOIN YarnColorMaster YCM
                            ON YCM.YarnColorID = JOD.YarnColorID

                        LEFT JOIN LatestJobberInward JIM
                            ON JIM.JobWorkOutwardId = JOM.JobberOutwardID

                        WHERE
                            (@PartyId = 0 OR JOM.PartyId = @PartyId)

                        GROUP BY
                            UM.UserAccountId,
                            PM.PartyId,
                            JOM.JobberOutwardID,
                            JOM.OutwardListNo,
                            JOM.OutwardListDate,
                            JOM.PartyId,
                            PM.PartyName,
                            JIM.DateAndTime,
                            JIM.JobberInwardId

                        HAVING
                        (
                            @IsComplete = 0
                            AND
                            MAX(
                                CASE
                                    WHEN JIM.PartyId = JOM.PartyId
                                    THEN 1
                                    ELSE 0
                                END
                            ) = 0
                        )
                        OR
                        (
                            @IsComplete = 1
                            AND
                            MAX(
                                CASE
                                    WHEN JIM.PartyId = JOM.PartyId
                                    THEN 1
                                    ELSE 0
                                END
                            ) = 1
                        )";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@IsComplete", IsComplete);
                        cmd.Parameters.AddWithValue("@PartyId", PartyId);

                        SqlDataAdapter da = new SqlDataAdapter(cmd);

                        da.Fill(dt);

                        // Encrypt GeneratedLink only
                        foreach (DataRow row in dt.Rows)
                        {
                            row["GeneratedLink"] =
                                GetEncryptedLink(
                                    row["GeneratedLink"].ToString()
                                );
                        }
                    }
                }

                return JsonConvert.SerializeObject(dt);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string SaveJobberInward(JobberInwardMasterModel obj)
        {
            SqlConnection con = null;
            SqlTransaction tran = null;

            try
            {
                string conStr = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                con = new SqlConnection(conStr);
                con.Open();

                tran = con.BeginTransaction();

                long JobberInwardId = 0;

                decimal totalWeight = 0;
                decimal alreadyReceivedWeight = 0;
                decimal currentWeight = 0;
                decimal pendingWeight = 0;

                #region Weight Calculation

                using (SqlCommand cmdWeight = new SqlCommand(@"
            SELECT ISNULL(TotalWeight,0)  FROM YarnOutwardScanMaster WHERE YarnOutwardID = @YarnOutwardID", con, tran))
                {
                    cmdWeight.Parameters.AddWithValue("@YarnOutwardID", obj.JobWorkOutwardId);
                    object result = cmdWeight.ExecuteScalar();
                    if (result != null) totalWeight = Convert.ToDecimal(result);
                }

                using (SqlCommand cmdReceived = new SqlCommand(@"
            SELECT ISNULL(SUM(JID.NetWeight),0)  FROM JobberInwardDetail JID
