            SELECT @Prefix = ISNULL(PartyPrefix, 'CH') FROM PartyMaster WHERE PartyId = @PartyId;

            -- 2. Find the last generated ChallanNo for this prefix using UPDLOCK for thread safety
            DECLARE @MaxChallan NVARCHAR(50);
            SELECT TOP 1 @MaxChallan = ChallanNo 
            FROM JobberInwardMaster WITH (UPDLOCK) 
            WHERE ChallanNo LIKE @Prefix + '%' 
            ORDER BY CAST(SUBSTRING(ChallanNo, LEN(@Prefix) + 1, LEN(ChallanNo)) AS INT) DESC;

            -- 3. Increment and pad with zeros
            IF @MaxChallan IS NULL
            BEGIN
                SELECT @Prefix + '01';
            END
            ELSE
            BEGIN
                DECLARE @NextNum INT = CAST(SUBSTRING(@MaxChallan, LEN(@Prefix) + 1, LEN(@MaxChallan)) AS INT) + 1;
                SELECT @Prefix + FORMAT(@NextNum, '00'); -- Ensures output is '01', '02', '10', etc.
            END
        ";

