                    cmd.Parameters.AddWithValue("@POPendingWeight", pendingWeight);
                    cmd.Parameters.AddWithValue("@GodownID", obj.GodownID);
                    cmd.Parameters.AddWithValue("@PhotoOfInward", string.IsNullOrEmpty(obj.PhotoOfInward) ? "" : obj.PhotoOfInward);
                    cmd.Parameters.AddWithValue("@CompanyId", Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);
