                int.TryParse(HttpContext.Current.Request["YarnColorID"], out YarnColorID);

                string CompanyCode = HttpContext.Current.Request["CompanyCode"] ?? "";

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand())
                    {
                        cmd.Connection = con;
                        cmd.CommandType = CommandType.Text;

                        cmd.CommandText = @"
                   -- 1. Declare Parameters (Set default values or pass them dynamically)
DECLARE @DefaultCompanyID INT;       
-- 2. Fetch Default Company
SELECT TOP 1 @DefaultCompanyID = CompanyId       
FROM CompanyMaster       
WHERE is_default = 1; 

-- 3. CTEs for Inward and Outward Calculation
;WITH InwardDetails AS (         
    SELECT            
        YIM.YarnMaterialID,          
        YIM.YarnColorID,          
        YIM.YarnPOID,      
        YPM.BillToPartyID,          
        YPM.ShippedToPartyID,          
        YID.YarnInterchangeID AS GodownLocationID,          
        COUNT(*) AS InwardBoxes,      
        SUM(ISNULL(YID.NetWeight, 0)) AS InwardWeight          
    FROM YarnInwardMaster YIM          
    INNER JOIN YarnPOMaster YPM ON YIM.YarnPOID = YPM.YarnPOID          
    INNER JOIN YarnInwardDetail YID ON YIM.YarnInwardID = YID.YarnInwardID          
    INNER JOIN GodownLocationMaster GLM ON YID.YarnInterchangeID = GLM.GodownLocationID          
    GROUP BY        
        YIM.YarnMaterialID,        
        YIM.YarnColorID,        
        YIM.YarnPOID,      
        YPM.BillToPartyID,        
        YPM.ShippedToPartyID,        
        YID.YarnInterchangeID          
),     
OutwardDetails AS (         
    SELECT            
        YOD.BillToPartyID,          
        YOD.YarnMaterialID,          
        YOD.YarnColorID,          
        YOD.GodownLocationID,      
        SUM(ISNULL(YOD.NoOfBox, 0)) AS OutwardBoxes          
    FROM YarnOutwardDetail YOD             
    INNER JOIN YarnOutwardMaster YOM        
        ON YOD.YarnOutwardID = YOM.YarnOutwardID          
    WHERE YOM.CompanyId = @DefaultCompanyID          
    GROUP BY      
        YOD.BillToPartyID,    
        YOD.YarnMaterialID,    
        YOD.YarnColorID,    
        YOD.GodownLocationID             
),     
FinalResult AS (         
    SELECT            
        BillTo.PartyName AS CompanyName,          
        ShippedTo.PartyName AS PartyName,          
        YMM.YarnMaterial,          
        YCM.YarnColor,          
        YPD.CompanyCode AS YarnColorCode,          
        GM.GodownTitle,          
        GL.LocationTitle,          
        ID.YarnMaterialID,  -- Included for filtering
        ID.YarnColorID,     -- Included for filtering
        GM.GodownID,        -- Included for filtering

        -- ✅ SAFE BOX CALCULATION (NO NEGATIVE)    
        CASE     
            WHEN (ID.InwardBoxes - ISNULL(OD.OutwardBoxes, 0)) < 0     
            THEN 0    
            ELSE (ID.InwardBoxes - ISNULL(OD.OutwardBoxes, 0))    
        END AS NoOfBoxes,          

        -- ✅ SAFE NET WEIGHT (NO NEGATIVE)    
        CAST(    
            CASE     
                WHEN (ID.InwardBoxes - ISNULL(OD.OutwardBoxes, 0)) <= 0     
                THEN 0    
                WHEN ID.InwardBoxes > 0            
                THEN (ID.InwardWeight / ID.InwardBoxes)     
                   * (ID.InwardBoxes - ISNULL(OD.OutwardBoxes, 0))    
                ELSE 0    
            END            
        AS DECIMAL(18,2)) AS NetWeigh          

    FROM InwardDetails ID          
    LEFT JOIN OutwardDetails OD        
        ON ID.YarnMaterialID = OD.YarnMaterialID            
       AND ID.YarnColorID = OD.YarnColorID            
       AND ID.GodownLocationID = OD.GodownLocationID          
    LEFT JOIN PartyMaster BillTo        
        ON BillTo.PartyID = ID.BillToPartyID          
    LEFT JOIN PartyMaster ShippedTo        
        ON ShippedTo.PartyID = ID.ShippedToPartyID          
    LEFT JOIN YarnMaterialMaster YMM        
        ON ID.YarnMaterialID = YMM.YarnMaterialID          
    LEFT JOIN YarnColorMaster YCM        
        ON ID.YarnColorID = YCM.YarnColorID          
    LEFT JOIN YarnPODetails YPD        
        ON YPD.YarnPOID = ID.YarnPOID      
       AND YPD.YarnMaterialID = ID.YarnMaterialID      
       AND YPD.YarnColorID = ID.YarnColorID          
    LEFT JOIN GodownLocationMaster GL        
        ON ID.GodownLocationID = GL.GodownLocationID          
    LEFT JOIN GodownMaster GM        
        ON GL.GodownID = GM.GodownID          
)          

------------------------------------------------------------    
-- ✅ FINAL SELECT WITH CORRECT FILTERS    
------------------------------------------------------------    
SELECT 
    CompanyName,          
    PartyName,          
    YarnMaterial,          
    YarnColor,          
    YarnColorCode,          
    GodownTitle,          
    LocationTitle,          
    NoOfBoxes,
    NetWeigh
FROM FinalResult            
WHERE NoOfBoxes > 0 
 AND GodownID = @GodownID
  AND (@YarnMaterialID = 0 OR YarnMaterialID = @YarnMaterialID)    
 AND (@YarnColorID = 0 OR YarnColorID = @YarnColorID)    
  AND (@CompanyCode = '' OR ISNULL(YarnColorCode, '') = @CompanyCode)
ORDER BY 
    LocationTitle";

                        cmd.Parameters.Add("@GodownID", SqlDbType.Int).Value = GodownID;
                        cmd.Parameters.Add("@YarnMaterialID", SqlDbType.Int).Value = YarnMaterialID;
                        cmd.Parameters.Add("@YarnColorID", SqlDbType.Int).Value = YarnColorID;
                        cmd.Parameters.Add("@CompanyCode", SqlDbType.VarChar, 50).Value = CompanyCode;

                        con.Open();

                        using (SqlDataReader rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                GodownMaster obj = new GodownMaster();

                                obj.BoxNo = rdr["NoOfBoxes"].ToString();
                                obj.NetWeight = rdr["NetWeigh"].ToString();
                                obj.LocationTitle = rdr["LocationTitle"].ToString();

