                ilist.YarnInwardDetailID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.YarnInwardDetailID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnInwardDetailID"])));
            }

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText =
                    @"select YID.YarnInwardDetailID, YIM.YarnInwardID,
                                    YIM.YarnColorID, YCM.YarnColorCode, YCM.YarnColor,
                                    YID.BoxNo, YID.BarcodeNo, YID.NetWeight, 
                                    YIM.CompanyId, CM.CompanyName,
                                    YIM.YarnMaterialID, YMM.YarnMaterial
                                    from YarnInwardDetail YID
                                    LEFT JOIN YarnInwardMaster YIM ON YID.YarnInwardID = YIM.YarnInwardID
                                    LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
                                    LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN CompanyMaster CM ON YIM.CompanyId = CM.CompanyId
                                    where YID.YarnInwardDetailID = " + ilist.YarnInwardDetailID + @"";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnInwardMaster condition = new YarnInwardMaster();
                        condition.YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"].ToString());
                        condition.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.CompanyId = Convert.ToInt32(rdr["CompanyId"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());

                        condition.YarnColorCode = rdr["YarnColorCode"].ToString();
                        condition.YarnColor = rdr["YarnColor"].ToString();

                        condition.BoxNo = rdr["BoxNo"].ToString();
                        condition.BarcodeNo = rdr["BarcodeNo"].ToString();
                        condition.NetWeight = Convert.ToDecimal(rdr["NetWeight"].ToString());
                        condition.CompanyName = rdr["CompanyName"].ToString();
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString();



                        listYarnInwardMaster.Add(condition);

                    }

                    listYarnInwardMasterR.Code = 200;
                    listYarnInwardMasterR.Message = "Success";
                    listYarnInwardMasterR.listYarnInwardMaster = listYarnInwardMaster;
                }
                else
                {
                    listYarnInwardMasterR.Code = 105;
                    listYarnInwardMasterR.Message = "Opps! Purchase Order Not Exist.";
