                cmd.CommandText = @"
SELECT
    T1.*,
    CASE
        WHEN ISNULL(YTCM.YarnInwardDetailID, 0) = 0 THEN 'NO'
        ELSE 'YES'
    END AS MOVEBOXORNOT
FROM
(
    -----------------------------------------------------------------------
    --Records which are never interchanged
    ---------------------------------------------------------------------- -
    SELECT
        YID.YarnInwardDetailID,
        YID.DateAndTime,
        YID.BoxNo,
        YID.NetWeight,
        YID.BarcodeNo,
        YID.GodownLocationID,
        YID.YarnInwardID,
        YID.UserAccountId,
        GLM.LocationTitle,
        YIM.YarnMaterialID,
        YIM.YarnColorID,
        YCM.YarnColor,
        YIM.GodownID,
        YIM.YarnPOID,
        YIM.TotalWeight,
        YMM.YarnMaterial,
        GM.GodownTitle,
        YPM.PONo,
        PM.PartyName,
        YPD.YarnPODetailID,
        YPD.CompanyCode
    FROM YarnInwardDetail YID
    LEFT JOIN GodownLocationMaster GLM
        ON YID.GodownLocationID = GLM.GodownLocationID
    LEFT JOIN YarnInwardMaster YIM
        ON YID.YarnInwardID = YIM.YarnInwardID
    LEFT JOIN YarnMaterialMaster YMM
        ON YIM.YarnMaterialID = YMM.YarnMaterialID
    LEFT JOIN YarnColorMaster YCM
        ON YIM.YarnColorID = YCM.YarnColorID
    LEFT JOIN GodownMaster GM
        ON YIM.GodownID = GM.GodownID
    LEFT JOIN YarnPOMaster YPM
        ON YIM.YarnPOID = YPM.YarnPOID
    LEFT JOIN PartyMaster PM
        ON YPM.BillToPartyID = PM.PartyId
    LEFT JOIN YarnPODetails YPD
        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID
    WHERE YID.YarnInwardDetailID NOT IN
    (
        SELECT DISTINCT YarnInwardDetailID
        FROM YarnInterchangeMaster
    )

    UNION ALL

    ---------------------------------------------------------------------- -
    --Latest Interchange Record
    ---------------------------------------------------------------------- -
    SELECT
        T.YarnInwardDetailID,
        T.DateAndTime,
        YID.BoxNo,
        YID.NetWeight,
        YID.BarcodeNo,
        T.GodownLocationID,
        YID.YarnInwardID,
        T.UserAccountId,
        GLM.LocationTitle,
        T.YarnMaterialID,
        T.YarnColorID,
        YCM.YarnColor,
        T.GodownID,
        T.YarnPOID,
        YIM.TotalWeight,
        YMM.YarnMaterial,
        GM.GodownTitle,
        YPM.PONo,
        PM.PartyName,
        YPD.YarnPODetailID,
        YPD.CompanyCode
    FROM
    (
        SELECT *,
               ROW_NUMBER() OVER
               (
                    PARTITION BY YarnInwardDetailID
                    ORDER BY YarnInterchangeID DESC
               ) AS rn
        FROM YarnInterchangeMaster
    ) T
    LEFT JOIN YarnInwardDetail YID
        ON T.YarnInwardDetailID = YID.YarnInwardDetailID
    LEFT JOIN GodownLocationMaster GLM
        ON T.GodownLocationID = GLM.GodownLocationID
    LEFT JOIN YarnInwardMaster YIM
        ON YID.YarnInwardID = YIM.YarnInwardID
    LEFT JOIN YarnMaterialMaster YMM
        ON T.YarnMaterialID = YMM.YarnMaterialID
    LEFT JOIN YarnColorMaster YCM
        ON T.YarnColorID = YCM.YarnColorID
    LEFT JOIN GodownMaster GM
        ON T.GodownID = GM.GodownID
    LEFT JOIN YarnPOMaster YPM
        ON T.YarnPOID = YPM.YarnPOID
    LEFT JOIN PartyMaster PM
        ON YPM.BillToPartyID = PM.PartyId
    LEFT JOIN YarnPODetails YPD
        ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID
    WHERE T.rn = 1
) T1

LEFT JOIN
(
