        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnInterChangeLedgerTable()
        {

            var request = HttpContext.Current.Request;
            YarnInterChangeResponce listYarnInterChangeResponce = new YarnInterChangeResponce();

            List<YarnInterChangeMaster> listYarnInterChangeMaster = new List<YarnInterChangeMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            YarnInterChangeResponce ilist = new YarnInterChangeResponce();
            ilist.YarnInwardDetailID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnInwardDetailID"]);


            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                //yarn materail
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"
                                    select YICM.YarnInterchangeID, YICM.YarnInwardDetailID, YICM.DateAndTime, YID.BoxNo, YID.NetWeight,
                                    YICM.YarnMaterialID, YMM.YarnMaterial, 
                                    YICM.YarnColorID, YCM.YarnColorCode, YCM.YarnColor,
                                    YICM.GodownID, GM.GodownTitle, GM.GodownAddress,
                                    YICM.GodownLocationID, GLM.LocationTitle
                                    from YarnInterchangeMaster	YICM
                                    LEFT JOIN YarnInwardDetail YID ON YICM.YarnInwardDetailID =  YID.YarnInwardDetailID
                                    LEFT JOIN YarnMaterialMaster YMM ON YICM.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON YICM.YarnColorID = YCM.YarnColorID
                                    LEFT JOIN YarnPODetails YPD ON YICM.YarnPODetailID = YPD.YarnPODetailID
                                    LEFT JOIN GodownMaster GM ON YICM.GodownID = GM.GodownID
                                    LEFT JOIN GodownLocationMaster GLM ON YICM.GodownLocationID = GLM.GodownLocationID
                                    WHERE YICM.YarnInwardDetailID = " + ilist.YarnInwardDetailID + @"
                                    ORDER BY YICM.YarnInterchangeID
                                ";

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();


                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnInterChangeMaster condition = new YarnInterChangeMaster();
                        condition.YarnInterchangeID = Convert.ToInt32(rdr["YarnInterchangeID"].ToString());
                        condition.YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"].ToString());
                        condition.DateAndTimes = Convert.ToDateTime(rdr["DateAndTime"].ToString()).ToString("dd-MM-yyyy HH:mm:ss");
                        condition.BoxNo = rdr["BoxNo"].ToString().ToUpper();
                        condition.NetWeight = Convert.ToDecimal(rdr["NetWeight"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString();
                        condition.YarnColor = rdr["YarnColor"].ToString();
                        condition.GodownID = Convert.ToInt32(rdr["GodownID"].ToString());
                        condition.GodownTitle = rdr["GodownTitle"].ToString();
                        condition.GodownAddress = rdr["GodownAddress"].ToString();
                        condition.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"].ToString());
                        condition.LocationTitle = rdr["LocationTitle"].ToString();
                        listYarnInterChangeMaster.Add(condition);
                    }

                }


                listYarnInterChangeResponce.Code = 200;
                listYarnInterChangeResponce.Message = "Success";
                listYarnInterChangeResponce.listYarnInterChangeMaster = listYarnInterChangeMaster;


                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnInterChangeResponce));
            return;


        }

