                        condition.CompanyName = rdr3["PartyName"].ToString().ToUpper();
                        condition.YarnMaterialID = Convert.ToInt32(rdr3["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr3["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr3["YarnColorID"].ToString());
                        condition.YarnColor = rdr3["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr3["YarnColorCode"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr3["Stock"].ToString());
                        condition.GodownLocationID = Convert.ToInt32(rdr3["GodownLocationID"].ToString());
                        condition.LocationTitle = rdr3["LocationTitle"].ToString();
                        condition.GodownID = Convert.ToInt32(rdr3["GodownID"].ToString());
                        listTotalExistingOutwardStockArray.Add(condition);
                    }

                }

                rdr3.Close();

                listYarnOutwardMasterResponce.Code = 200;
                listYarnOutwardMasterResponce.Message = "Success";
                listYarnOutwardMasterResponce.listTotalInwardStockArray = listTotalInwardStockArray;
                listYarnOutwardMasterResponce.listTotalOutwardStockArray = listTotalOutwardStockArray;
                listYarnOutwardMasterResponce.listTotalExistingOutwardStockArray = listTotalExistingOutwardStockArray;
                //listYarnOutwardMasterResponce.YarnOutwardcondition = YarnOutwardcondition;
                listYarnOutwardMasterResponce.listPartyMaster = listPartyMaster;
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnOutwardMasterResponce));
            return;


        }
