            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"select t1.*, GM.GodownTitle, GLM.LocationTitle, PM.PartyName as 'CompanyName', 
                                    YMM.YarnMaterial, YCM.YarnColor, YCM.YarnColorCode
                                    from(
	                                    SELECT
		                                    GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID,  ISNULL(SUM(InputNoOfBox),0) as InputNoOfBox
	                                    FROM (
		                                    SELECT * FROM (VALUES
			                                    " + ilist.GodownInputBoxss + @"
		                                    ) AS V ( GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
	                                    ) X 
                                        GROUP BY GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID
                                    ) as t1
                                    LEFT JOIN GodownLocationMaster GLM ON t1.GodownLocationID = GLM.GodownLocationID
                                    LEFT JOIN GodownMaster GM ON GLM.GodownID = GM.GodownID
                                    LEFT JOIN PartyMaster PM ON t1.BillToPartyID = PM.PartyId
                                    LEFT JOIN YarnMaterialMaster YMM ON t1.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON t1.YarnColorID = YCM.YarnColorID
                                    ORDER BY t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID, t1.GodownLocationID;
                                    ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
