        public decimal SafeDecimal(object val)
        {
            decimal result;
            return val == DBNull.Value || !decimal.TryParse(val.ToString(), out result)
                ? 0
                : result;
        }
        public int SafeInt(object val)
        {
            int result;
            return val == DBNull.Value || !int.TryParse(val.ToString(), out result)
                ? 0
                : result;
        }
