                string partyQuery = @"SELECT PartyId FROM UserAccountMaster WHERE UserAccountId = @UserAccountId";
                using (SqlCommand cmd = new SqlCommand(partyQuery, con))
                {
                    cmd.Parameters.AddWithValue("@UserAccountId", userId);
                    object result = cmd.ExecuteScalar();
                    if (result != null && result != DBNull.Value)
                    {
                        PartyId = Convert.ToInt32(result);
                    }
                }
            }
            if (PartyId > 0)
            {
                ilist.BillToPartyID = PartyId;
            }
            string CompanyName = "";
            if (ilist.BillToPartyID > 0)
            {
                CompanyName = " AND t1.PartyId = " + ilist.BillToPartyID + " ";
            }
            string YarnMaterial = "";
            if (ilist.YarnMaterialID > 0)
            {
                YarnMaterial = " AND t1.YarnMaterialID = " + ilist.YarnMaterialID + " ";
            }
            string YarnColor = "";
            if (ilist.YarnColorID > 0)
            {
                YarnColor = " AND t1.YarnColorID = " + ilist.YarnColorID + " ";
            }
            string YarnInwardDetails = "";
            //if (ilist.YarnInwardDetailIDss != "")
            //{
            //    YarnInwardDetails = " and YarnInwardDetailID not in (" + ilist.YarnInwardDetailIDss + ") ";
            //}        
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;



                if (ilist.SiftGodownLocationId != "")
                {

                    cmd.CommandText = @"select (t2.Stock) AS Stock, 
                                        t2.BillToPartyID, t2.CompanyName, t2.YarnMaterialID,
                                        t2.YarnMaterial, t2.YarnColorID, t2.YarnColor,
                                        t2.YarnColorCode from
                                        (
	                                        select CASE 
		                                        WHEN (t1.Stock - ISNULL(t2.Stock,0)) < 0 THEN 0
		                                        ELSE (t1.Stock - ISNULL(t2.Stock,0))
	                                        END AS Stock, t1.BillToPartyID, t1.CompanyName, t1.YarnMaterialID, t1.YarnMaterial, 
	                                        t1.YarnColorID, t1.YarnColor,
	                                        t1.YarnColorCode from 
	                                        (
		                                        select ISNULL(SUM(Stock),0) as Stock, t1.BillToPartyID, t1.CompanyName,
		                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode from
		                                        (
			                                        select  YIM.YarnInwardID, YIM.YarnPOID, YPM.BillToPartyID, YPM.PartyName as 'CompanyName',
			                                        YIM.YarnMaterialID, YMM.YarnMaterial, YIM.YarnColorID, YCM.YarnColor, YCM.YarnColorCode , YIDD.Stock
			                                        from YarnInwardMaster YIM
			                                        LEFT JOIN 
			                                        (
				                                        select YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName from YarnPOMaster YPM
				                                        LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
			                                        )YPM ON YIM.YarnPOID = YPM.YarnPOID
			                                        LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
			                                        LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
			                                        LEFT JOIN 
			                                        (
				                                        select COUNT(*) as Stock, YarnInwardID from YarnInwardDetail 
						                                        where GodownLocationID in (select GodownLocationID from GodownLocationMaster where GodownID = '" + ilist.GodownID + @"')
						                                        group by YarnInwardID
			                                        ) YIDD ON YIM.YarnInwardID = YIDD.YarnInwardID
		                                        ) as t1
		                                        where (1=1) " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"   
		                                        group by t1.BillToPartyID, t1.CompanyName,
		                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode  
	                                        ) as t1 
	                                        LEFT JOIN 
	                                        (
		                                        select SUM(t1.InputNoOfBox) as Stock,
		                                        t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
		                                        from
		                                        (
			                                        SELECT
				                                        GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID,  ISNULL(SUM(InputNoOfBox),0) as InputNoOfBox
			                                        FROM (
				                                        SELECT * FROM (VALUES
					                                        " + ilist.SiftGodownLocationId + @"
				                                        ) AS V ( GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
			                                        ) X 
			                                        GROUP BY GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID
		                                        ) as t1
		                                        group by t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
	                                        ) as t2
	                                        ON  t1.BillToPartyID = t2.BillToPartyID
	                                        AND t1.YarnMaterialID = t2.YarnMaterialID
	                                        AND t1.YarnColorID = t2.YarnColorID
                                        ) as t2
                                        WHERE t2.Stock > 0";


                }
                else
                {

                    cmd.CommandText = @"
                                  SELECT
                                (t1.Stock - ISNULL(JOD.Stock, 0)) AS Stock,
                                t1.PartyId AS BillToPartyID,
                                t1.CompanyName,
                                t1.YarnMaterialID,
                                t1.YarnMaterial,
                                t1.YarnColorID,
                                t1.YarnColor,
                                t1.YarnColorCode
                            FROM
                            (
                                SELECT
                                    ISNULL(SUM(t1.Stock),0) AS Stock,
                                    t1.PartyId,
                                    t1.CompanyName,
                                    t1.YarnMaterialID,
                                    t1.YarnMaterial,
                                    t1.YarnColorID,
                                    t1.YarnColor,
                                    t1.YarnColorCode
                                FROM
                                (
                                    SELECT YIM.YarnInwardID,YIM.YarnPOID,PM.PartyId,PM.PartyName AS CompanyName,YIM.YarnMaterialID,YMM.YarnMaterial,YIM.YarnColorID,YCM.YarnColor,YCM.YarnColorCode,
                                       JIDD.Stock  
			                            FROM JobberInwardDetail JID
                                    LEFT JOIN JobberInwardMaster JIM ON JIM.JobberInwardId = JID.JobberInwardId
                                    LEFT JOIN PartyMaster PM  ON PM.PartyId = JIM.PartyId
                                    LEFT JOIN YarnInwardDetail YID ON JID.BarcodeNo = YID.BarcodeNo
                                    LEFT JOIN YarnInwardMaster YIM ON YID.YarnInwardID = YIM.YarnInwardID
                                    LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
                                    LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
                                    LEFT JOIN (SELECT  COUNT(*) AS Stock, BarcodeNo FROM JobberInwardDetail 
		                             " + YarnInwardDetails + @" 
		                            GROUP BY BarcodeNo ) JIDD  ON JID.BarcodeNo = JIDD.BarcodeNo
                                ) t1  where (1=1) " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"
                                GROUP BY
                                    t1.PartyId,
                                    t1.CompanyName,
                                    t1.YarnMaterialID,
                                    t1.YarnMaterial,
                                    t1.YarnColorID,
                                    t1.YarnColor,
                                    t1.YarnColorCode
                            ) t1
                            LEFT JOIN
                            ( SELECT SUM(JOD.NoOfBox) AS Stock,JOM.PartyId,JOD.YarnMaterialID,JOD.YarnColorID FROM JobberOutwardDetail JOD
                                INNER JOIN JobberOutwardMaster JOM  ON JOM.JobberOutwardID = JOD.JobberOutwardID
                                WHERE JOM.CompanyId =( SELECT TOP 1 CompanyId FROM CompanyMaster WHERE Is_Default = 1)
                                GROUP BY JOM.PartyId,JOD.YarnMaterialID,JOD.YarnColorID
                            ) JOD
                            ON t1.PartyId = JOD.PartyId
                            AND t1.YarnMaterialID = JOD.YarnMaterialID
                            AND t1.YarnColorID = JOD.YarnColorID
                            WHERE (t1.Stock - ISNULL(JOD.Stock, 0)) > 0;";
                }


                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr["Stock"].ToString());
                        listUser.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();
            }
            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;
            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getUpdateJobberOutwardSiftMaster()
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;

            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            try
            {
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                YarnOutwardMaster ilist = new YarnOutwardMaster();

                ilist.BillToPartyID = Convert.ToInt32(HttpContext.Current.Request.Params["BillToPartyID"] ?? "0");
                ilist.YarnMaterialID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnMaterialID"] ?? "0");
                ilist.YarnColorID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnColorID"] ?? "0");
                ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"] ?? "0");
                ilist.siftGodownInputBox = HttpContext.Current.Request.Params["siftGodownInputBox"];

                string userId = "0";
                int PartyId = 0;

                if (HttpContext.Current.Request.Cookies["UserIDs"] != null)
                {
                    userId = HttpContext.Current.Request.Cookies["UserIDs"].Value.Split('=')[1];
                }

                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();

                    string partyQuery = @"SELECT PartyId
                                  FROM UserAccountMaster
                                  WHERE UserAccountId = @UserAccountId";

                    using (SqlCommand cmd = new SqlCommand(partyQuery, con))
                    {
                        cmd.Parameters.AddWithValue("@UserAccountId", userId);

                        object result = cmd.ExecuteScalar();

                        if (result != null && result != DBNull.Value)
                        {
                            PartyId = Convert.ToInt32(result);
                        }
                    }
                }

                // Agar login user ki party mili hai to wahi use karo
                if (PartyId > 0)
                {
                    ilist.BillToPartyID = PartyId;
                }

                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = CommandType.Text;

                    cmd.CommandText = @"
                                    SELECT
                                        (T.NoOfBox - ISNULL(O.Stock,0)) AS NoOfBox,
                                        T.GodownLocationID,
                                        T.BillToPartyID,
                                        T.YarnMaterialID,
                                        T.YarnColorID,
                                        GM.GodownTitle,
                                        GLM.LocationTitle,
                                        PM.PartyName AS CompanyName,
                                        YMM.YarnMaterial,
                                        YCM.YarnColor,
                                        YCM.YarnColorCode
                                    FROM
                                    (
                                        SELECT
                                            YID.GodownLocationID,
                                            JIM.PartyId AS BillToPartyID,
                                            YIM.YarnMaterialID,
                                            YIM.YarnColorID,
                                            COUNT(*) AS NoOfBox
                                        FROM JobberInwardDetail JID
                                        INNER JOIN JobberInwardMaster JIM
                                            ON JIM.JobberInwardId = JID.JobberInwardId
                                        INNER JOIN YarnInwardDetail YID
                                            ON JID.BarcodeNo = YID.BarcodeNo
                                        INNER JOIN YarnInwardMaster YIM
                                            ON YID.YarnInwardID = YIM.YarnInwardID
                                        WHERE
                                            (@PartyId = 0 OR JIM.PartyId = @PartyId)
                                            AND (@YarnMaterialID = 0 OR YIM.YarnMaterialID = @YarnMaterialID)
                                            AND (@YarnColorID = 0 OR YIM.YarnColorID = @YarnColorID)
                                        GROUP BY
                                            YID.GodownLocationID,
                                            JIM.PartyId,
                                            YIM.YarnMaterialID,
                                            YIM.YarnColorID
                                    ) T
                                    LEFT JOIN
                                    (
                                        SELECT
                                            GodownLocationID,
                                            BillToPartyID,
                                            YarnMaterialID,
                                            YarnColorID,
                                            SUM(NoOfBox) AS Stock
                                        FROM JobberOutwardDetail
                                        GROUP BY
                                            GodownLocationID,
                                            BillToPartyID,
                                            YarnMaterialID,
                                            YarnColorID
                                    ) O
                                        ON T.GodownLocationID = O.GodownLocationID
                                        AND T.BillToPartyID = O.BillToPartyID
                                        AND T.YarnMaterialID = O.YarnMaterialID
                                        AND T.YarnColorID = O.YarnColorID

                                    LEFT JOIN GodownLocationMaster GLM
                                        ON T.GodownLocationID = GLM.GodownLocationID

                                    LEFT JOIN GodownMaster GM
                                        ON GLM.GodownID = GM.GodownID

                                    LEFT JOIN PartyMaster PM
                                        ON T.BillToPartyID = PM.PartyId

                                    LEFT JOIN YarnMaterialMaster YMM
                                        ON T.YarnMaterialID = YMM.YarnMaterialID

                                    LEFT JOIN YarnColorMaster YCM
                                        ON T.YarnColorID = YCM.YarnColorID

                                    WHERE (T.NoOfBox - ISNULL(O.Stock,0)) > 0

                                    ORDER BY
                                        GM.GodownTitle,
                                        GLM.LocationTitle";

                    cmd.Parameters.AddWithValue("@PartyId", ilist.BillToPartyID);
                    cmd.Parameters.AddWithValue("@YarnMaterialID", ilist.YarnMaterialID);
                    cmd.Parameters.AddWithValue("@YarnColorID", ilist.YarnColorID);

                    con.Open();

                    SqlDataReader rdr = cmd.ExecuteReader();

                    while (rdr.Read())
                    {
                        YarnOutwardMaster item = new YarnOutwardMaster();

                        item.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"]);
                        item.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"]);
                        item.YarnColorID = Convert.ToInt32(rdr["YarnColorID"]);
                        item.NoOfBox = Convert.ToInt32(rdr["NoOfBox"]);
                        item.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"]);

                        item.GodownTitle = Convert.ToString(rdr["GodownTitle"]).ToUpper();
                        item.LocationTitle = Convert.ToString(rdr["LocationTitle"]).ToUpper();
                        item.CompanyName = Convert.ToString(rdr["CompanyName"]).ToUpper();
                        item.YarnMaterial = Convert.ToString(rdr["YarnMaterial"]).ToUpper();
                        item.YarnColor = Convert.ToString(rdr["YarnColor"]).ToUpper();
                        item.YarnColorCode = Convert.ToString(rdr["YarnColorCode"]).ToUpper();

                        listUser.Add(item);
                    }

                    rdr.Close();
                }

                response.Code = 200;
                response.Message = "Success";
                response.listYarnOutwardMaster = listUser;
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
                response.listYarnOutwardMaster = new List<YarnOutwardMaster>();
            }

            Context.Response.Write(js.Serialize(response));
        }
