        [WebMethod]
        public object GetBarcodeDetails(string barcodeNo)
        {
            // Replace with your actual connection string configuration
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            // Use the query you provided (parameterized to prevent SQL Injection)
            string query = @"
            SELECT JIM.GodownID, JID.JobberInwardDetailID, JID.JobberInwardID, PM.SundryParty, 
                   YPM.YarnPOID, PM.PartyId as CompanyPartyId, PM.PartyName AS CompanyPartyName, 
                   PM1.PartyName AS BillToPartyName, PM1.PartyId as BillToPartyId, YMM.YarnMaterialID, 
                   YMM.YarnMaterial, YCM.YarnColorID, YCM.YarnColor, JID.BarcodeNo, JID.BoxNo, 
                   JID.NetWeight, YCM.YarnColorCode 
            FROM JobberInwardDetail JID 
            INNER JOIN JobberInwardMaster JIM ON JIM.JobberInwardID = JID.JobberInwardID 
            INNER JOIN YarnInwardDetail YID ON YID.BarcodeNo = JID.BarcodeNo 
            INNER JOIN YarnInwardMaster YIM ON YIM.YarnInwardID = YID.YarnInwardID 
            INNER JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = YIM.YarnMaterialID 
            INNER JOIN YarnColorMaster YCM ON YCM.YarnColorID = YIM.YarnColorID 
            INNER JOIN YarnPOMaster YPM ON YPM.YarnPOID = YIM.YarnPOID 
            INNER JOIN PartyMaster PM ON PM.PartyId = YPM.CompanyPartyID 
            INNER JOIN PartyMaster PM1 ON PM1.PartyId = YPM.BillToPartyID 
            WHERE JID.UserAccountId = @UserAccountId AND JID.BarcodeNo = @BarcodeNo";


            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    // Set parameters safely
                    cmd.Parameters.AddWithValue("@UserAccountId", Context.Request.Cookies["UserIDs"].Value.Split('=')[1]); // hardcoded from your query example
                    cmd.Parameters.AddWithValue("@BarcodeNo", barcodeNo);
                    conn.Open();
                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            // Return an anonymous object mapping all columns directly to JSON keys
                            return new
                            {
                                GodownID = reader["GodownID"].ToString(),
                                JobberInwardDetailID = reader["JobberInwardDetailID"].ToString(),
                                JobberInwardID = reader["JobberInwardID"].ToString(),
                                SundryParty = reader["SundryParty"].ToString(),
                                YarnPOID = reader["YarnPOID"].ToString(),
                                CompanyPartyId = reader["CompanyPartyId"].ToString(),
                                CompanyPartyName = reader["CompanyPartyName"].ToString(),
                                BillToPartyName = reader["BillToPartyName"].ToString(),
                                BillToPartyId = reader["BillToPartyId"].ToString(),
                                YarnMaterialID = reader["YarnMaterialID"].ToString(),
                                YarnMaterial = reader["YarnMaterial"].ToString(),
                                YarnColorID = reader["YarnColorID"].ToString(),
                                YarnColor = reader["YarnColor"].ToString(),
                                BarcodeNo = reader["BarcodeNo"].ToString(),
                                BoxNo = reader["BoxNo"].ToString(),
                                NetWeight = Convert.ToDecimal(reader["NetWeight"]).ToString("0.00"),
                                YarnColorCode = reader["YarnColorCode"].ToString()
                            };
                        }
                    }
                }
            }
            return null; // Returns null if no matching barcode row exists
        }
        [WebMethod]
        public object JobberOutward(string JobberOutwardID = "")
        {
            int userAccountId = 0;
            int PartyId = GetPartyId();
            if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
            {
                string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                userAccountId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
            }

            int currentJobberOutwardID = 0;
            if (!string.IsNullOrWhiteSpace(JobberOutwardID))
            {
                try
                {
                    string encryptedId = JobberOutwardID;
                    if (!encryptedId.EndsWith("%3d%3d", StringComparison.OrdinalIgnoreCase))
                    {
                        encryptedId = encryptedId.Replace("==", "") + "%3d%3d";
                    }

                    currentJobberOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(encryptedId)));
                }
                catch
                {
                    currentJobberOutwardID = 0;
                }
            }

            string query = @"
        SELECT
            JIM.GodownID,
            JID.JobberInwardDetailID,
            JID.JobberInwardID,
            PM.SundryParty,
            YPM.YarnPOID,
            PM.PartyId AS CompanyPartyId,
            PM.PartyName AS CompanyPartyName,
            PM1.PartyName AS BillToPartyName,
            PM1.PartyId AS BillToPartyId,
            YMM.YarnMaterialID,
            YMM.YarnMaterial,
            YCM.YarnColorID,
            YCM.YarnColor,
            JID.BarcodeNo,
            JID.BoxNo,
            JID.NetWeight,
            YCM.YarnColorCode
        FROM JobberInwardMaster JIM
        INNER JOIN JobberInwardDetail JID ON JID.JobberInwardID = JIM.JobberInwardID
        LEFT JOIN YarnInwardDetail YID ON YID.BarcodeNo = JID.BarcodeNo
        LEFT JOIN YarnInwardMaster YIM ON YIM.YarnInwardID = YID.YarnInwardID
        LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = YIM.YarnMaterialID
        INNER JOIN YarnColorMaster YCM ON YCM.YarnColorID = YIM.YarnColorID
        INNER JOIN YarnPOMaster YPM ON YPM.YarnPOID = YIM.YarnPOID
        INNER JOIN PartyMaster PM ON PM.PartyId = YPM.CompanyPartyID
        INNER JOIN PartyMaster PM1 ON PM1.PartyId = YPM.BillToPartyID
        WHERE JIM.PartyId = @PartyId
        AND NOT EXISTS
        (
            SELECT 1
            FROM JobberOutwardDetail JOD
            CROSS APPLY OPENJSON(JOD.DetailsJson) D
            WHERE TRY_CONVERT(INT, JSON_VALUE(D.value, '$.JobberInwardDetailID')) = JID.JobberInwardDetailID
            AND (@JobberOutwardID = 0 OR JOD.JobberOutwardID <> @JobberOutwardID)
        )
        ORDER BY YMM.YarnMaterial, YCM.YarnColor, JID.JobberInwardDetailID;";

            DataTable dt = new DataTable();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.Add("@PartyId", SqlDbType.Int).Value = PartyId;
                    cmd.Parameters.Add("@JobberOutwardID", SqlDbType.Int).Value = currentJobberOutwardID;

                    using (SqlDataAdapter sda = new SqlDataAdapter(cmd))
                    {
                        sda.Fill(dt);
                    }
                }
            }

            return JsonConvert.SerializeObject(dt);
        }
        [WebMethod]
        public PartyDetailsDTO GetPartyDetailsById(int partyId)
        {
            PartyDetailsDTO party = null;
            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            string query = @"SELECT PartyId, PartyName, BillingAddress AS BillingAddress 
                     FROM PartyMaster 
                     WHERE PartyId = @PartyId";

            using (SqlConnection conn = new SqlConnection(connString))
            {
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    cmd.Parameters.AddWithValue("@PartyId", partyId);
                    conn.Open();

                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            party = new PartyDetailsDTO
                            {
                                PartyId = reader["PartyId"] != DBNull.Value ? Convert.ToInt32(reader["PartyId"]) : 0,
                                PartyName = reader["PartyName"] != DBNull.Value ? reader["PartyName"].ToString() : string.Empty,
                                BillingAddress = reader["BillingAddress"] != DBNull.Value ? reader["BillingAddress"].ToString() : string.Empty
                            };
                        }
                    }
                }
            }

            return party;
        }
