        [WebMethod]
        public void ExportDesignExcel()
        {
            string connString =
                ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            DataTable dt = new DataTable();

            // =====================================================
            // GET DESIGN + COLOR MATCHING DATA
            // =====================================================
            using (SqlConnection con = new SqlConnection(connString))
            {
                string query = @"
            SELECT
                DEFM.DesignerCode,
                DEFM.DesignNo,
                DCMD.MatchingID,
                CGM.ColorGroup,
              DCMD.ColorMatchingPhoto

            FROM DesignColorMatchingFormMaster AS DCMFM

            LEFT JOIN DesignEntryFormMaster AS DEFM
                ON DEFM.DesignEntryFormID =
                   DCMFM.DesignEntryFormID

            INNER JOIN DesignColorMatchingDetails AS DCMD
                ON DCMD.DesignColorMatchingFormID =
                   DCMFM.DesignColorMatchingFormID

            INNER JOIN ColorGroupMaster AS CGM
                ON CGM.ColorGroupID =
                   DCMD.ColorGroupID

            WHERE DCMFM.FinancialYearID = (
                SELECT FinancialYearID
                FROM FinancialYearMaster
                WHERE IsDefault = 1
            )

            AND DCMFM.CompanyId = (
                SELECT CompanyId
                FROM CompanyMaster
                WHERE is_default = 1
            )

            AND CGM.ColorGroup IS NOT NULL

            ORDER BY
                DEFM.DesignerCode,
                DEFM.DesignNo,
                DCMD.MatchingNo;";

                using (SqlDataAdapter da =
                    new SqlDataAdapter(query, con))
                {
                    da.Fill(dt);
                }
            }

            // =====================================================
            // CREATE EXCEL
            // =====================================================
            using (XLWorkbook wb = new XLWorkbook())
            {
                IXLWorksheet ws =
                    wb.Worksheets.Add("Design Master");

                // =================================================
                // HEADER
                // =================================================
                ws.Cell(1, 1).Value =
                    "DesignerCode-DesignNo";

                ws.Cell(1, 2).Value =
                    "MatchingID";

                ws.Cell(1, 3).Value =
                    "ColorGroup";

                ws.Cell(1, 4).Value =
                    "PhotoOfDesign";

                // Header formatting
                ws.Range(1, 1, 1, 4)
                    .Style.Font.Bold = true;

                ws.Range(1, 1, 1, 4)
                    .Style.Alignment.Horizontal =
                    XLAlignmentHorizontalValues.Center;

                ws.Range(1, 1, 1, 4)
                    .Style.Alignment.Vertical =
                    XLAlignmentVerticalValues.Center;

                ws.Row(1).Height = 25;

                // =================================================
                // DATA
                // =================================================
                int excelRow = 2;

                foreach (DataRow dr in dt.Rows)
                {
                    // =============================================
                    // DESIGNER CODE
                    // =============================================
                    string designerCode =
                        dr["DesignerCode"] == DBNull.Value
                            ? ""
                            : dr["DesignerCode"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // DESIGN NO
                    // =============================================
                    string designNo =
                        dr["DesignNo"] == DBNull.Value
                            ? ""
                            : dr["DesignNo"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // DESIGNER CODE - DESIGN NO
                    // =============================================
                    ws.Cell(excelRow, 1).Value =
                        designerCode + "-" + designNo;

                    // =============================================
                    // MATCHING ID
                    // =============================================
                    ws.Cell(excelRow, 2).Value =
                        dr["MatchingID"] == DBNull.Value
                            ? ""
                            : dr["MatchingID"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =============================================
                    // COLOR GROUP
                    // =============================================
                    ws.Cell(excelRow, 3).Value =
                        dr["ColorGroup"] == DBNull.Value
                            ? ""
                            : dr["ColorGroup"]
                                .ToString()
                                .Trim()
                                .ToUpper();

                    // =================================================
                    // DESIGN IMAGE
                    // =================================================
                    string photoPath = "";

                    if (dr["ColorMatchingPhoto"] != DBNull.Value)
                    {
                        photoPath =
                            dr["ColorMatchingPhoto"]
                                .ToString()
                                .Trim();
                    }

                    if (!string.IsNullOrWhiteSpace(photoPath))
                    {
                        try
                        {
                            // Example DB value:
                            //
                            // COLORMATCHINGPHOTO/YGRKBIRS025-5.BMP
                            //
                            // Get only:
                            //
                            // YGRKBIRS025-5.BMP

                            string fileName =
                                Path.GetFileName(
                                    photoPath.Replace("/", "\\")
                                );

                            // =========================================
                            // ACTUAL IMAGE PATH
                            // =========================================
                            //
                            // E:\Bharat\New folder\weavelanesoft\
                            // ColorMatchingPhoto\
                            //

                            string physicalImagePath =
                                Server.MapPath(
                                    "~/ColorMatchingPhoto/" +
                                    fileName
                                );

                            if (File.Exists(physicalImagePath))
                            {
                                // =====================================
                                // TEMP FOLDER
                                // =====================================
                                string tempFolder =
                                    Server.MapPath(
                                        "~/Uploads/TempDesignImages/"
                                    );

                                if (!Directory.Exists(tempFolder))
                                {
                                    Directory.CreateDirectory(
                                        tempFolder
                                    );
                                }

                                // =====================================
                                // UNIQUE TEMP IMAGE NAME
                                // =====================================
                                string tempFileName =
                                    Guid.NewGuid().ToString("N") +
                                    ".jpg";

                                string tempImagePath =
                                    Path.Combine(
                                        tempFolder,
                                        tempFileName
                                    );

                                // =====================================
                                // RESIZE + COMPRESS IMAGE
                                // =====================================
                                ResizeImageToJpeg(
                                    physicalImagePath,
                                    tempImagePath,
                                    80,
                                    80
                                );

                                // =====================================
                                // ADD SMALL JPEG TO EXCEL
                                // =====================================
                                if (File.Exists(tempImagePath))
                                {
                                    ws.AddPicture(tempImagePath)
                                        .MoveTo(
                                            ws.Cell(
                                                excelRow,
                                                4
                                            )
                                        )
                                        .WithSize(80, 80);

                                    ws.Row(excelRow).Height = 65;

                                    // =================================
                                    // DELETE TEMP FILE
                                    // =================================
                                    try
                                    {
                                        File.Delete(
                                            tempImagePath
                                        );
                                    }
                                    catch
                                    {
                                        // Ignore delete error
                                    }
                                }
                                else
                                {
                                    ws.Cell(
                                        excelRow,
                                        4
                                    ).Value =
                                        "Image Conversion Failed";
                                }
                            }
                            else
                            {
                                ws.Cell(
                                    excelRow,
                                    4
                                ).Value =
                                    "Image Not Found";
                            }
                        }
                        catch (OutOfMemoryException)
                        {
                            // =========================================
                            // BAD / VERY LARGE / CORRUPT IMAGE
                            // =========================================
                            ws.Cell(
                                excelRow,
                                4
                            ).Value =
                                "Image Too Large";
                        }
                        catch (Exception ex)
                        {
                            ws.Cell(
                                excelRow,
                                4
                            ).Value =
                                "Image Error";

                            // For debugging if required:
                            //
                            // ws.Cell(excelRow, 5).Value =
                            //     ex.Message;
                        }
                    }
                    else
                    {
                        ws.Cell(
                            excelRow,
                            4
                        ).Value =
                            "No Image";
                    }

                    excelRow++;
                }

                // =====================================================
                // FORMAT
                // =====================================================

                ws.Column(1).Width = 25;
                ws.Column(2).Width = 30;
                ws.Column(3).Width = 25;
                ws.Column(4).Width = 22;

                if (excelRow > 1)
                {
                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    )
                    .Style
                    .Alignment
                    .Vertical =
                        XLAlignmentVerticalValues.Center;

                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    )
                    .Style
                    .Alignment
                    .WrapText = true;
                }

                // =====================================================
                // FREEZE HEADER
                // =====================================================
                ws.SheetView.FreezeRows(1);

                // =====================================================
                // AUTO FILTER
                // =====================================================
                if (excelRow > 2)
                {
                    ws.Range(
                        1,
                        1,
                        excelRow - 1,
                        4
                    ).SetAutoFilter();
                }

                // =====================================================
                // SAVE EXCEL
                // =====================================================
                string uploadFolder =
                    Server.MapPath("~/Uploads/");

                if (!Directory.Exists(uploadFolder))
                {
                    Directory.CreateDirectory(
                        uploadFolder
                    );
                }

                string excelFileName =
                    "colormaching_" +
                    DateTime.Now.ToString(
                        "yyyyMMddHHmmss"
                    ) +
                    ".xlsx";

                string excelFilePath =
                    Path.Combine(
                        uploadFolder,
                        excelFileName
                    );

                wb.SaveAs(excelFilePath);

                // =====================================================
                // DOWNLOAD
                // =====================================================
                HttpResponse response =
                    HttpContext.Current.Response;

                response.Clear();
                response.ClearHeaders();
                response.ClearContent();

                response.ContentType =
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

                response.AddHeader(
                    "Content-Disposition",
                    "attachment; filename=\"" +
                    excelFileName +
                    "\""
                );

                response.TransmitFile(
                    excelFilePath
                );

                response.Flush();

                HttpContext.Current.ApplicationInstance
                    .CompleteRequest();
            }
        }

        // =============================================================
        // RESIZE + COMPRESS IMAGE
        // =============================================================
        private void ResizeImageToJpeg(string sourcePath, string destinationPath, int maxWidth, int maxHeight)
        {
            using (System.Drawing.Image originalImage =
                System.Drawing.Image.FromFile(sourcePath))
            {
                // =============================================
                // Calculate aspect ratio
                // =============================================
                double ratioX =
                    (double)maxWidth /
                    originalImage.Width;

                double ratioY =
                    (double)maxHeight /
                    originalImage.Height;

                double ratio =
                    Math.Min(
                        ratioX,
                        ratioY
                    );

                int newWidth =
                    Math.Max(
                        1,
                        (int)(
                            originalImage.Width *
                            ratio
                        )
                    );

                int newHeight =
                    Math.Max(
                        1,
                        (int)(
                            originalImage.Height *
                            ratio
                        )
                    );

                // =============================================
                // Create small bitmap
                // =============================================
                using (Bitmap bitmap =
                    new Bitmap(
                        newWidth,
                        newHeight
                    ))
                {
                    using (Graphics graphics =
                        Graphics.FromImage(bitmap))
                    {
                        graphics.CompositingQuality =
                            CompositingQuality.HighQuality;

                        graphics.InterpolationMode =
                            InterpolationMode.HighQualityBicubic;

                        graphics.SmoothingMode =
                            SmoothingMode.HighQuality;

                        graphics.PixelOffsetMode =
                            PixelOffsetMode.HighQuality;

                        graphics.DrawImage(
                            originalImage,
                            0,
                            0,
                            newWidth,
                            newHeight
                        );
                    }

                    // =============================================
                    // JPEG encoder
                    // =============================================
                    ImageCodecInfo jpegCodec = null;

                    ImageCodecInfo[] codecs =
                        ImageCodecInfo.GetImageEncoders();

                    foreach (ImageCodecInfo codec in codecs)
                    {
                        if (codec.FormatID ==
                            System.Drawing.Imaging.ImageFormat.Jpeg.Guid)
                        {
                            jpegCodec = codec;
                            break;
                        }
                    }

                    if (jpegCodec != null)
                    {
                        EncoderParameters encoderParameters =
                            new EncoderParameters(1);

                        encoderParameters.Param[0] =
                            new EncoderParameter(
                                System.Drawing.Imaging.Encoder.Quality,
                                75L
                            );

                        bitmap.Save(
                            destinationPath,
                            jpegCodec,
                            encoderParameters
                        );

                        encoderParameters.Dispose();
                    }
                    else
                    {
                        bitmap.Save(
                            destinationPath,
                            System.Drawing.Imaging.ImageFormat.Jpeg
                        );
                    }
                }
            }
        }
        [WebMethod]
        public string MoveJobberInwardToPending(int JobberInwardID)
        {
            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connString))
            {
                con.Open();

                using (SqlTransaction transaction = con.BeginTransaction())
                {
                    try
                    {
                        // 1. Delete Jobber Inward Details
                        using (SqlCommand cmdDetail = new SqlCommand(@"
                    DELETE FROM JobberInwardDetail
                    WHERE JobberInwardID = @JobberInwardID
                ", con, transaction))
                        {
                            cmdDetail.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);
                            cmdDetail.ExecuteNonQuery();
                        }

                        // 2. Delete Jobber Inward Master
                        using (SqlCommand cmdMaster = new SqlCommand(@"
                    DELETE FROM JobberInwardMaster
                    WHERE JobberInwardID = @JobberInwardID
                ", con, transaction))
                        {
                            cmdMaster.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);
                            cmdMaster.ExecuteNonQuery();
                        }

                        transaction.Commit();

                        return "success";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();

                        return "Error: " + ex.Message;
                    }
                }
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string GetJobberInwardView(int JobberInwardID)
        {
            try
            {
                DataTable dtMaster = new DataTable();
                DataTable dtDetails = new DataTable();

                string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(connString))
                {
                    con.Open();

                    // =========================================================
                    // MASTER
                    // =========================================================

                    string masterQuery = @"
                SELECT
                    JIM.JobberInwardId,
                    JIM.DateAndTime,

                    JIM.JobberId,
                    JIM.PartyId,
                    JIM.JobWorkOutwardId,

                    -- Received Challan
                    JIM.ChallanNo AS ReceivedChallanNo,

                    JIM.TotalWeight,
                    JIM.PendingWeight,
                    JIM.POPendingWeight,

                    JIM.GodownID,
                    JIM.PhotoOfInward,
                    JIM.CompanyId,
                    JIM.IsComplete,

                    -- Sender
                    PM.PartyName AS SenderName,
                    PM.BillingAddress AS SenderAddress,
                    PM.MobileNo AS SenderMobile,

                    -- Jobber Outward
                    YOM.OutwardListNo AS JobberChallanNo,
                    YOM.OutwardListDate,

                    -- Receiver
                    CM.CompanyName AS ReceivedName,
                    CM.MobileNo AS ReceivedMobile,

                    -- Godown
                    GM.GodownTitle AS GodownName

                FROM JobberInwardMaster JIM

                LEFT JOIN PartyMaster PM
                    ON PM.PartyId = JIM.PartyId

                LEFT JOIN YarnOutwardMaster YOM
                    ON YOM.YarnOutwardID = JIM.JobWorkOutwardId

                LEFT JOIN CompanyMaster CM
                    ON CM.CompanyId = JIM.CompanyId

                LEFT JOIN GodownMaster GM
                    ON GM.GodownID = JIM.GodownID

                WHERE
                    JIM.JobberInwardId = @JobberInwardID
            ";

                    using (SqlCommand cmd = new SqlCommand(masterQuery, con))
                    {
                        cmd.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);

                        SqlDataAdapter da = new SqlDataAdapter(cmd);

                        da.Fill(dtMaster);
                    }


                    // =========================================================
                    // DETAILS
                    // =========================================================

                    string detailQuery = @"   ;WITH InwardDetails AS
                (
                    SELECT
                        JID.JobberInwardDetailID,
                        JID.DateAndTime,
                        JID.BoxNo,
                        JID.NetWeight,
                        JID.BarcodeNo,
                        JID.GodownLocationID,
                        JID.JobberInwardID,
                        JID.UserAccountId,
                        JID.YarnInterchangeID,
                        JID.IsScanStutas,
                        JID.IsScanUpdateDateTime,

                        ROW_NUMBER() OVER
                        (
                            ORDER BY JID.JobberInwardDetailID
                        ) AS RN

                    FROM JobberInwardDetail JID

                    WHERE
                        JID.JobberInwardID = @JobberInwardID
                ),

                OutwardDetails AS
                (
                    SELECT
                        YOD.YarnOutwardDetailID,
                        YOD.YarnOutwardID,
                        YOD.YarnMaterialID,
                        YOD.YarnColorID,
                        YOD.GodownLocationID,
                        YOD.NoOfBox,

                        ROW_NUMBER() OVER
                        (
                            ORDER BY YOD.YarnOutwardDetailID
                        ) AS RN

                    FROM YarnOutwardDetail YOD

                    INNER JOIN JobberInwardMaster JIM
                        ON JIM.JobWorkOutwardId = YOD.YarnOutwardID

                    WHERE
                        JIM.JobberInwardId = @JobberInwardID
                )

                SELECT

                    ID.JobberInwardDetailID,
                    ID.DateAndTime,

                    ID.BoxNo,
                    ID.NetWeight,
                    ID.BarcodeNo,

                    ID.GodownLocationID,
                    ID.JobberInwardID,
                    ID.UserAccountId,
                    ID.YarnInterchangeID,
                    ID.IsScanStutas,
                    ID.IsScanUpdateDateTime,

                    -- Yarn Material
                    OD.YarnMaterialID,
                    ISNULL(YMM.YarnMaterial, '') AS YarnMaterial,

                    -- Yarn Color
                    OD.YarnColorID,
                    ISNULL(YCM.YarnColor, '') AS YarnColor,

                    OD.NoOfBox AS OutwardBox

                FROM InwardDetails ID

                LEFT JOIN OutwardDetails OD
                    ON OD.RN = ID.RN

                LEFT JOIN YarnMaterialMaster YMM
                    ON YMM.YarnMaterialID = OD.YarnMaterialID

                LEFT JOIN YarnColorMaster YCM
                    ON YCM.YarnColorID = OD.YarnColorID

                ORDER BY
                    ID.JobberInwardDetailID ";
                    using (SqlCommand cmd = new SqlCommand(detailQuery, con))
                    {
                        cmd.Parameters.AddWithValue("@JobberInwardID", JobberInwardID);
                        SqlDataAdapter da = new SqlDataAdapter(cmd); da.Fill(dtDetails);
                    }
                }

                if (dtMaster.Rows.Count == 0) { return JsonConvert.SerializeObject(new { Status = false, Message = "Jobber Inward not found." }); }
                return JsonConvert.SerializeObject(new
                {
                    Status = true,
                    Master = dtMaster,
                    Details = dtDetails
                });
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = false,
                    Message = ex.Message
                });
            }
        }
