                                    JOM.GodownID,
                                    JOM.PartyId,
                                    JOM.OutwardListNo,
                                    JOM.OutwardListDate,                
                                    JOM.UserAccountId,
                                    JOM.FinancialYearID,
                                    JOM.CompanyId,
                                    JOM.SundryPartyID,
                                    JOM.TotalWeight,
                                    PM.PartyName,
                                    PM.BillingAddress
                                FROM JobberOutwardMaster JOM
                                LEFT JOIN JobberMaster JM ON JM.Id = JOM.PartyId
                                WHERE JOM.JobberOutwardID = @JobberOutwardID";

                    using (SqlCommand cmd = new SqlCommand(masterQuery, con))
                    {
                        cmd.Parameters.Add("@JobberOutwardID", SqlDbType.Int).Value = outwardId;
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtMaster);
                        }
                    }

                    // ==========================================
                    // DETAILS
                    // ==========================================

                    string detailQuery = @"
                                SELECT
                                    JOD.JobberOutwardDetailID,
                                    JOD.DateAndTime,
                                    JOD.JobberOutwardID,
                                    JOD.BillToPartyId,
                                    JOD.CompanyPartyId,  
                                    JOD.YarnMaterialID,
                                    JOD.YarnColorID,
                                    JOD.NoOfBox,
                                    JOD.UserAccountId,
                                    JOD.NetWeight,
                                    JOD.BarcodeNo,
                                    JOD.BoxNo,
                                    JOD.YarnPOID,
                                    JOD.DetailsJson, -- <--- ADDED THIS LINE TO SELECT THE JSON TRACKING DATA
                                    YM.YarnMaterial,
                                    YC.YarnColor,
                                    YC.YarnColorCode,
                                    PM.PartyName AS BillToPartyName,
                                    CPM.PartyName AS CompanyPartyName
                                FROM JobberOutwardDetail JOD
                                LEFT JOIN YarnMaterialMaster YM ON YM.YarnMaterialID = JOD.YarnMaterialID
                                LEFT JOIN YarnColorMaster YC ON YC.YarnColorID = JOD.YarnColorID
                                LEFT JOIN PartyMaster PM ON PM.PartyId = JOD.BillToPartyId
                                LEFT JOIN PartyMaster CPM ON CPM.PartyId = JOD.CompanyPartyId
                                WHERE JOD.JobberOutwardID = @JobberOutwardID
                                ORDER BY  JOD.JobberOutwardDetailID";

                    using (SqlCommand cmd = new SqlCommand(detailQuery, con))
                    {
                        cmd.Parameters.Add("@JobberOutwardID", SqlDbType.Int).Value = outwardId;
                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dtDetails);
                        }
                    }
                }

                // ==========================================
                // RESULT
                // ==========================================

                var result = new
                {
                    Code = 200,
                    Message = "Success",

                    Master =
                        DataTableToList(dtMaster),

                    Details =
                        DataTableToList(dtDetails)
                };

                return JsonConvert.SerializeObject(result);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Code = 500,
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ServiceResponse insertJobberOutwardMaster(JobberOutwardMasterDTO masterData)
        {
            ServiceResponse response = new ServiceResponse();
            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            // 1. Initial Validation
            if (masterData == null || masterData.Details == null || masterData.Details.Count == 0)
            {
                response.Code = 400;
                response.Message = "No items scanned to save.";
                return response;
            }

            // 2. Safe Cookie Processing
            int userAccountId = 0;
            int companyId = 0;

            try
            {
                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    userAccountId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    response.Code = 401;
                    response.Message = "User session expired. Please log in again.";
                    return response;
                }

                if (Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value))
                {
                    string cookieVal = Context.Request.Cookies["CompanyID"].Value;
                    companyId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    response.Code = 401;
                    response.Message = "Company profile context missing. Please re-login.";
                    return response;
                }
            }
            catch (Exception ex)
            {
                response.Code = 400;
                response.Message = "Authentication format error: " + ex.Message;
                return response;
            }

            // 3. Database Operations
            using (SqlConnection conn = new SqlConnection(connString))
            {
                conn.Open();
                using (SqlTransaction transaction = conn.BeginTransaction())
                {
                    try
                    {
                        // A. Fetch PartyPrefix, PartyId, and SundryParty
                        string partyPrefix = "";
                        int PartyId = 0;
                        int SundryParty = 0;

                        string getPrefixQuery = "SELECT ISNULL(PM.PartyPrefix, ''), UM.PartyId, PM.SundryParty FROM UserAccountMaster UM LEFT JOIN PartyMaster PM ON PM.PartyId = UM.PartyId WHERE UM.UserAccountId = @PartyId";

                        using (SqlCommand cmdPrefix = new SqlCommand(getPrefixQuery, conn, transaction))
                        {
                            cmdPrefix.Parameters.AddWithValue("@PartyId", userAccountId);

                            using (SqlDataReader reader = cmdPrefix.ExecuteReader())
                            {
                                if (reader.Read())
                                {
                                    partyPrefix = reader.IsDBNull(0) ? "" : reader.GetString(0);
                                    PartyId = reader.IsDBNull(1) ? 0 : Convert.ToInt32(reader.GetValue(1));
                                    SundryParty = reader.IsDBNull(2) ? 0 : Convert.ToInt32(reader.GetValue(2));
                                }
                            }
                        }

                        // Fallback prefix if empty
                        if (string.IsNullOrEmpty(partyPrefix))
                        {
                            partyPrefix = "TR";
                        }

                        // Find the latest sequence number safely across the company context using the prefix block
                        string getMaxSeqQuery = @"SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(OutwardListNo, LEN(@Prefix) + 1, LEN(OutwardListNo)) AS INT)), 0) 
                                        FROM JobberOutwardMaster 
                                        WHERE CompanyId = @CompanyId AND OutwardListNo LIKE @Prefix + '%'";

                        int nextSeq = 1;
                        using (SqlCommand cmdSeq = new SqlCommand(getMaxSeqQuery, conn, transaction))
                        {
                            cmdSeq.Parameters.AddWithValue("@CompanyId", companyId);
                            cmdSeq.Parameters.AddWithValue("@Prefix", partyPrefix);
                            object seqResult = cmdSeq.ExecuteScalar();
                            if (seqResult != null && seqResult != DBNull.Value)
                            {
                                nextSeq = Convert.ToInt32(seqResult) + 1;
                            }
                        }
                        string generatedOutwardListNo = partyPrefix + nextSeq.ToString();

                        // B. Insert into JobberOutwardMaster Table
                        string insertMasterQuery = @"
                    INSERT INTO JobberOutwardMaster 
                    (DateAndTime, GodownID, PartyId, OutwardListNo, OutwardListDate, IsScanStutas, UserAccountId, FinancialYearID, CompanyId, SundryPartyID, TotalWeight) 
                    VALUES 
                    (GETDATE(), @GodownID, @PartyId, @OutwardListNo, @OutwardListDate, 1, @UserAccountId, (SELECT TOP 1 FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1), @CompanyId, @SundryPartyID, @TotalWeight);
                    SELECT SCOPE_IDENTITY();";

                        int generatedMasterId = 0;
                        int initialGodownId = masterData.Details[0].GodownID;
                        int initialSundryPartyId = SundryParty;
                        DateTime outwardDate = DateTime.Now;
                        if (!string.IsNullOrEmpty(masterData.OutwardListDate))
                        {
                            // Try parsing standard formats safely
                            if (!DateTime.TryParse(masterData.OutwardListDate, out outwardDate))
                            {
                                // Fallback or explicit format check if needed
                                DateTime.TryParseExact(masterData.OutwardListDate, new string[] { "dd/MM/yyyy", "yyyy-MM-dd", "MM/dd/yyyy" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out outwardDate);
                            }
                        }

                        using (SqlCommand cmd = new SqlCommand(insertMasterQuery, conn, transaction))
                        {
                            cmd.Parameters.AddWithValue("@GodownID", initialGodownId);
                            cmd.Parameters.AddWithValue("@PartyId", masterData.PartyId);
                            cmd.Parameters.AddWithValue("@OutwardListNo", generatedOutwardListNo);
                            cmd.Parameters.AddWithValue("@OutwardListDate", outwardDate);
                            cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                            cmd.Parameters.AddWithValue("@CompanyId", companyId);
                            cmd.Parameters.AddWithValue("@SundryPartyID", initialSundryPartyId);
                            cmd.Parameters.AddWithValue("@TotalWeight", masterData.TotalWeight);
                            generatedMasterId = Convert.ToInt32(cmd.ExecuteScalar());
                        }

                        // C. Insert rows into JobberOutwardDetail Table
                        string insertDetailQuery = @"
                    INSERT INTO JobberOutwardDetail 
                    (DateAndTime, JobberOutwardID, BillToPartyID, YarnMaterialID, YarnColorID, NoOfBox, UserAccountId, NetWeight, BarcodeNo, BoxNo, CompanyPartyId, YarnPOID, DetailsJson) 
                    VALUES 
                    (GETDATE(), @JobberOutwardID, @BillToPartyID, @YarnMaterialID, @YarnColorID, @NoOfBox, @UserAccountId, @NetWeight, @BarcodeNo, @BoxNo, @CompanyPartyId, @YarnPOID, @DetailsJson);";

                        foreach (var item in masterData.Details)
                        {
                            using (SqlCommand cmdDetail = new SqlCommand(insertDetailQuery, conn, transaction))
                            {
                                cmdDetail.Parameters.AddWithValue("@JobberOutwardID", generatedMasterId);
                                cmdDetail.Parameters.AddWithValue("@BillToPartyID", item.BillToPartyId);
                                cmdDetail.Parameters.AddWithValue("@YarnMaterialID", item.YarnMaterialID);
                                cmdDetail.Parameters.AddWithValue("@YarnColorID", item.YarnColorID);
                                cmdDetail.Parameters.AddWithValue("@NoOfBox", item.NoOfBox > 0 ? item.NoOfBox : 1);
                                cmdDetail.Parameters.AddWithValue("@UserAccountId", userAccountId);
                                cmdDetail.Parameters.AddWithValue("@NetWeight", item.NetWeight);
                                cmdDetail.Parameters.AddWithValue("@BarcodeNo", item.BarcodeNo ?? "");
                                cmdDetail.Parameters.AddWithValue("@BoxNo", item.BoxNo ?? "");
                                cmdDetail.Parameters.AddWithValue("@CompanyPartyId", item.CompanyPartyId);
                                cmdDetail.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                                cmdDetail.Parameters.AddWithValue("@DetailsJson", (object)item.DetailsJson ?? DBNull.Value);
                                cmdDetail.ExecuteNonQuery();
                            }
                        }

                        transaction.Commit();
                        response.Code = 200;
                        response.Message = "Jobber Outward entry recorded successfully with List No: " + generatedOutwardListNo;
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        response.Code = 500;
                        response.Message = "Database Error: " + ex.Message;
                    }
                }
            }
            return response;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public string updateJobberOutwardMaster(JobberOutwardMasterDTO masterData)
        {
            SqlConnection con = null;
            SqlTransaction transaction = null;

            try
            {
                int userAccountId = 0;
                int companyId = 0;

                if (Context.Request.Cookies["UserIDs"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["UserIDs"].Value))
                {
                    string cookieVal = Context.Request.Cookies["UserIDs"].Value;
                    userAccountId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }
                else
                {
                    return JsonConvert.SerializeObject(new { Code = 401, Message = "User session expired. Please log in again." });
                }

                if (Context.Request.Cookies["CompanyID"] != null && !string.IsNullOrEmpty(Context.Request.Cookies["CompanyID"].Value))
                {
                    string cookieVal = Context.Request.Cookies["CompanyID"].Value;
                    companyId = Convert.ToInt32(cookieVal.Contains("=") ? cookieVal.Split('=')[1] : cookieVal);
                }

                int outwardId = 0;
                if (!string.IsNullOrEmpty(masterData.JobberOutwardEncryptedID))
                {
                    outwardId = Convert.ToInt32(Decrypt(masterData.JobberOutwardEncryptedID));
                }
                else
                {
                    outwardId = masterData.JobberOutwardID;
                }

                string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                con = new SqlConnection(connString);
                con.Open();
                transaction = con.BeginTransaction();

                // 1. UPDATE MASTER
                string updateMasterQuery = @"
                                            UPDATE JobberOutwardMaster
                                            SET PartyId = @PartyId,
                                                OutwardListNo = @OutwardListNo,
                                                OutwardListDate = @OutwardListDate,
                                                TotalWeight = @TotalWeight,
                                                UserAccountId = @UserAccountId
                                            WHERE JobberOutwardID = @JobberOutwardID";

                using (SqlCommand cmd = new SqlCommand(updateMasterQuery, con, transaction))
                {
                    cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                    cmd.Parameters.AddWithValue("@PartyId", masterData.PartyId);
                    cmd.Parameters.AddWithValue("@OutwardListNo", masterData.OutwardListNo);
                    cmd.Parameters.AddWithValue("@OutwardListDate", Convert.ToDateTime(masterData.OutwardListDate));
                    cmd.Parameters.AddWithValue("@TotalWeight", masterData.TotalWeight);
                    cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                    cmd.ExecuteNonQuery();
                }

                // 2. DELETE OLD DETAILS
                string deleteDetailQuery = "DELETE FROM JobberOutwardDetail WHERE JobberOutwardID = @JobberOutwardID";
                using (SqlCommand cmd = new SqlCommand(deleteDetailQuery, con, transaction))
                {
                    cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                    cmd.ExecuteNonQuery();
                }

                // 3. INSERT REVISED DETAILS (Matching exact columns including CompanyPartyId and DetailsJson)
                if (masterData.Details != null && masterData.Details.Count > 0)
                {
                    string insertDetailQuery = @"
            INSERT INTO JobberOutwardDetail
            (DateAndTime,JobberOutwardID, BillToPartyID, YarnMaterialID, YarnColorID, NoOfBox, NetWeight, BarcodeNo, BoxNo, CompanyPartyId, YarnPOID, UserAccountId, DetailsJson)
            VALUES
            (getdate(),@JobberOutwardID, @BillToPartyId, @YarnMaterialID, @YarnColorID, @NoOfBox, @NetWeight, @BarcodeNo, @BoxNo, @CompanyPartyId, @YarnPOID, @UserAccountId, @DetailsJson)";


                    foreach (var item in masterData.Details)
                    {
                        using (SqlCommand cmd = new SqlCommand(insertDetailQuery, con, transaction))
                        {
                            cmd.Parameters.AddWithValue("@JobberOutwardID", outwardId);
                            cmd.Parameters.AddWithValue("@BillToPartyId", item.BillToPartyId);
                            cmd.Parameters.AddWithValue("@YarnMaterialID", item.YarnMaterialID);
                            cmd.Parameters.AddWithValue("@YarnColorID", item.YarnColorID);
                            cmd.Parameters.AddWithValue("@NoOfBox", item.NoOfBox > 0 ? item.NoOfBox : 1);
                            cmd.Parameters.AddWithValue("@NetWeight", item.NetWeight);
                            cmd.Parameters.AddWithValue("@BarcodeNo", item.BarcodeNo ?? "");
                            cmd.Parameters.AddWithValue("@BoxNo", item.BoxNo ?? "");
                            cmd.Parameters.AddWithValue("@CompanyPartyId", item.CompanyPartyId); // Fix: Use item's specific CompanyPartyId instead of masterData.PartyId
                            cmd.Parameters.AddWithValue("@YarnPOID", item.YarnPOID);
                            cmd.Parameters.AddWithValue("@UserAccountId", userAccountId);
                            cmd.Parameters.AddWithValue("@DetailsJson", (object)item.DetailsJson ?? DBNull.Value);

                            cmd.ExecuteNonQuery();
                        }
                    }
                }

                transaction.Commit();

                return JsonConvert.SerializeObject(new
                {
                    Code = 200,
                    Message = "Jobber Outward updated successfully."
                });
            }
            catch (Exception ex)
            {
                if (transaction != null)
                {
                    try { transaction.Rollback(); } catch { }
                }

                return JsonConvert.SerializeObject(new
                {
                    Code = 500,
                    Message = ex.Message
                });
            }
            finally
            {
                if (con != null)
                {
                    con.Close();
                    con.Dispose();
                }
            }
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ServiceResponse DeleteJobberOutwardMaster(int YarnOutwardID)
        {
            ServiceResponse response = new ServiceResponse();
            string connString = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection conn = new SqlConnection(connString))
            {
                conn.Open();
                using (SqlTransaction transaction = conn.BeginTransaction())
                {
                    try
                    {
                        // 1. Delete child records first to avoid foreign key violation
                        string deleteDetailQuery = "DELETE FROM JobberOutwardDetail WHERE JobberOutwardID = @JobberOutwardID";
                        using (SqlCommand cmdDetail = new SqlCommand(deleteDetailQuery, conn, transaction))
                        {
                            cmdDetail.Parameters.AddWithValue("@JobberOutwardID", YarnOutwardID);
                            cmdDetail.ExecuteNonQuery();
                        }

                        // 2. Delete parent record from JobberOutwardMaster
                        string deleteMasterQuery = "DELETE FROM JobberOutwardMaster WHERE JobberOutwardID = @JobberOutwardID";
                        using (SqlCommand cmdMaster = new SqlCommand(deleteMasterQuery, conn, transaction))
                        {
                            cmdMaster.Parameters.AddWithValue("@JobberOutwardID", YarnOutwardID);
                            cmdMaster.ExecuteNonQuery();
                        }

                        transaction.Commit();
                        response.Code = 200;
                        response.Message = "Jobber Outward deleted successfully.";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        response.Code = 500;
                        response.Message = "Database Error: " + ex.Message;
                    }
                }
            }
            return response;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public object GetPendingOrdersForProduction()
        {
            var orderList = new List<object>();
            try
            {
                string connString = System.Configuration.ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                string query = @"
                        WITH SOD_Seq AS (
                            SELECT 
                                sod.*,
                                DENSE_RANK() OVER (PARTITION BY sod.SaleOrderID ORDER BY sod.DetailID) AS DesignSeq
                            FROM SaleOrderDetails sod
                        ),
                        SOSD_Seq AS (
                            SELECT 
                                sods.*,
                                ROW_NUMBER() OVER (PARTITION BY sods.DetailID ORDER BY sods.SubDetailID) AS ColourSeq
                            FROM SaleOrderSubDetails sods
                        )
                        SELECT 
                            so.SaleOrderID AS SalesOrderID,
                            so.OrderNo,
                            CONVERT(varchar(10), so.OrderDate, 101) AS OrderDate,
                            so.PartyId AS PartyID,
                            pm.PartyName,
                            sod.DesignNo,
                            ISNULL(sods.ColourID, sod.DesignColorMatchingID) AS ColourMatchingID,
                            sods.ColourName,
                            ISNULL(NULLIF(dcmd.ColorMatchingPhoto, ''), ISNULL(defm.PhotoOfDesign, '')) AS PhotoPath,
                            sods.Qty AS TotalOrderPcs,
                            ISNULL(prodSum.AlreadyProducedPcs, 0) AS AlreadyProducedPcs,
                            CASE WHEN (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0)) < 0 THEN 0 ELSE (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0)) END AS Pcs,
                            CASE WHEN (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0)) < 0 THEN 0 ELSE (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0)) END AS PendingPcs,
                            sod.Rate,
                            sod.DetailID,
                            sods.SubDetailID,
                            ISNULL(defm.TotalCard, 0) AS TotalCard,
                            ISNULL(defm.PickOnLoom, 0) AS Pick,
                            sod.DesignSeq,
                            sods.ColourSeq
                        FROM SaleOrder so
                        INNER JOIN PartyMaster pm ON so.PartyId = pm.PartyId
                        INNER JOIN SOD_Seq sod ON so.SaleOrderID = sod.SaleOrderID
                        INNER JOIN SOSD_Seq sods ON sod.DetailID = sods.DetailID
                        LEFT JOIN DesignColorMatchingDetails dcmd ON ISNULL(sods.ColourID, sod.DesignColorMatchingID) = dcmd.DesignColorMatchingDetailsID
                        LEFT JOIN (
                            SELECT 
                                ISNULL(pod.SubDetailID, 0) AS SubDetailID,
                                pod.SalesOrderDetailID,
                                ISNULL(SUM(pod.ProductionPCS), 0) AS AlreadyProducedPcs
                            FROM ProductionOrderDetail pod
                            INNER JOIN ProductionOrderMaster pom ON pod.ProductionOrderID = pom.ProductionOrderID
                            WHERE ISNULL(pod.IsActive, 1) = 1 AND ISNULL(pom.IsActive, 1) = 1
                            GROUP BY pod.SubDetailID, pod.SalesOrderDetailID
                        ) prodSum ON (sods.SubDetailID > 0 AND prodSum.SubDetailID = sods.SubDetailID)
                            OR (sods.SubDetailID = 0 AND prodSum.SalesOrderDetailID = sod.DetailID)
                        LEFT JOIN (
                            SELECT DesignerCode, DesignNo, 
                                   MAX(CASE WHEN ISNUMERIC(TotalCard) = 1 THEN CONVERT(DECIMAL(18,2), TotalCard) ELSE 0 END) AS TotalCard, 
                                   MAX(CASE WHEN ISNUMERIC(PickOnLoom) = 1 THEN CONVERT(DECIMAL(18,2), PickOnLoom) ELSE 0 END) AS PickOnLoom,
                                   MAX(ISNULL(PhotoOfDesign, '')) AS PhotoOfDesign
                            FROM DesignEntryFormMaster
                            GROUP BY DesignerCode, DesignNo
                        ) defm
                        ON LTRIM(RTRIM(CASE WHEN CHARINDEX(' - ', sod.DesignNo) > 0 THEN SUBSTRING(sod.DesignNo, 1, CHARINDEX(' - ', sod.DesignNo) - 1) ELSE sod.DesignNo END)) = LTRIM(RTRIM(CONVERT(VARCHAR(100), defm.DesignerCode)))
                        AND LTRIM(RTRIM(CASE WHEN CHARINDEX(' - ', sod.DesignNo) > 0 THEN SUBSTRING(sod.DesignNo, CHARINDEX(' - ', sod.DesignNo) + 3, LEN(sod.DesignNo)) ELSE sod.DesignNo END)) = LTRIM(RTRIM(CONVERT(VARCHAR(100), defm.DesignNo)))
                        WHERE (sods.Qty - ISNULL(prodSum.AlreadyProducedPcs, 0)) > 0
                        ORDER BY so.OrderNo, sod.DetailID, sods.SubDetailID;";

                using (SqlConnection conn = new SqlConnection(connString))
                {
                    using (SqlCommand cmd = new SqlCommand(query, conn))
                    {
                        conn.Open();
                        using (SqlDataReader reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string rawPhoto = reader["PhotoPath"] != DBNull.Value ? reader["PhotoPath"].ToString().Trim() : "";
                                string normalizedPhoto = "";
                                if (!string.IsNullOrEmpty(rawPhoto))
                                {
                                    string clean = rawPhoto.Replace("\\", "/");
                                    if (clean.StartsWith("~/")) clean = clean.Substring(2);
                                    if (!clean.StartsWith("/")) clean = "/" + clean;
                                    normalizedPhoto = clean;
                                }

                                orderList.Add(new
                                {
                                    SalesOrderID = reader["SalesOrderID"] != DBNull.Value ? reader["SalesOrderID"].ToString() : null,
                                    SalesOrderDetailID = reader["DetailID"] != DBNull.Value ? reader["DetailID"].ToString() : "",
                                    PartyID = reader["PartyID"] != DBNull.Value ? reader["PartyID"].ToString() : null,
                                    ColourMatchingID = reader["ColourMatchingID"] != DBNull.Value ? reader["ColourMatchingID"].ToString() : null,
                                    OrderNo = reader["OrderNo"] != DBNull.Value ? reader["OrderNo"].ToString() : "",
                                    OrderDate = reader["OrderDate"] != DBNull.Value ? reader["OrderDate"].ToString() : "",
                                    PartyName = reader["PartyName"] != DBNull.Value ? reader["PartyName"].ToString() : "",
                                    DesignNo = reader["DesignNo"] != DBNull.Value ? reader["DesignNo"].ToString() : "",
                                    ColourName = reader["ColourName"] != DBNull.Value ? reader["ColourName"].ToString() : "",
                                    Qty = reader["Pcs"] != DBNull.Value ? Convert.ToDecimal(reader["Pcs"]) : 0,
                                    Pcs = reader["Pcs"] != DBNull.Value ? Convert.ToDecimal(reader["Pcs"]) : 0,
                                    TotalOrderPcs = reader["TotalOrderPcs"] != DBNull.Value ? Convert.ToDecimal(reader["TotalOrderPcs"]) : 0,
                                    AlreadyProducedPcs = reader["AlreadyProducedPcs"] != DBNull.Value ? Convert.ToDecimal(reader["AlreadyProducedPcs"]) : 0,
                                    PendingPcs = reader["PendingPcs"] != DBNull.Value ? Convert.ToDecimal(reader["PendingPcs"]) : 0,
                                    Rate = reader["Rate"] != DBNull.Value ? Convert.ToDecimal(reader["Rate"]) : 0,
                                    DetailID = reader["DetailID"] != DBNull.Value ? reader["DetailID"].ToString() : "",
                                    SubDetailID = reader["SubDetailID"] != DBNull.Value ? reader["SubDetailID"].ToString() : "",
                                    TotalCard = reader["TotalCard"] != DBNull.Value ? Convert.ToDecimal(reader["TotalCard"]) : 0,
                                    Pick = reader["Pick"] != DBNull.Value ? Convert.ToDecimal(reader["Pick"]) : 0,
                                    DesignSeq = reader["DesignSeq"] != DBNull.Value ? Convert.ToInt32(reader["DesignSeq"]) : 0,
                                    ColourSeq = reader["ColourSeq"] != DBNull.Value ? Convert.ToInt32(reader["ColourSeq"]) : 0,
                                    PhotoPath = normalizedPhoto,
                                    ColorMatchingPhoto = normalizedPhoto
                                });
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("GetPendingOrdersForProduction Error: " + ex.ToString());
            }

            return orderList;
        }


        #region Jobber Master
        // 1. GET ALL JOBBERS (List View)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public List<JobberViewModel> GetJobberList()
        {
            List<JobberViewModel> list = new List<JobberViewModel>();
            using (SqlConnection con = new SqlConnection(connString))
            {
                string query = "SELECT Id, JobberType, PartyName, MobileNumber, City FROM JobberMaster order by Id desc";
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    con.Open();
                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            JobberViewModel jobber = new JobberViewModel
                            {
                                Id = Convert.ToInt32(reader["Id"]),
                                JobberType = reader["JobberType"].ToString(),
                                PartyName = reader["PartyName"].ToString(),
                                MobileNumber = reader["MobileNumber"].ToString(),
                                City = reader["City"].ToString()
                            };
                            list.Add(jobber);
                        }
                    }
                }
            }
            return list;
        }
        // 2. VIEW SINGLE RECORD (Get details + single machine row columns)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public JobberViewModel GetJobberById(int id)
        {
            JobberViewModel jobber = null;
            using (SqlConnection con = new SqlConnection(connString))
            {
                con.Open();
                string query = "SELECT * FROM JobberMaster WHERE Id = @Id";
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@Id", id);
                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            jobber = new JobberViewModel
                            {
                                Id = Convert.ToInt32(reader["Id"]),
                                JobberType = reader["JobberType"].ToString(),
                                Gstin = reader["Gstin"]?.ToString(),
                                PanNo = reader["PanNo"]?.ToString(),
                                PartyName = reader["PartyName"].ToString(),
                                Prefix = reader["Prefix"]?.ToString(),
                                MobileNumber = reader["MobileNumber"].ToString(),
                                AlternateNumber = reader["AlternateNumber"]?.ToString(),
                                Email = reader["Email"]?.ToString(),
                                PlaceOfSupply = reader["PlaceOfSupply"]?.ToString(),
                                Pincode = reader["Pincode"]?.ToString(),
                                City = reader["City"].ToString(),
                                BankHolderName = reader["BankHolderName"]?.ToString(),
                                BankAcNo = reader["BankAcNo"]?.ToString(),
                                BankName = reader["BankName"]?.ToString(),
                                BankIfsc = reader["BankIfsc"]?.ToString(),
                                BankBranch = reader["BankBranch"]?.ToString(),
                                BillingAddress = reader["BillingAddress"]?.ToString(),
                                MachineType = reader["MachineType"]?.ToString(),
                                Rpm = reader["Rpm"] != DBNull.Value ? Convert.ToInt32(reader["Rpm"]) : 0,
                                PanaRepeat = reader["PanaRepeat"] != DBNull.Value ? Convert.ToInt32(reader["PanaRepeat"]) : 0,
                                PanaWidth = reader["PanaWidth"] != DBNull.Value ? Convert.ToInt32(reader["PanaWidth"]) : 0,
                                NoOfMachines = reader["NoOfMachines"] != DBNull.Value ? Convert.ToInt32(reader["NoOfMachines"]) : 0
                            };
                        }
                    }
                }
            }
            return jobber ?? new JobberViewModel();
        }
        // 3. INSERT / UPDATE (Save record saving machine columns directly)
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public bool SaveJobber(JobberViewModel model)
        {
            if (model == null) return false;

            // Extract UserAccountId and CompanyId safely from Cookies
            model.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            model.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);

            if (model.JobberType == null || !model.JobberType.Contains("Weaving"))
            {
                model.MachineType = string.Empty;
                model.Rpm = 0;
                model.PanaRepeat = 0;
                model.PanaWidth = 0;
                model.NoOfMachines = 0;
            }

            using (SqlConnection con = new SqlConnection(connString))
            {
                con.Open();
                try
                {
                    // --- CHECK DUPLICATE PREFIX ---
                    if (!string.IsNullOrEmpty(model.Prefix))
                    {
                        string checkQuery = "SELECT COUNT(1) FROM JobberMaster WHERE CompanyId = @CompanyId AND LTRIM(RTRIM(UPPER(Prefix))) = LTRIM(RTRIM(UPPER(@Prefix))) AND Id <> @Id";
                        using (SqlCommand checkCmd = new SqlCommand(checkQuery, con))
                        {
                            checkCmd.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                            checkCmd.Parameters.AddWithValue("@Prefix", model.Prefix.Trim());
                            checkCmd.Parameters.AddWithValue("@Id", model.Id); // Exclude current record during update

                            int existingCount = Convert.ToInt32(checkCmd.ExecuteScalar());
                            if (existingCount > 0)
                            {
                                // Duplicate prefix found, reject saving
                                return false;
                            }
                        }
                    }

                    long savedJobberId = model.Id;

                    if (model.Id == 0)
                    {
                        // --- INSERT LOGIC ---
                        string insertQuery = @"INSERT INTO JobberMaster 
                        (CompanyId, UserAccountId, DateAndTime, JobberType, Gstin, PanNo, PartyName, Prefix, MobileNumber, AlternateNumber, Email, PlaceOfSupply, Pincode, City, BankHolderName, BankAcNo, BankName, BankIfsc, BankBranch, BillingAddress, MachineType, Rpm, PanaRepeat, PanaWidth, NoOfMachines, IsActiveParty)
                        OUTPUT INSERTED.Id
                        VALUES 
                        (@CompanyId, @UserAccountId, GETDATE(), @JobberType, @Gstin, @PanNo, @PartyName, @Prefix, @MobileNumber, @AlternateNumber, @Email, @PlaceOfSupply, @Pincode, @City, @BankHolderName, @BankAcNo, @BankName, @BankIfsc, @BankBranch, @BillingAddress, @MachineType, @Rpm, @PanaRepeat, @PanaWidth, @NoOfMachines, @IsActiveParty)";

                        using (SqlCommand cmd = new SqlCommand(insertQuery, con))
                        {
                            AddJobberParameters(cmd, model);
                            savedJobberId = Convert.ToInt64(cmd.ExecuteScalar());
                        }

                        // --- JOBBER USER ACCOUNT CREATION (INSERT) ---
                        if (savedJobberId > 0)
                        {
                            string checkUserQuery = @"SELECT COUNT(1) FROM UserAccountMaster 
                                                      WHERE CompanyId = @CompanyId 
                                                      AND (PartyId = @PartyId OR (UserAccountMobileNo = @MobileNo AND @MobileNo IS NOT NULL AND @MobileNo <> ''))";
                            int userExists = 0;

                            using (SqlCommand cmdCheckUser = new SqlCommand(checkUserQuery, con))
                            {
                                cmdCheckUser.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                                cmdCheckUser.Parameters.AddWithValue("@PartyId", savedJobberId);
                                cmdCheckUser.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                                userExists = Convert.ToInt32(cmdCheckUser.ExecuteScalar());
                            }

                            if (userExists > 0)
                            {
                                // Update existing user account linked to this party/mobile
                                string updateUserQuery = @"
                                        UPDATE UserAccountMaster 
                                        SET UserAccountName = @UserAccountName, 
                                            UserAccountMobileNo = @MobileNo,
                                            UserAccountEmail = @Email,
                                            UserRole = 'Job Work',
                                            PartyId = @PartyId
                                        WHERE CompanyId = @CompanyId 
                                        AND (PartyId = @PartyId OR (UserAccountMobileNo = @MobileNo AND @MobileNo IS NOT NULL AND @MobileNo <> ''))";

                                using (SqlCommand cmdUserUpdate = new SqlCommand(updateUserQuery, con))
                                {
                                    cmdUserUpdate.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                                    cmdUserUpdate.Parameters.AddWithValue("@UserAccountName", model.PartyName ?? (object)DBNull.Value);
                                    cmdUserUpdate.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                                    cmdUserUpdate.Parameters.AddWithValue("@Email", string.IsNullOrWhiteSpace(model.Email) ? ("jobber_" + savedJobberId + "@noemail.local") : model.Email.Trim());
                                    cmdUserUpdate.Parameters.AddWithValue("@PartyId", savedJobberId);

                                    cmdUserUpdate.ExecuteNonQuery();
                                }
                            }
                            else
                            {
                                // Insert new user account
                                string insertUserQuery = @"
                                    INSERT INTO UserAccountMaster
                                    (UserAccountDateAndTime, CompanyId, UserAccountName, UserRole, UserAccountMobileNo, UserAccountEmail, UserAccountPassword, AllowLogin, PartyId)
                                    VALUES
                                    (GETDATE(), @CompanyId, @UserAccountName, 'Job Work', @MobileNo, @Email, @Password, 1, @PartyId)";

                                using (SqlCommand cmdUser = new SqlCommand(insertUserQuery, con))
                                {
                                    cmdUser.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                                    cmdUser.Parameters.AddWithValue("@UserAccountName", model.PartyName ?? (object)DBNull.Value);
                                    cmdUser.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                                    cmdUser.Parameters.AddWithValue("@Password", getMd5Hash(string.IsNullOrEmpty(model.MobileNumber) ? "123456" : model.MobileNumber.Trim()));
                                    cmdUser.Parameters.AddWithValue("@Email", string.IsNullOrWhiteSpace(model.Email) ? ("jobber_" + savedJobberId + "@noemail.local") : model.Email.Trim());
                                    cmdUser.Parameters.AddWithValue("@PartyId", savedJobberId);

                                    cmdUser.ExecuteNonQuery();
                                }
                            }
                        }
                    }
                    else
                    {
                        // --- UPDATE LOGIC ---
                        string updateQuery = @"UPDATE JobberMaster SET CompanyId=@CompanyId, UserAccountId=@UserAccountId,
                        JobberType=@JobberType, Gstin=@Gstin, PanNo=@PanNo, PartyName=@PartyName, Prefix=@Prefix, 
                        MobileNumber=@MobileNumber, AlternateNumber=@AlternateNumber, Email=@Email, PlaceOfSupply=@PlaceOfSupply, 
                        Pincode=@Pincode, City=@City, BankHolderName=@BankHolderName, BankAcNo=@BankAcNo, 
                        BankName=@BankName, BankIfsc=@BankIfsc, BankBranch=@BankBranch, BillingAddress=@BillingAddress,
                        MachineType=@MachineType, Rpm=@Rpm, PanaRepeat=@PanaRepeat, PanaWidth=@PanaWidth, NoOfMachines=@NoOfMachines,
                        IsActiveParty=@IsActiveParty
                        WHERE Id=@Id";

                        using (SqlCommand cmd = new SqlCommand(updateQuery, con))
                        {
                            AddJobberParameters(cmd, model);
                            cmd.Parameters.AddWithValue("@Id", model.Id);
                            cmd.ExecuteNonQuery();
                        }

                        // --- JOBBER USER ACCOUNT SYNC (UPDATE / INSERT IF MISSING) ---
                        string checkUserQuery = @"SELECT COUNT(1) FROM UserAccountMaster 
                                                  WHERE CompanyId = @CompanyId 
                                                  AND (PartyId = @PartyId OR (UserAccountMobileNo = @MobileNo AND @MobileNo IS NOT NULL AND @MobileNo <> ''))";
                        int userExists = 0;

                        using (SqlCommand cmdCheckUser = new SqlCommand(checkUserQuery, con))
                        {
                            cmdCheckUser.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                            cmdCheckUser.Parameters.AddWithValue("@PartyId", model.Id);
                            cmdCheckUser.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                            userExists = Convert.ToInt32(cmdCheckUser.ExecuteScalar());
                        }

                        if (userExists > 0)
                        {
                            string updateUserQuery = @"
                            UPDATE UserAccountMaster 
                            SET UserAccountName = @UserAccountName, 
                                UserAccountMobileNo = @MobileNo, 
                                UserAccountEmail = @Email,
                                UserRole = 'Job Work',
                                PartyId = @PartyId 
                            WHERE CompanyId = @CompanyId 
                            AND (PartyId = @PartyId OR (UserAccountMobileNo = @MobileNo AND @MobileNo IS NOT NULL AND @MobileNo <> ''))";

                            using (SqlCommand cmdUserUpdate = new SqlCommand(updateUserQuery, con))
                            {
                                cmdUserUpdate.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                                cmdUserUpdate.Parameters.AddWithValue("@UserAccountName", model.PartyName ?? (object)DBNull.Value);
                                cmdUserUpdate.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                                cmdUserUpdate.Parameters.AddWithValue("@Email", string.IsNullOrWhiteSpace(model.Email) ? ("jobber_" + model.Id + "@noemail.local") : model.Email.Trim());
                                cmdUserUpdate.Parameters.AddWithValue("@PartyId", model.Id);

                                cmdUserUpdate.ExecuteNonQuery();
                            }
                        }
                        else
                        {
                            // If UserAccountMaster record does not exist for this Jobber, create a new one on update
                            string insertUserQuery = @"
                                INSERT INTO UserAccountMaster
                                (UserAccountDateAndTime, CompanyId, UserAccountName, UserRole, UserAccountMobileNo, UserAccountEmail, UserAccountPassword, AllowLogin, PartyId)
                                VALUES
                                (GETDATE(), @CompanyId, @UserAccountName, 'Job Work', @MobileNo, @Email, @Password, 1, @PartyId)";

                            using (SqlCommand cmdUser = new SqlCommand(insertUserQuery, con))
                            {
                                cmdUser.Parameters.AddWithValue("@CompanyId", model.CompanyId);
                                cmdUser.Parameters.AddWithValue("@UserAccountName", model.PartyName ?? (object)DBNull.Value);
                                cmdUser.Parameters.AddWithValue("@MobileNo", string.IsNullOrEmpty(model.MobileNumber) ? (object)DBNull.Value : model.MobileNumber.Trim());
                                cmdUser.Parameters.AddWithValue("@Password", getMd5Hash(string.IsNullOrEmpty(model.MobileNumber) ? "123456" : model.MobileNumber.Trim()));
                                cmdUser.Parameters.AddWithValue("@Email", string.IsNullOrWhiteSpace(model.Email) ? (model.PartyName + "@noemail.local") : model.Email.Trim());
                                cmdUser.Parameters.AddWithValue("@PartyId", model.Id);
                                cmdUser.ExecuteNonQuery();
                            }
                        }
                    }
                    return true;
                }
                catch (Exception ex)
                {
                    // Optional: Log exception here for debugging
                    return false;
                }
            }
        }
        private void AddJobberParameters(SqlCommand cmd, JobberViewModel model)
        {
            cmd.Parameters.AddWithValue("@CompanyId", model.CompanyId); // Pull from session context if needed
            cmd.Parameters.AddWithValue("@UserAccountId", model.UserAccountId); // Pull from session context if needed
            cmd.Parameters.AddWithValue("@JobberType", model.JobberType ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@Gstin", model.Gstin ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@PanNo", model.PanNo ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@PartyName", model.PartyName ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@Prefix", model.Prefix ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@MobileNumber", model.MobileNumber ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@AlternateNumber", model.AlternateNumber ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@Email", model.Email ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@PlaceOfSupply", model.PlaceOfSupply ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@Pincode", model.Pincode ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@City", model.City ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BankHolderName", model.BankHolderName ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BankAcNo", model.BankAcNo ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BankName", model.BankName ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BankIfsc", model.BankIfsc ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BankBranch", model.BankBranch ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@BillingAddress", model.BillingAddress ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@MachineType", model.MachineType ?? (object)DBNull.Value);
            cmd.Parameters.AddWithValue("@Rpm", model.Rpm);
            cmd.Parameters.AddWithValue("@PanaRepeat", model.PanaRepeat);
            cmd.Parameters.AddWithValue("@PanaWidth", model.PanaWidth);
            cmd.Parameters.AddWithValue("@NoOfMachines", model.NoOfMachines);
            cmd.Parameters.AddWithValue("@IsActiveParty", model.IsActiveParty);
        }
        // 4. DELETE RECORD
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public bool DeleteJobber(int id)
        {
            try
            {
                using (SqlConnection con = new SqlConnection(connString))
                {
                    string query = @"
                DELETE FROM JobberMaster
                WHERE Id = @Id";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.Parameters.AddWithValue("@Id", id);

                        con.Open();

                        int rowsAffected = cmd.ExecuteNonQuery();

                        return rowsAffected > 0;
                    }
                }
            }
            catch (Exception ex)
            {
                throw new Exception("Error deleting Jobber: " + ex.Message);
            }
        }
