        #region ProductionSleep
        [WebMethod]
        public List<JobberMasterClass> GetJobberMaster()
        {
            List<JobberMasterClass> list =
                new List<JobberMasterClass>();

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                using (SqlCommand cmd =
                       new SqlCommand())
                {
                    cmd.Connection = con;

                    cmd.CommandType =
                        CommandType.Text;

                    cmd.CommandText = @"
             SELECT
                Id AS JobberMasterID,
                PartyName AS JobberName,
                Rpm,
                PanaRepeat,
                PanaWidth,
                NoOfMachines
            FROM JobberMaster
            WHERE ISNULL(IsActiveParty, 1) = 1
            ORDER BY PartyName
            ";

                    con.Open();

                    using (SqlDataReader rdr =
                           cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            JobberMasterClass item =
                                new JobberMasterClass();

                            item.JobberMasterID =
                                rdr["JobberMasterID"] ==
                                DBNull.Value
                                    ? 0
                                    : Convert.ToInt32(
                                        rdr["JobberMasterID"]
                                    );

                            item.JobberName =
                                rdr["JobberName"] ==
                                DBNull.Value
                                    ? ""
                                    : rdr["JobberName"]
                                        .ToString();

                            item.Rpm =
                                rdr["Rpm"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["Rpm"]
                                        .ToString();

                            item.PanaRepeat =
                                rdr["PanaRepeat"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["PanaRepeat"]
                                        .ToString();

                            item.PanaWidth =
                                rdr["PanaWidth"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["PanaWidth"]
                                        .ToString();

                            item.NoOfMachines =
                                rdr["NoOfMachines"] ==
                                DBNull.Value
                                    ? "0"
                                    : rdr["NoOfMachines"]
                                        .ToString();

                            list.Add(item);
                        }
                    }
                }
            }

            return list;
        }
        /// <summary>
        /// GetProductionOrderList
        /// </summary>
        /// <returns></returns>
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public List<ProductionOrderListItem> GetProductionOrderList()
        {
            var list = new List<ProductionOrderListItem>();

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                con.Open();

                /*
                 * IMPORTANT:
                 * Do not filter the list by CompanyId here.
                 *
                 * Older ProductionOrderMaster rows can have CompanyId = NULL
                 * (for example records saved before CompanyId was added).
                 * Filtering those rows by the default company would make the
                 * list show 0 records even though Production Orders exist.
                 *
                 * Company-wise filtering can be added later once every
                 * ProductionOrderMaster row has a valid CompanyId.
                 */
                const string sql = @"
SELECT
    POM.ProductionOrderID,
    POM.ProductionOrderNo,
    POM.ProductionOrderDate,
    POM.JobWorkerID,
    POM.JobWorkerName,
    POM.PanaRepeat,
    POM.JobRate,
    POM.Traders,
    POM.TotalPcs,
    POM.TotalProductionPcs,
    POM.TotalPendingPcs,
    POM.TotalAmount,
    POM.Status,
    POM.CompanyId,
    POM.UserAccountId,
    ISNULL(D.DetailCount, 0) AS DetailCount
FROM ProductionOrderMaster POM
OUTER APPLY
(
    SELECT COUNT(1) AS DetailCount
    FROM ProductionOrderDetail POD
    WHERE POD.ProductionOrderID = POM.ProductionOrderID
      AND POD.IsActive = 1
) D
WHERE POM.IsActive = 1
ORDER BY
    POM.ProductionOrderID DESC;";

                using (SqlCommand cmd =
                       new SqlCommand(sql, con))
                {
                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        while (dr.Read())
                        {
                            var item =
                                new ProductionOrderListItem();

                            item.ProductionOrderID =
                                ToLong(dr["ProductionOrderID"]);

                            item.ProductionOrderNo =
                                ToStringValue(
                                    dr["ProductionOrderNo"]);

                            item.ProductionOrderDate =
                                ToDateValue(
                                    dr["ProductionOrderDate"]);

                            item.JobWorkerID =
                                ToNullableLong(
                                    dr["JobWorkerID"]);

                            item.JobWorkerName =
                                ToStringValue(
                                    dr["JobWorkerName"]);

                            item.PanaRepeat =
                                ToDecimalValue(
                                    dr["PanaRepeat"]);

                            item.JobRate =
                                ToDecimalValue(
                                    dr["JobRate"]);

                            item.Traders =
                                ToStringValue(
                                    dr["Traders"]);

                            item.TotalPcs =
                                ToDecimalValue(
                                    dr["TotalPcs"]);

                            item.TotalProductionPcs =
                                ToDecimalValue(
                                    dr["TotalProductionPcs"]);

                            item.TotalPendingPcs =
                                ToDecimalValue(
                                    dr["TotalPendingPcs"]);

                            item.TotalAmount =
                                ToDecimalValue(
                                    dr["TotalAmount"]);

                            item.Status =
                                ToIntValue(
                                    dr["Status"]);

                            item.CompanyId =
                                ToNullableLong(
                                    dr["CompanyId"]);

                            item.UserAccountId =
                                ToNullableLong(
                                    dr["UserAccountId"]);

                            item.DetailCount =
                                ToIntValue(
                                    dr["DetailCount"]);

                            list.Add(item);
                        }
                    }
                }
            }

            return list;
        }


        /*
         * ================================================================
         * PRODUCTION ORDER BY ID
         * ================================================================
         *
         * Used for:
         * Edit / View Production Order
         *
         * URL:
         * WebServiceNikunjTextile.asmx/GetProductionOrderByID
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderByIDResponse GetProductionOrderByID(
            long ProductionOrderID)
        {
            var result =
                new ProductionOrderByIDResponse
                {
                    Success = false,
                    Message = "",
                    Master = null,
                    Details =
                        new List<ProductionOrderDetailListItem>()
                };

            if (ProductionOrderID <= 0)
            {
                result.Message =
                    "Invalid Production Order ID.";

                return result;
            }

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                con.Open();

                const string masterSql = @"
SELECT TOP 1
    ProductionOrderID,
    ProductionOrderNo,
    ProductionOrderDate,
    JobWorkerID,
    JobWorkerName,
    PanaRepeat,
    JobRate,
    Traders,
    TotalPcs,
    TotalProductionPcs,
    TotalPendingPcs,
    TotalAmount,
    Status,
    CompanyId,
    UserAccountId,
    (
        SELECT COUNT(1)
        FROM ProductionOrderDetail D
        WHERE D.ProductionOrderID =
              P.ProductionOrderID
          AND D.IsActive = 1
    ) AS DetailCount
FROM ProductionOrderMaster P
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1;";

                using (SqlCommand cmd =
                       new SqlCommand(
                           masterSql,
                           con))
                {
                    cmd.Parameters.Add(
                        "@ProductionOrderID",
                        SqlDbType.BigInt
                    ).Value =
                        ProductionOrderID;

                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        if (!dr.Read())
                        {
                            result.Message =
                                "Production Order not found.";

                            return result;
                        }

                        result.Master =
                            new ProductionOrderListItem
                            {
                                ProductionOrderID =
                                    ToLong(
                                        dr["ProductionOrderID"]),

                                ProductionOrderNo =
                                    ToStringValue(
                                        dr["ProductionOrderNo"]),

                                ProductionOrderDate =
                                    ToDateValue(
                                        dr["ProductionOrderDate"]),

                                JobWorkerID =
                                    ToNullableLong(
                                        dr["JobWorkerID"]),

                                JobWorkerName =
                                    ToStringValue(
                                        dr["JobWorkerName"]),

                                PanaRepeat =
                                    ToDecimalValue(
                                        dr["PanaRepeat"]),

                                JobRate =
                                    ToDecimalValue(
                                        dr["JobRate"]),

                                Traders =
                                    ToStringValue(
                                        dr["Traders"]),

                                TotalPcs =
                                    ToDecimalValue(
                                        dr["TotalPcs"]),

                                TotalProductionPcs =
                                    ToDecimalValue(
                                        dr["TotalProductionPcs"]),

                                TotalPendingPcs =
                                    ToDecimalValue(
                                        dr["TotalPendingPcs"]),

                                TotalAmount =
                                    ToDecimalValue(
                                        dr["TotalAmount"]),

                                Status =
                                    ToIntValue(
                                        dr["Status"]),

                                CompanyId =
                                    ToNullableLong(
                                        dr["CompanyId"]),

                                UserAccountId =
                                    ToNullableLong(
                                        dr["UserAccountId"]),

                                DetailCount =
                                    ToIntValue(
                                        dr["DetailCount"])
                            };
                    }
                }


                const string detailSql = @"
SELECT *
FROM ProductionOrderDetail
WHERE ProductionOrderID = @ProductionOrderID
  AND IsActive = 1
ORDER BY ProductionOrderDetailID ASC;";

                using (SqlCommand cmd =
                       new SqlCommand(
                           detailSql,
                           con))
                {
                    cmd.Parameters.Add(
                        "@ProductionOrderID",
                        SqlDbType.BigInt
                    ).Value =
                        ProductionOrderID;

                    using (SqlDataReader dr =
                           cmd.ExecuteReader())
                    {
                        while (dr.Read())
                        {
                            result.Details.Add(
                                new ProductionOrderDetailListItem
                                {
                                    ProductionOrderDetailID =
                                        ToLong(
                                            dr["ProductionOrderDetailID"]),

                                    ProductionOrderID =
                                        ToLong(
                                            dr["ProductionOrderID"]),

                                    SalesOrderID =
                                        ToNullableLong(
                                            dr["SalesOrderID"]),

                                    SalesOrderDetailID =
                                        ToNullableLong(
                                            dr["SalesOrderDetailID"]),

                                    SubDetailID =
                                        ToNullableLong(
                                            dr["SubDetailID"]),

                                    SalesOrderNo =
                                        ToStringValue(
                                            dr["SalesOrderNo"]),

                                    SlipNo =
                                        ToStringValue(
                                            dr["SlipNo"]),

                                    Barcode =
                                        ToStringValue(
                                            dr["Barcode"]),

                                    OrderDate =
                                        ToDateString(
                                            dr["OrderDate"]),

                                    PartyID =
                                        ToNullableLong(
                                            dr["PartyID"]),

                                    PartyName =
                                        ToStringValue(
                                            dr["PartyName"]),

                                    DesignEntryFormID =
                                        ToNullableLong(
                                            dr["DesignEntryFormID"]),

                                    DesignNo =
                                        ToStringValue(
                                            dr["DesignNo"]),

                                    ColourMatchingID =
                                        ToNullableLong(
                                            dr["ColourMatchingID"]),

                                    ColourMatchingName =
                                        ToStringValue(
                                            dr["ColourMatchingName"]),

                                    WarpQuality =
                                        ToStringValue(
                                            dr["WarpQuality"]),

                                    WeftQuality =
                                        ToStringValue(
                                            dr["WeftQuality"]),

                                    PCS =
                                        ToDecimalValue(
                                            dr["PCS"]),

                                    ProductionPCS =
                                        ToDecimalValue(
                                            dr["ProductionPCS"]),

                                    PendingPCS =
                                        ToDecimalValue(
                                            dr["PendingPCS"]),

                                    SalesRate =
                                        ToDecimalValue(
                                            dr["SalesRate"]),

                                    JobRate =
                                        ToDecimalValue(
                                            dr["JobRate"]),

                                    Amount =
                                        ToDecimalValue(
                                            dr["Amount"]),

                                    Rpm =
                                        HasColumn(dr, "Rpm") ? ToDecimalValue(dr["Rpm"]) : 0m,

                                    PanaRepeat =
                                        HasColumn(dr, "PanaRepeat") ? ToDecimalValue(dr["PanaRepeat"]) : 0m,

                                    PanaWidth =
                                        HasColumn(dr, "PanaWidth") ? ToDecimalValue(dr["PanaWidth"]) : 0m,

                                    NoOfMachines =
                                        HasColumn(dr, "NoOfMachines") ? ToDecimalValue(dr["NoOfMachines"]) : 0m,

                                    RepPCS =
                                        HasColumn(dr, "RepPCS") ? ToDecimalValue(dr["RepPCS"]) : 0m,

                                    RepRate =
                                        HasColumn(dr, "RepRate") ? ToDecimalValue(dr["RepRate"]) : 0m,

                                    RepAmt =
                                        HasColumn(dr, "RepAmt") ? ToDecimalValue(dr["RepAmt"]) : 0m,

                                    JobberAccept =
                                        HasColumn(dr, "JobberAccept") ? ToIntValue(dr["JobberAccept"]) : 0,

                                    CompanyId =
                                        ToNullableLong(
                                            dr["CompanyId"]),

                                    UserAccountId =
                                        ToNullableLong(
                                            dr["UserAccountId"])
                                }
                            );
                        }
                    }
                }
            }

            result.Success = true;
            result.Message =
                "Production Order loaded successfully.";

            return result;
        }


        /*
         * ================================================================
         * PRODUCTION ORDER BY ENCRYPTED ID
         * ================================================================
         *
         * Used by:
         * ProductionSleep.cshtml
         *
         * URL:
         * /ProductionSleep?ProductionOrderID=<ENCRYPTED>
         *
         * The existing getEncryptID WebMethod returns the encrypted ID.
         * This method decrypts that value on the server and then uses the
         * existing GetProductionOrderByID method.
         *
         * The browser therefore never needs to put the numeric ID in the
         * URL or send the numeric ID directly for the edit/view page.
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderByIDResponse GetProductionOrderByEncryptedID(
            string EncryptedID)
        {
            var result =
                new ProductionOrderByIDResponse
                {
                    Success = false,
                    Message = "",
                    Master = null,
                    Details =
                        new List<ProductionOrderDetailListItem>()
                };

            if (string.IsNullOrWhiteSpace(EncryptedID))
            {
                result.Message =
                    "Encrypted Production Order ID is required.";

                return result;
            }

            try
            {
                /*
                 * IMPORTANT:
                 *
                 * ProductionOrderList uses the existing project
                 * getEncryptID WebMethod. That value is NOT plain Base64.
                 *
                 * Example URL:
                 *
                 * ProductionOrderID=
                 * rq5q6i50XyKd...Vw%253d%253d
                 *
                 * Browser URLSearchParams may already decode one layer.
                 * Still remove any remaining URL encoding here so both
                 * %3D and %253D style values are supported.
                 */
                string encryptedValue =
                    EncryptedID.Trim();

                for (int i = 0; i < 3; i++)
                {
                    string decoded =
                        System.Web.HttpUtility.UrlDecode(
                            encryptedValue
                        );

                    if (decoded == encryptedValue)
                    {
                        break;
                    }

                    encryptedValue = decoded;
                }

                if (string.IsNullOrWhiteSpace(encryptedValue))
                {
                    result.Message =
                        "Encrypted Production Order ID is required.";

                    return result;
                }

                long directID;
                if (long.TryParse(encryptedValue, out directID) && directID > 0)
                {
                    return GetProductionOrderByID(directID);
                }

                string decryptedValue = Decrypt(encryptedValue);

                if (string.IsNullOrWhiteSpace(decryptedValue))
                {
                    result.Message =
                        "Invalid encrypted Production Order ID.";

                    return result;
                }

                decryptedValue =
                    decryptedValue.Trim();

                /*
                 * Some existing encrypted values may contain:
                 *
                 * 17|Edit
                 * 17|View
                 *
                 * In that case the first part is the ProductionOrderID.
                 */
                if (decryptedValue.Contains("|"))
                {
                    decryptedValue =
                        decryptedValue.Split('|')[0];
                }

                long productionOrderID;

                if (!long.TryParse(
                        decryptedValue,
                        out productionOrderID) ||
                    productionOrderID <= 0)
                {
                    result.Message =
                        "Invalid encrypted Production Order ID.";

                    return result;
                }

                /*
                 * Reuse the existing DB binding method.
                 */
                return GetProductionOrderByID(
                    productionOrderID
                );
            }
            catch (Exception ex)
            {
                /*
                 * Do not expose Base64/FormatException-specific errors.
                 * Return one clean message to the frontend.
                 */
                result.Message =
                    string.IsNullOrWhiteSpace(ex.Message)
                        ? "Invalid encrypted Production Order ID."
                        : ex.Message;

                return result;
            }
        }

        /*
         * ================================================================
         * DELETE PRODUCTION ORDER
         * ================================================================
         *
         * Hard delete:
         *
         * Delete details and master records physically from DB.
         */
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderDeleteResponse DeleteProductionOrder(
            long ProductionOrderID)
        {
            var result =
                new ProductionOrderDeleteResponse
                {
                    Success = false,
                    Message = "",
                    ProductionOrderID =
                        ProductionOrderID
                };

            if (ProductionOrderID <= 0)
            {
                result.Message =
                    "Invalid Production Order ID.";

                return result;
            }

            string connectionString =
                ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

            using (SqlConnection con =
                   new SqlConnection(connectionString))
            {
                con.Open();

                using (SqlTransaction tran =
                       con.BeginTransaction(
                           IsolationLevel.ReadCommitted))
                {
                    try
                    {
                        EnsureProductionOrderSubDetailTableExists(con, tran);

                        /*
                         * Check master.
                         */
                        const string checkSql = @"
SELECT COUNT(1)
FROM ProductionOrderMaster
WHERE ProductionOrderID = @ProductionOrderID;";

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   checkSql,
                                   con,
                                   tran))
                        {
                            cmd.Parameters.Add(
                                "@ProductionOrderID",
                                SqlDbType.BigInt
                            ).Value =
                                ProductionOrderID;

                            int exists =
                                Convert.ToInt32(
                                    cmd.ExecuteScalar());

                            if (exists == 0)
                            {
                                tran.Rollback();

                                result.Message =
                                    "Production Order not found or already deleted.";

                                return result;
                            }
                        }

                        /*
                         * Check if any ACTIVE subdetail allocations exist in ProductionOrderSubDetail
                         */
                        const string checkActiveSubSql = @"
SELECT COUNT(1)
FROM ProductionOrderSubDetail
WHERE (ProductionOrderID = @ProductionOrderID 
       OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID))
  AND ISNULL(IsActive, 1) = 1;";

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   checkActiveSubSql,
                                   con,
                                   tran))
                        {
                            cmd.Parameters.Add(
                                "@ProductionOrderID",
                                SqlDbType.BigInt
                            ).Value =
                                ProductionOrderID;

                            int activeSubCount =
                                Convert.ToInt32(
                                    cmd.ExecuteScalar());

                            if (activeSubCount > 0)
                            {
                                tran.Rollback();

                                result.Success = false;
                                result.Message =
                                    "this order use JOBPRODUCTIONO";

                                return result;
                            }
                        }

                        /*
                         * Delete inactive subdetails (IsActive = 0) from ProductionOrderSubDetail
                         */
                        const string deleteSubDetailSql = @"
DELETE FROM ProductionOrderSubDetail
WHERE ProductionOrderID = @ProductionOrderID 
   OR ProductionOrderDetailID IN (SELECT ProductionOrderDetailID FROM ProductionOrderDetail WHERE ProductionOrderID = @ProductionOrderID);";

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   deleteSubDetailSql,
                                   con,
                                   tran))
                        {
                            cmd.Parameters.Add(
                                "@ProductionOrderID",
                                SqlDbType.BigInt
                            ).Value =
                                ProductionOrderID;

                            cmd.ExecuteNonQuery();
                        }


                        /*
                         * Delete details first.
                         */
                        const string detailDeleteSql = @"
DELETE FROM ProductionOrderDetail
WHERE ProductionOrderID = @ProductionOrderID;";

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   detailDeleteSql,
                                   con,
                                   tran))
                        {
                            cmd.Parameters.Add(
                                "@ProductionOrderID",
                                SqlDbType.BigInt
                            ).Value =
                                ProductionOrderID;

                            cmd.ExecuteNonQuery();
                        }


                        /*
                         * Delete master.
                         */
                        const string masterDeleteSql = @"
DELETE FROM ProductionOrderMaster
WHERE ProductionOrderID = @ProductionOrderID;";

                        using (SqlCommand cmd =
                               new SqlCommand(
                                   masterDeleteSql,
                                   con,
                                   tran))
                        {
                            cmd.Parameters.Add(
                                "@ProductionOrderID",
                                SqlDbType.BigInt
                            ).Value =
                                ProductionOrderID;

                            int affected =
                                cmd.ExecuteNonQuery();

                            if (affected <= 0)
                            {
                                tran.Rollback();

                                result.Message =
                                    "Production Order could not be deleted.";

                                return result;
                            }
                        }

                        tran.Commit();

                        result.Success = true;
                        result.Message =
                            "Production Order deleted successfully.";

                        return result;
                    }
                    catch (Exception ex)
                    {
                        try
                        {
                            tran.Rollback();
                        }
                        catch
                        {
                        }

                        result.Success = false;
                        result.Message = ex.Message;

                        return result;
                    }
                }
            }
        }


        /*
         * ================================================================
         * DEFAULT COMPANY - LIST
         * ================================================================
         */
        private static long? GetDefaultCompanyIdForList(
            SqlConnection con)
        {
            const string sql = @"
SELECT TOP 1 CompanyId
FROM CompanyMaster
WHERE is_default = 1
ORDER BY CompanyId;";

            using (SqlCommand cmd =
                   new SqlCommand(sql, con))
            {
                object value =
                    cmd.ExecuteScalar();

                if (value != null &&
                    value != DBNull.Value)
                {
                    return Convert.ToInt64(value);
                }
            }

            return null;
        }


        /*
         * ================================================================
         * SAFE CONVERSION HELPERS
         * ================================================================
         */
        private static string ToStringValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return "";
            }

            return Convert.ToString(value).Trim();
        }

        private static long ToLong(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0;
            }

            return Convert.ToInt64(value);
        }

        private static long? ToNullableLong(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return null;
            }

            return Convert.ToInt64(value);
        }

        private static int ToIntValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0;
            }

            return Convert.ToInt32(value);
        }

        private static decimal ToDecimalValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return 0m;
            }

            return Convert.ToDecimal(value);
        }

        private static DateTime ToDateValue(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return DateTime.MinValue;
            }

            return Convert.ToDateTime(value);
        }

        private static string ToDateString(object value)
        {
            if (value == null ||
                value == DBNull.Value)
            {
                return "";
            }

            return Convert
                .ToDateTime(value)
                .ToString("yyyy-MM-dd");
        }



        /// <summary>
        /// SaveProductionOrder
        /// </summary>
        /// <param name="request"></param>
        /// <returns></returns>
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public ProductionOrderSaveResponse SaveProductionOrder(ProductionOrderRequest request)
        {
            var result = new ProductionOrderSaveResponse
            {
                Success = false,
                ProductionOrderID = 0,
                InsertedDetails = 0,
                UpdatedDetails = 0,
                DeletedDetails = 0
            };

            if (request == null)
            {
                result.Message = "Production Order data is required.";
                return result;
            }

            if (request.listProductionOrderDetail == null ||
                request.listProductionOrderDetail.Count == 0)
            {
                result.Message = "Please select at least one Production Order detail.";
                return result;
            }

            DateTime productionDate;

            if (!TryParseDate(request.ProductionOrderDate, out productionDate))
            {
                result.Message = "Production Order Date is invalid.";
                return result;
            }

            string connectionString = ConfigurationManager
                .ConnectionStrings["sqlconnstr"]
                .ConnectionString;

            using (SqlConnection con = new SqlConnection(connectionString))
            {
                con.Open();

                using (SqlTransaction tran =
                       con.BeginTransaction(IsolationLevel.ReadCommitted))
                {
                    try
                    {
                        /*
                         * =====================================================
                         * CURRENT USER + DEFAULT COMPANY
                         * =====================================================
                         *
                         * UserAccountId:
                         * Context.Request.Cookies["UserIDs"]
                         *
                         * CompanyId:
                         * CompanyMaster where is_default = 1
                         */
                        long? currentUserAccountId =
                            GetCurrentUserAccountId();

                        long? currentCompanyId =
                            GetDefaultCompanyId(con, tran);

                        /*
                         * If your application requires these values,
                         * do not silently save NULL.
                         */
                        if (!currentUserAccountId.HasValue)
                        {
                            tran.Rollback();

                            result.Message =
                                "UserAccountId could not be found from UserIDs cookie.";

                            return result;
                        }

                        if (!currentCompanyId.HasValue)
                        {
                            tran.Rollback();

                            result.Message =
                                "Default CompanyId could not be found from CompanyMaster.";

                            return result;
                        }

                        long productionOrderID =
                            request.ProductionOrderID;

                        bool isInsert =
                            productionOrderID <= 0;

                        decimal totalPcs = 0m;
                        decimal totalProductionPcs = 0m;
                        decimal totalPendingPcs = 0m;
                        decimal totalAmount = 0m;

                        /*
                         * =====================================================
                         * NORMALIZE DETAILS + CALCULATE SERVER-SIDE TOTALS
                         * =====================================================
                         */
                        foreach (ProductionOrderDetailRequest d
                                 in request.listProductionOrderDetail)
                        {
                            if (d == null)
                                continue;

                            d.PCS =
                                Math.Max(0m, d.PCS);

                            d.ProductionPCS =
                                Math.Max(
                                    0m,
                                    Math.Min(
                                        d.ProductionPCS,
                                        d.PCS
                                    )
                                );

                            d.PendingPCS =
                                Math.Max(
                                    0m,
                                    d.PCS - d.ProductionPCS
                                );

                            d.JobRate =
                                request.JobRate;

                            d.Amount =
                                Math.Round(
                                    d.ProductionPCS *
                                    request.JobRate,
                                    2,
                                    MidpointRounding.AwayFromZero
                                );

                            totalPcs += d.PCS;
                            totalProductionPcs += d.ProductionPCS;
                            totalPendingPcs += d.PendingPCS;
                            totalAmount += d.Amount;
                        }

                        if (totalProductionPcs <= 0m)
                        {
                            tran.Rollback();

                            result.Message =
                                "Production PCS must be greater than 0.";

                            return result;
                        }

                        /*
                         * =====================================================
                         * PRODUCTION ORDER NO
                         * =====================================================
                         */
                        string productionOrderNo = (request.ProductionOrderNo ?? "").Trim();

                        if (productionOrderNo == "")
                        {
                            productionOrderNo = GetNextProductionOrderNo(con, tran);
                        }

                        bool hasRpmM = DoesColumnExist(con, tran, "ProductionOrderMaster", "Rpm");
                        bool hasPanaWidthM = DoesColumnExist(con, tran, "ProductionOrderMaster", "PanaWidth");
                        bool hasNoOfMachinesM = DoesColumnExist(con, tran, "ProductionOrderMaster", "NoOfMachines");

                        bool hasRpmD = DoesColumnExist(con, tran, "ProductionOrderDetail", "Rpm");
                        bool hasPanaRepeatD = DoesColumnExist(con, tran, "ProductionOrderDetail", "PanaRepeat");
                        bool hasPanaWidthD = DoesColumnExist(con, tran, "ProductionOrderDetail", "PanaWidth");
                        bool hasNoOfMachinesD = DoesColumnExist(con, tran, "ProductionOrderDetail", "NoOfMachines");

                        bool hasRepPcsD = DoesColumnExist(con, tran, "ProductionOrderDetail", "RepPCS");
                        bool hasRepRateD = DoesColumnExist(con, tran, "ProductionOrderDetail", "RepRate");
                        bool hasRepAmtD = DoesColumnExist(con, tran, "ProductionOrderDetail", "RepAmt");
                        bool hasJobberAcceptD = DoesColumnExist(con, tran, "ProductionOrderDetail", "JobberAccept");

                        /*
                         * =====================================================
                         * INSERT / UPDATE MASTER
                         * =====================================================
                         */
                        if (isInsert)
                        {
                            string insertMasterSql = @"
INSERT INTO ProductionOrderMaster
(
    ProductionOrderNo,
    ProductionOrderDate,
    JobWorkerID,
    JobWorkerName,
    PanaRepeat,
    " + (hasRpmM ? "Rpm, " : "") + @"
    " + (hasPanaWidthM ? "PanaWidth, " : "") + @"
    " + (hasNoOfMachinesM ? "NoOfMachines, " : "") + @"
    JobRate,
    Traders,
    TotalPcs,
    TotalProductionPcs,
    TotalPendingPcs,
    TotalAmount,
    Status,
    CompanyId,
    UserAccountId,
    DateandTime,
    IsActive
)
VALUES
(
    @ProductionOrderNo,
    @ProductionOrderDate,
    @JobWorkerID,
    @JobWorkerName,
    @PanaRepeat,
    " + (hasRpmM ? "@Rpm, " : "") + @"
    " + (hasPanaWidthM ? "@PanaWidth, " : "") + @"
    " + (hasNoOfMachinesM ? "@NoOfMachines, " : "") + @"
    @JobRate,
    @Traders,
    @TotalPcs,
    @TotalProductionPcs,
    @TotalPendingPcs,
    @TotalAmount,
    @Status,
    @CompanyId,
    @UserAccountId,
    GETDATE(),
    1
);

SELECT CAST(SCOPE_IDENTITY() AS BIGINT);";

                            using (SqlCommand cmd =
                                   new SqlCommand(
                                       insertMasterSql,
                                       con,
                                       tran))
                            {
                                AddMasterParameters(
                                    cmd,
                                    request,
                                    productionOrderNo,
                                    productionDate,
                                    totalPcs,
                                    totalProductionPcs,
                                    totalPendingPcs,
                                    totalAmount,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                productionOrderID =
                                    Convert.ToInt64(
                                        cmd.ExecuteScalar()
                                    );
                            }
                        }
                        else
                        {
                            const string checkMasterSql = @"
                                    SELECT COUNT(1)
                                    FROM ProductionOrderMaster
                                    WHERE ProductionOrderID = @ProductionOrderID
                                      AND IsActive = 1;";

                            using (SqlCommand check =
                                   new SqlCommand(
                                       checkMasterSql,
                                       con,
                                       tran))
                            {
                                check.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value =
                                    productionOrderID;

                                if (Convert.ToInt32(
                                        check.ExecuteScalar()) == 0)
                                {
                                    tran.Rollback();

                                    result.Message =
                                        "Production Order not found or inactive.";

                                    return result;
                                }
                            }

                            string updateMasterSql = @"
                                    UPDATE ProductionOrderMaster
                                    SET
                                        ProductionOrderNo = @ProductionOrderNo,
                                        ProductionOrderDate = @ProductionOrderDate,
                                        JobWorkerID = @JobWorkerID,
                                        JobWorkerName = @JobWorkerName,
                                        PanaRepeat = @PanaRepeat,
                                        " + (hasRpmM ? "Rpm = @Rpm, " : "") + @"
                                        " + (hasPanaWidthM ? "PanaWidth = @PanaWidth, " : "") + @"
                                        " + (hasNoOfMachinesM ? "NoOfMachines = @NoOfMachines, " : "") + @"
                                        JobRate = @JobRate,
                                        Traders = @Traders,
                                        TotalPcs = @TotalPcs,
                                        TotalProductionPcs = @TotalProductionPcs,
                                        TotalPendingPcs = @TotalPendingPcs,
                                        TotalAmount = @TotalAmount,
                                        Status = @Status,
                                        CompanyId = @CompanyId,
                                        UserAccountId = @UserAccountId,
                                        DateandTime = GETDATE()
                                    WHERE ProductionOrderID = @ProductionOrderID
                                      AND IsActive = 1;";

                            using (SqlCommand cmd =
                                   new SqlCommand(
                                       updateMasterSql,
                                       con,
                                       tran))
                            {
                                AddMasterParameters(
                                    cmd,
                                    request,
                                    productionOrderNo,
                                    productionDate,
                                    totalPcs,
                                    totalProductionPcs,
                                    totalPendingPcs,
                                    totalAmount,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                cmd.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value =
                                    productionOrderID;

                                cmd.ExecuteNonQuery();
                            }
                        }

                        /*
                         * =====================================================
                         * DETAILS INSERT / UPDATE
                         * =====================================================
                         */
                        var incomingDetailIds =
                            new HashSet<long>();

                        foreach (ProductionOrderDetailRequest d
                                 in request.listProductionOrderDetail)
                        {
                            if (d == null)
                                continue;

                            /*
                             * =================================================
                             * IMPORTANT DATABASE MAPPING
                             *
                             * SalesOrderDetailID -> SalesOrderDetails.DetailID
                             *
                             * Example from your DB:
                             *
                             * DetailID 13 -> SalesOrderID 5
                             * DetailID 11 -> SalesOrderID 6
                             *
                             * PartyID is then taken from SaleOrder.
                             * =================================================
                             */
                            ResolveSalesOrderValues(con, tran, d);

                            /*
                             * =================================================
                             * BARCODE - FINAL SAFE RULE
                             * =================================================
                             * UPDATE existing detail:
                             *   Always keep the barcode already stored in DB.
                             *   Never trust a barcode coming from the browser.
                             *
                             * INSERT new detail:
                             *   Always generate the barcode on the server.
                             *   Ignore any browser-generated jQuery.now() value.
                             *
                             * This is required because the unique index is:
                             * UX_ProductionOrderDetail_Company_Barcode
                             */
                            long detailID = d.ProductionOrderDetailID;

                            /*
                             * =================================================
                             * RECOVER EXISTING DETAIL ID DURING EDIT
                             * =================================================
                             *
                             * If the edit page did not send
                             * ProductionOrderDetailID, use SalesOrderDetailID
                             * to find the existing row inside the same
                             * ProductionOrder.
                             */
                            if (detailID <= 0 &&
                                !isInsert &&
                                d.SalesOrderDetailID.HasValue &&
                                d.SalesOrderDetailID.Value > 0)
                            {
                                detailID =
                                    GetExistingProductionOrderDetailID(
                                        con,
                                        tran,
                                        productionOrderID,
                                        d.SalesOrderDetailID.Value,
                                        d.SubDetailID,
                                        d.ColourMatchingID
                                    );

                                if (detailID > 0)
                                {
                                    d.ProductionOrderDetailID =
                                        detailID;
                                }
                            }

                            if (detailID <= 0 && !string.IsNullOrWhiteSpace(d.SlipNo) && currentCompanyId.HasValue)
                            {
                                long slipDetailID = GetProductionOrderDetailIDByCompanyAndSlipNo(
                                    con,
                                    tran,
                                    currentCompanyId.Value,
                                    d.SlipNo
                                );

                                if (slipDetailID > 0)
                                {
                                    detailID = slipDetailID;
                                    d.ProductionOrderDetailID = detailID;
                                }
                            }

                            /*
                             * =================================================
                             * SLIP NO - UPDATE SAFE
                             * =================================================
                             *
                             * Never replace an existing detail's SlipNo
                             * during UPDATE. This prevents the unique
                             * CompanyId + SlipNo index from being hit by
                             * a regenerated SlipNo.
                             */
                            if (detailID > 0)
                            {
                                string existingSlipNo =
                                    GetExistingSlipNo(
                                        con,
                                        tran,
                                        detailID,
                                        productionOrderID
                                    );

                                if (!string.IsNullOrWhiteSpace(existingSlipNo))
                                {
                                    d.SlipNo = existingSlipNo;
                                }
                            }

                            /*
                             * =================================================
                             * BARCODE - FINAL SAFE RULE
                             * =================================================
                             *
                             * UPDATE:
                             *   Keep existing DB barcode.
                             *
                             * INSERT:
                             *   Always generate server-side unique barcode.
                             */
                            if (detailID > 0)
                            {
                                string existingBarcode =
                                    GetExistingBarcode(
                                        con,
                                        tran,
                                        detailID,
                                        productionOrderID
                                    );

                                if (!string.IsNullOrWhiteSpace(existingBarcode))
                                {
                                    d.Barcode = existingBarcode;
                                }
                                else
                                {
                                    d.Barcode =
                                        GenerateUniqueBarcode(
                                            con,
                                            tran
                                        );
                                }
                            }
                            else
                            {
                                d.Barcode =
                                    GenerateUniqueBarcode(
                                        con,
                                        tran
                                    );
                            }

                            /*
                             * =================================================
                             * UPDATE EXISTING DETAIL
                             * =================================================
                             */
                            if (detailID > 0)
                            {
                                const string checkDetailSql = @"
                                                                SELECT COUNT(1)
                                                                FROM ProductionOrderDetail
                                                                WHERE ProductionOrderDetailID = @ProductionOrderDetailID;";

                                using (SqlCommand check =
                                       new SqlCommand(
                                           checkDetailSql,
                                           con,
                                           tran))
                                {
                                    check.Parameters.Add(
                                        "@ProductionOrderDetailID",
                                        SqlDbType.BigInt
                                    ).Value =
                                        detailID;

                                    if (Convert.ToInt32(
                                            check.ExecuteScalar()) > 0)
                                    {
                                        string updateDetailSql = @"
                                                        UPDATE ProductionOrderDetail
                                                        SET
                                                            ProductionOrderID = @ProductionOrderID,
                                                            SalesOrderID = @SalesOrderID,
                                                            SalesOrderDetailID = @SalesOrderDetailID,
                                                            SubDetailID = @SubDetailID,
                                                            SalesOrderNo = @SalesOrderNo,
                                                            OrderDate = @OrderDate,
                                                            PartyID = @PartyID,
                                                            PartyName = @PartyName,
                                                            SlipNo = @SlipNo,
                                                            Barcode = @Barcode,
                                                            DesignEntryFormID = @DesignEntryFormID,
                                                            DesignNo = @DesignNo,
                                                            ColourMatchingID = @ColourMatchingID,
                                                            ColourMatchingName = @ColourMatchingName,
                                                            WarpQuality = @WarpQuality,
                                                            WeftQuality = @WeftQuality,
                                                            PCS = @PCS,
                                                            ProductionPCS = @ProductionPCS,
                                                            PendingPCS = @PendingPCS,
                                                            SalesRate = @SalesRate,
                                                            JobRate = @JobRate,
                                                            Amount = @Amount,
                                                            " + (hasRpmD ? "Rpm = @Rpm, " : "") + @"
                                                            " + (hasPanaRepeatD ? "PanaRepeat = @PanaRepeat, " : "") + @"
                                                            " + (hasPanaWidthD ? "PanaWidth = @PanaWidth, " : "") + @"
                                                            " + (hasNoOfMachinesD ? "NoOfMachines = @NoOfMachines, " : "") + @"
                                                            " + (hasRepPcsD ? "RepPCS = @RepPCS, " : "") + @"
                                                            " + (hasRepRateD ? "RepRate = @RepRate, " : "") + @"
                                                            " + (hasRepAmtD ? "RepAmt = @RepAmt, " : "") + @"
                                                            " + (hasJobberAcceptD ? "JobberAccept = @JobberAccept, " : "") + @"
                                                            CompanyId = @CompanyId,
                                                            UserAccountId = @UserAccountId,
                                                            DateandTime = GETDATE(),
                                                            IsActive = 1
                                                        WHERE ProductionOrderDetailID = @ProductionOrderDetailID
                                                          AND ProductionOrderID = @ProductionOrderID;";

                                        using (SqlCommand cmd =
                                               new SqlCommand(
                                                   updateDetailSql,
                                                   con,
                                                   tran))
                                        {
                                            AddDetailParameters(
                                                cmd,
                                                d,
                                                productionOrderID,
                                                request,
                                                currentCompanyId,
                                                currentUserAccountId
                                            );

                                            cmd.Parameters.Add(
                                                "@ProductionOrderDetailID",
                                                SqlDbType.BigInt
                                            ).Value =
                                                detailID;

                                            cmd.ExecuteNonQuery();
                                        }

                                        incomingDetailIds.Add(
                                            detailID
                                        );

                                        result.UpdatedDetails++;

                                        continue;
                                    }
                                }
                            }

                            /*
                             * =================================================
                             * INSERT NEW DETAIL
                             * =================================================
                             *
                             * Do not allow an active SlipNo belonging to
                             * another Production Order to create a raw SQL
                             * duplicate-key exception.
                             */
                            if (detailID <= 0)
                            {
                                if (string.IsNullOrWhiteSpace(d.SlipNo))
                                {
                                    tran.Rollback();

                                    result.Message =
                                        "Slip No is required for Production Order detail.";

                                    return result;
                                }

                                decimal remainingPending =
                                    GetRemainingPendingPcsForSlip(
                                        con,
                                        tran,
                                        d.SubDetailID,
                                        d.SalesOrderDetailID,
                                        d.SlipNo,
                                        currentCompanyId,
                                        productionOrderID
                                    );

                                if (remainingPending <= 0)
                                {
                                    tran.Rollback();

                                    result.Message =
                                        "Slip No " +
                                        d.SlipNo +
                                        " has no pending pcs remaining (0 pending). Cannot create further production orders.";

                                    return result;
                                }
                            }

                            /*
                             * =================================================
                             * INSERT NEW DETAIL
                             * =================================================
                             */
                            string insertDetailSql = @"
                                    INSERT INTO ProductionOrderDetail
                                    (
                                        ProductionOrderID,
                                        SalesOrderID,
                                        SalesOrderDetailID,
                                        SubDetailID,
                                        SalesOrderNo,
                                        OrderDate,
                                        PartyID,
                                        PartyName,
                                        SlipNo,
                                        Barcode,
                                        DesignEntryFormID,
                                        DesignNo,
                                        ColourMatchingID,
                                        ColourMatchingName,
                                        WarpQuality,
                                        WeftQuality,
                                        PCS,
                                        ProductionPCS,
                                        PendingPCS,
                                        SalesRate,
                                        JobRate,
                                        Amount,
                                        " + (hasRpmD ? "Rpm, " : "") + @"
                                        " + (hasPanaRepeatD ? "PanaRepeat, " : "") + @"
                                        " + (hasPanaWidthD ? "PanaWidth, " : "") + @"
                                        " + (hasNoOfMachinesD ? "NoOfMachines, " : "") + @"
                                        " + (hasRepPcsD ? "RepPCS, " : "") + @"
                                        " + (hasRepRateD ? "RepRate, " : "") + @"
                                        " + (hasRepAmtD ? "RepAmt, " : "") + @"
                                        " + (hasJobberAcceptD ? "JobberAccept, " : "") + @"
                                        CompanyId,
                                        UserAccountId,
                                        DateandTime,
                                        IsActive
                                    )
                                    VALUES
                                    (
                                        @ProductionOrderID,
                                        @SalesOrderID,
                                        @SalesOrderDetailID,
                                        @SubDetailID,
                                        @SalesOrderNo,
                                        @OrderDate,
                                        @PartyID,
                                        @PartyName,
                                        @SlipNo,
                                        @Barcode,
                                        @DesignEntryFormID,
                                        @DesignNo,
                                        @ColourMatchingID,
                                        @ColourMatchingName,
                                        @WarpQuality,
                                        @WeftQuality,
                                        @PCS,
                                        @ProductionPCS,
                                        @PendingPCS,
                                        @SalesRate,
                                        @JobRate,
                                        @Amount,
                                        " + (hasRpmD ? "@Rpm, " : "") + @"
                                        " + (hasPanaRepeatD ? "@PanaRepeat, " : "") + @"
                                        " + (hasPanaWidthD ? "@PanaWidth, " : "") + @"
                                        " + (hasNoOfMachinesD ? "@NoOfMachines, " : "") + @"
                                        " + (hasRepPcsD ? "@RepPCS, " : "") + @"
                                        " + (hasRepRateD ? "@RepRate, " : "") + @"
                                        " + (hasRepAmtD ? "@RepAmt, " : "") + @"
                                        " + (hasJobberAcceptD ? "@JobberAccept, " : "") + @"
                                        @CompanyId,
                                        @UserAccountId,
                                        GETDATE(),
                                        1
                                    );

                                    SELECT CAST(SCOPE_IDENTITY() AS BIGINT);";

                            using (SqlCommand cmd =
                                   new SqlCommand(
                                       insertDetailSql,
                                       con,
                                       tran))
                            {
                                AddDetailParameters(
                                    cmd,
                                    d,
                                    productionOrderID,
                                    request,
                                    currentCompanyId,
                                    currentUserAccountId
                                );

                                long newDetailID =
                                    Convert.ToInt64(
                                        cmd.ExecuteScalar()
                                    );

                                incomingDetailIds.Add(
                                    newDetailID
                                );

                                result.InsertedDetails++;
                            }
                        }

                        /*
                         * =====================================================
                         * EDIT MODE:
                         * OLD ACTIVE DETAILS NOT SENT BY CLIENT = SOFT DELETE
                         * =====================================================
                         */
                        if (!isInsert)
                        {
                            const string oldDetailsSql = @"
                                                        SELECT ProductionOrderDetailID
                                                        FROM ProductionOrderDetail
                                                        WHERE ProductionOrderID = @ProductionOrderID
                                                          AND IsActive = 1;";

                            var oldDetailIds =
                                new List<long>();

                            using (SqlCommand cmd =
                                   new SqlCommand(
                                       oldDetailsSql,
                                       con,
                                       tran))
                            {
                                cmd.Parameters.Add(
                                    "@ProductionOrderID",
                                    SqlDbType.BigInt
                                ).Value =
                                    productionOrderID;

                                using (SqlDataReader dr =
                                       cmd.ExecuteReader())
                                {
                                    while (dr.Read())
                                    {
                                        oldDetailIds.Add(
                                            Convert.ToInt64(
                                                dr[0]
                                            )
                                        );
                                    }
                                }
                            }

                            foreach (long oldID
                                     in oldDetailIds)
                            {
                                if (incomingDetailIds.Contains(oldID))
                                    continue;

                                const string deactivateSql = @"
                                                UPDATE ProductionOrderDetail
                                                SET
                                                    IsActive = 0,
                                                    DateandTime = GETDATE()
                                                WHERE ProductionOrderDetailID = @ProductionOrderDetailID
                                                  AND ProductionOrderID = @ProductionOrderID;";

                                using (SqlCommand cmd =
                                       new SqlCommand(
                                           deactivateSql,
                                           con,
                                           tran))
                                {
                                    cmd.Parameters.Add(
                                        "@ProductionOrderDetailID",
                                        SqlDbType.BigInt
                                    ).Value =
                                        oldID;

                                    cmd.Parameters.Add(
                                        "@ProductionOrderID",
                                        SqlDbType.BigInt
                                    ).Value =
                                        productionOrderID;

                                    cmd.ExecuteNonQuery();

                                    result.DeletedDetails++;
                                }
                            }
                        }

                        tran.Commit();

                        result.Success = true;
                        result.ProductionOrderID =
                            productionOrderID;

                        result.ProductionOrderNo =
                            productionOrderNo;

                        result.Message =
                            isInsert
                                ? "Production Order saved successfully."
                                : "Production Order updated successfully.";

                        return result;
                    }
                    catch (Exception ex)
                    {
                        try
                        {
                            tran.Rollback();
                        }
                        catch
                        {
                        }

                        result.Success = false;
                        result.Message = ex.Message;

                        return result;
                    }
                }
            }
        }
        /*
         * ================================================================
         * RESOLVE SALES ORDER VALUES
         * ================================================================
         *
         * Mapping:
         *
         * ProductionOrderDetail.SalesOrderDetailID
         *          =
         * SalesOrderDetails.DetailID
         *
         * SalesOrderDetails.DetailID 13 -> SalesOrderID 5
         * SalesOrderDetails.DetailID 11 -> SalesOrderID 6
         *
         * Then:
         *
         * SaleOrder.SalesOrderID -> PartyID
         *
         * Also gets DesignColorMatchingID when ColourMatchingID
         * was not supplied by the frontend.
         */
        private static void ResolveSalesOrderValues(SqlConnection con, SqlTransaction tran, ProductionOrderDetailRequest d)
        {
            if (!d.SalesOrderDetailID.HasValue || d.SalesOrderDetailID.Value <= 0)
            {
                return;
            }

            const string sql = @" SELECT TOP 1  SOD.SaleOrderID, SO.PartyID, SOD.DesignColorMatchingID  FROM SaleOrderDetails SOD
                                        LEFT JOIN SaleOrder SO  ON SO.SaleOrderID = SOD.SaleOrderID WHERE SOD.DetailID = @DetailID;";

            using (SqlCommand cmd = new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.Add("@DetailID", SqlDbType.BigInt).Value = d.SalesOrderDetailID.Value;

                using (SqlDataReader dr =
                       cmd.ExecuteReader())
                {
                    if (!dr.Read())
                        return;

                    /*
                     * SalesOrderID
                     */
                    if (dr["SaleOrderID"] != DBNull.Value)
                    {
                        d.SalesOrderID =
                            Convert.ToInt64(
                                dr["SaleOrderID"]
                            );
                    }

                    /*
                     * PartyID
                     */
                    if (dr["PartyID"] != DBNull.Value)
                    {
                        d.PartyID =
                            Convert.ToInt64(
                                dr["PartyID"]
                            );
                    }

                    /*
                     * ColourMatchingID
                     *
                     * SalesOrderDetails screenshot shows:
                     * DesignColorMatchingID
                     *
                     * Use it only if frontend has not supplied
                     * ColourMatchingID.
                     */
                    if ((!d.ColourMatchingID.HasValue ||
                         d.ColourMatchingID.Value <= 0) &&
                        dr["DesignColorMatchingID"] != DBNull.Value)
                    {
                        d.ColourMatchingID =
                            Convert.ToInt64(
                                dr["DesignColorMatchingID"]
                            );
                    }
                }
            }
        }
        /*
         * ================================================================
         * CURRENT USER ID
         * ================================================================
         *
         * Required source:
         *
         * Context.Request.Cookies["UserIDs"].Value.Split('=')[1]
         *
         * Handles both:
         *
         * UserIDs=17
         * and
         * 17
         */
        private long? GetCurrentUserAccountId()
        {
            try
            {
                if (Context == null ||
                    Context.Request == null)
                {
                    return null;
                }

                HttpCookie cookie =
                    Context.Request.Cookies["UserIDs"];

                if (cookie == null)
                    return null;

                string cookieValue =
                    cookie.Value;

                if (string.IsNullOrWhiteSpace(cookieValue))
                    return null;

                string[] parts =
                    cookieValue.Split('=');

                string userIdText =
                    parts.Length > 1
                        ? parts[1]
                        : parts[0];

                long userId;

                if (long.TryParse(
                        userIdText,
                        out userId))
                {
                    return userId;
                }
            }
            catch
            {
            }

            return null;
        }
        /*
         * ================================================================
         * DEFAULT COMPANY
         * ================================================================
         */
        private static long? GetDefaultCompanyId(SqlConnection con, SqlTransaction tran)
        {
            const string sql = @"
SELECT TOP 1 CompanyId
FROM CompanyMaster
WHERE is_default = 1
ORDER BY CompanyId;";

            using (SqlCommand cmd =
                   new SqlCommand(
                       sql,
                       con,
                       tran))
            {
                object value =
                    cmd.ExecuteScalar();

                if (value != null &&
                    value != DBNull.Value)
                {
                    return Convert.ToInt64(value);
                }
            }

            return null;
        }
        /*
         * ================================================================
         * BARCODE
         * ================================================================
         *
         * Main value is milliseconds, equivalent to:
         *
         * var milliseconds = jQuery.now();
         *
         * A uniqueness check is added because two rows can otherwise
         * receive the same millisecond value in very fast execution.
         */
        private static string GenerateUniqueBarcode(SqlConnection con, SqlTransaction tran)
        {
            long milliseconds =
                DateTimeOffset.UtcNow
                    .ToUnixTimeMilliseconds();

            const string checkSql = @"
SELECT COUNT(1)
FROM ProductionOrderDetail
WHERE CompanyId = @CompanyId
  AND Barcode = @Barcode
  AND IsActive = 1;";

            long? companyId =
                GetDefaultCompanyId(con, tran);

            if (!companyId.HasValue)
                throw new Exception(
                    "Default CompanyId could not be found."
                );

            for (int i = 0; i < 1000; i++)
            {
                string barcode =
                    milliseconds.ToString();

                using (SqlCommand cmd =
                       new SqlCommand(
                           checkSql,
                           con,
                           tran))
                {
                    cmd.Parameters.Add(
                        "@CompanyId",
                        SqlDbType.BigInt
                    ).Value = companyId.Value;

                    cmd.Parameters.Add(
                        "@Barcode",
                        SqlDbType.NVarChar,
                        100
                    ).Value = barcode;

                    int count =
                        Convert.ToInt32(
                            cmd.ExecuteScalar()
                        );

                    if (count == 0)
                        return barcode;
                }

                milliseconds++;
            }

            throw new Exception(
                "Unable to generate a unique Barcode."
            );
        }
        /*
         * ================================================================
         * MASTER PARAMETERS
         * ================================================================
         */
        private static void AddMasterParameters(SqlCommand cmd, ProductionOrderRequest request, string productionOrderNo, DateTime productionDate, decimal totalPcs, decimal totalProductionPcs, decimal totalPendingPcs, decimal totalAmount, long? currentCompanyId, long? currentUserAccountId)
        {
            cmd.Parameters.Add(
                "@ProductionOrderNo",
                SqlDbType.NVarChar,
                50
            ).Value =
                DbString(productionOrderNo);

            cmd.Parameters.Add(
                "@ProductionOrderDate",
                SqlDbType.Date
            ).Value =
                productionDate.Date;

            cmd.Parameters.Add(
                "@JobWorkerID",
                SqlDbType.BigInt
            ).Value =
                (object)request.JobWorkerID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@JobWorkerName",
                SqlDbType.NVarChar,
                200
            ).Value =
                DbString(request.JobWorkerName);

            cmd.Parameters.Add(
                "@PanaRepeat",
                SqlDbType.Decimal
            ).Value =
                request.PanaRepeat;

            cmd.Parameters.Add(
                "@Rpm",
                SqlDbType.Decimal
            ).Value =
                request.Rpm;

            cmd.Parameters.Add(
                "@PanaWidth",
                SqlDbType.Decimal
            ).Value =
                request.PanaWidth;

            cmd.Parameters.Add(
                "@NoOfMachines",
                SqlDbType.Decimal
            ).Value =
                request.NoOfMachines;

            cmd.Parameters.Add(
                "@JobRate",
                SqlDbType.Decimal
            ).Value =
                request.JobRate;

            cmd.Parameters.Add(
                "@Traders",
                SqlDbType.NVarChar,
                200
            ).Value =
                DbString(request.Traders);

            cmd.Parameters.Add(
                "@TotalPcs",
                SqlDbType.Decimal
            ).Value =
                totalPcs;

            cmd.Parameters.Add(
                "@TotalProductionPcs",
                SqlDbType.Decimal
            ).Value =
                totalProductionPcs;

            cmd.Parameters.Add(
                "@TotalPendingPcs",
                SqlDbType.Decimal
            ).Value =
                totalPendingPcs;

            cmd.Parameters.Add(
                "@TotalAmount",
                SqlDbType.Decimal
            ).Value =
                totalAmount;

            cmd.Parameters.Add(
                "@Status",
                SqlDbType.TinyInt
            ).Value =
                totalPendingPcs <= 0m
                    ? 2
                    : 1;

            /*
             * IMPORTANT:
             * Do NOT use request.CompanyId here.
             */
            cmd.Parameters.Add(
                "@CompanyId",
                SqlDbType.BigInt
            ).Value =
                (object)currentCompanyId ??
                DBNull.Value;

            /*
             * IMPORTANT:
             * Do NOT use request.UserAccountId here.
             */
            cmd.Parameters.Add(
                "@UserAccountId",
                SqlDbType.BigInt
            ).Value =
                (object)currentUserAccountId ??
                DBNull.Value;
        }
        /*
         * ================================================================
         * DETAIL PARAMETERS
         * ================================================================
         */
        private static void AddDetailParameters(SqlCommand cmd, ProductionOrderDetailRequest d, long productionOrderID, ProductionOrderRequest request, long? currentCompanyId, long? currentUserAccountId)
        {
            cmd.Parameters.Add(
                "@ProductionOrderID",
                SqlDbType.BigInt
            ).Value =
                productionOrderID;

            /*
             * This has already been resolved from
             * SalesOrderDetails.DetailID before this method.
             */
            cmd.Parameters.Add(
                "@SalesOrderID",
                SqlDbType.BigInt
            ).Value =
                (object)d.SalesOrderID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@SalesOrderDetailID",
                SqlDbType.BigInt
            ).Value =
                (object)d.SalesOrderDetailID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@SubDetailID",
                SqlDbType.BigInt
            ).Value =
                (object)d.SubDetailID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@SalesOrderNo",
                SqlDbType.NVarChar,
                50
            ).Value =
                DbString(d.SalesOrderNo);

            cmd.Parameters.Add(
                "@OrderDate",
                SqlDbType.Date
            ).Value =
                ToDbDate(d.OrderDate);

            /*
             * PartyID has already been resolved from SaleOrder
             * using SalesOrderID.
             */
            cmd.Parameters.Add(
                "@PartyID",
                SqlDbType.BigInt
            ).Value =
                (object)d.PartyID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@PartyName",
                SqlDbType.NVarChar,
                300
            ).Value =
                DbString(d.PartyName);

            cmd.Parameters.Add(
                "@SlipNo",
                SqlDbType.NVarChar,
                50
            ).Value =
                DbString(d.SlipNo);

            cmd.Parameters.Add(
                "@Barcode",
                SqlDbType.NVarChar,
                100
            ).Value =
                DbString(d.Barcode);

            /*
             * DesignEntryFormID is retained from frontend/source data.
             * It is NOT guessed from DesignID.
             */
            cmd.Parameters.Add(
                "@DesignEntryFormID",
                SqlDbType.BigInt
            ).Value =
                (object)d.DesignEntryFormID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@DesignNo",
                SqlDbType.NVarChar,
                100
            ).Value =
                DbString(d.DesignNo);

            /*
             * ColourMatchingID is resolved from
             * SalesOrderDetails.DesignColorMatchingID when missing.
             */
            cmd.Parameters.Add(
                "@ColourMatchingID",
                SqlDbType.BigInt
            ).Value =
                (object)d.ColourMatchingID ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@ColourMatchingName",
                SqlDbType.NVarChar,
                300
            ).Value =
                DbString(d.ColourMatchingName);

            cmd.Parameters.Add(
                "@WarpQuality",
                SqlDbType.NVarChar,
                1000
            ).Value =
                DbString(d.WarpQuality);

            cmd.Parameters.Add(
                "@WeftQuality",
                SqlDbType.NVarChar,
                1000
            ).Value =
                DbString(d.WeftQuality);

            cmd.Parameters.Add(
                "@PCS",
                SqlDbType.Decimal
            ).Value =
                d.PCS;

            cmd.Parameters.Add(
                "@ProductionPCS",
                SqlDbType.Decimal
            ).Value =
                d.ProductionPCS;

            cmd.Parameters.Add(
                "@PendingPCS",
                SqlDbType.Decimal
            ).Value =
                d.PendingPCS;

            cmd.Parameters.Add(
                "@SalesRate",
                SqlDbType.Decimal
            ).Value =
                d.SalesRate;

            cmd.Parameters.Add(
                "@JobRate",
                SqlDbType.Decimal
            ).Value =
                request.JobRate;

            cmd.Parameters.Add(
                "@Amount",
                SqlDbType.Decimal
            ).Value =
                d.Amount;

            decimal rpm = d.Rpm > 0 ? d.Rpm : request.Rpm;
            decimal panaRepeat = d.PanaRepeat > 0 ? d.PanaRepeat : request.PanaRepeat;
            decimal panaWidth = d.PanaWidth > 0 ? d.PanaWidth : request.PanaWidth;
            decimal noOfMachines = d.NoOfMachines > 0 ? d.NoOfMachines : request.NoOfMachines;

            cmd.Parameters.Add(
                "@Rpm",
                SqlDbType.Decimal
            ).Value =
                rpm;

            cmd.Parameters.Add(
                "@PanaRepeat",
                SqlDbType.Decimal
            ).Value =
                panaRepeat;

            cmd.Parameters.Add(
                "@PanaWidth",
                SqlDbType.Decimal
            ).Value =
                panaWidth;

            cmd.Parameters.Add(
                "@NoOfMachines",
                SqlDbType.Decimal
            ).Value =
                noOfMachines;

            cmd.Parameters.Add(
                "@RepPCS",
                SqlDbType.Decimal
            ).Value =
                d.RepPCS > 0 ? d.RepPCS : d.ProductionPCS;

            cmd.Parameters.Add(
                "@RepRate",
                SqlDbType.Decimal
            ).Value =
                d.RepRate > 0 ? d.RepRate : d.JobRate;

            cmd.Parameters.Add(
                "@RepAmt",
                SqlDbType.Decimal
            ).Value =
                d.RepAmt > 0 ? d.RepAmt : d.Amount;

            cmd.Parameters.Add(
                "@JobberAccept",
                SqlDbType.Int
            ).Value =
                d.JobberAccept;

            /*
             * ALWAYS use current/default values.
             */
            cmd.Parameters.Add(
                "@CompanyId",
                SqlDbType.BigInt
            ).Value =
                (object)currentCompanyId ??
                DBNull.Value;

            cmd.Parameters.Add(
                "@UserAccountId",
                SqlDbType.BigInt
            ).Value =
                (object)currentUserAccountId ??
                DBNull.Value;
        }

        private static bool DoesColumnExist(SqlConnection con, SqlTransaction tran, string tableName, string columnName)
        {
            try
            {
                const string sql = "SELECT COUNT(1) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME = @ColumnName;";
                using (SqlCommand cmd = new SqlCommand(sql, con, tran))
                {
                    cmd.Parameters.AddWithValue("@TableName", tableName);
                    cmd.Parameters.AddWithValue("@ColumnName", columnName);
                    return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
                }
            }
            catch
            {
                return false;
            }
        }

        private static bool DoesTableExist(SqlConnection con, string tableName)
        {
            try
            {
                const string sql = "SELECT COUNT(1) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = @TableName;";
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.AddWithValue("@TableName", tableName);
                    return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
                }
            }
            catch
            {
                return false;
            }
        }

        private static bool HasColumn(SqlDataReader dr, string columnName)
        {
            for (int i = 0; i < dr.FieldCount; i++)
            {
                if (dr.GetName(i).Equals(columnName, StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }
        /*
         * ================================================================
         * STRING / DATE HELPERS
         * ================================================================
         */
        private static object DbString(string value)
        {
            return string.IsNullOrWhiteSpace(value)
                ? (object)DBNull.Value
                : value.Trim();
        }
        private static object ToDbDate(string value)
        {
            DateTime date;

            return TryParseDate(
                value,
                out date
            )
                ? (object)date.Date
                : DBNull.Value;
        }
        private static bool TryParseDate(string value, out DateTime date)
        {
            string[] formats =
            {
            "yyyy-MM-dd",
            "dd/MM/yyyy",
            "MM/dd/yyyy",
            "dd-MM-yyyy",
            "MM-dd-yyyy",
            "yyyy/MM/dd"
        };

            return DateTime.TryParseExact(
                       (value ?? "").Trim(),
                       formats,
                       CultureInfo.InvariantCulture,
                       DateTimeStyles.None,
                       out date
                   )
                   ||
                   DateTime.TryParse(
                       (value ?? "").Trim(),
                       CultureInfo.InvariantCulture,
                       DateTimeStyles.None,
                       out date
                   );
        }
        /*
         * ================================================================
         * NEXT PRODUCTION ORDER NO
         * ================================================================
         */
        private static string GetNextProductionOrderNo(SqlConnection con, SqlTransaction tran)
        {
            const string sql = @"
                    SELECT ISNULL(
                        MAX(
                            TRY_CONVERT(
                                INT,
                                CASE
                                    WHEN ProductionOrderNo LIKE 'PRO%'
                                    THEN SUBSTRING(
                                        ProductionOrderNo,
                                        4,
                                        20
                                    )
                                    ELSE NULL
                                END
                            )
                        ),
                        0
                    ) + 1
                    FROM ProductionOrderMaster;";

            using (SqlCommand cmd =
                   new SqlCommand(
                       sql,
                       con,
                       tran))
            {
                int next =
                    Convert.ToInt32(
                        cmd.ExecuteScalar()
                    );

                return "PRO" +
                       next.ToString("0000");
            }
        }
        /*
         * ================================================================
         * FIND EXISTING DETAIL IN SAME PRODUCTION ORDER
         * ================================================================
         */
        private static long GetExistingProductionOrderDetailID(
            SqlConnection con,
            SqlTransaction tran,
            long productionOrderID,
            long salesOrderDetailID,
            long? subDetailID = null,
            long? colourMatchingID = null)
        {
            const string sql = @"
SELECT TOP 1 ProductionOrderDetailID
FROM ProductionOrderDetail
WHERE ProductionOrderID = @ProductionOrderID
  AND SalesOrderDetailID = @SalesOrderDetailID
  AND (@SubDetailID IS NULL OR @SubDetailID <= 0 OR ISNULL(SubDetailID, 0) = @SubDetailID)
  AND (@ColourMatchingID IS NULL OR @ColourMatchingID <= 0 OR ISNULL(ColourMatchingID, 0) = @ColourMatchingID)
  AND IsActive = 1
ORDER BY ProductionOrderDetailID ASC;";

            using (SqlCommand cmd =
                   new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.Add(
                    "@ProductionOrderID",
                    SqlDbType.BigInt
                ).Value = productionOrderID;

                cmd.Parameters.Add(
                    "@SalesOrderDetailID",
                    SqlDbType.BigInt
                ).Value = salesOrderDetailID;

                cmd.Parameters.Add(
                    "@SubDetailID",
                    SqlDbType.BigInt
                ).Value = (object)subDetailID ?? DBNull.Value;

                cmd.Parameters.Add(
                    "@ColourMatchingID",
                    SqlDbType.BigInt
                ).Value = (object)colourMatchingID ?? DBNull.Value;

                object value =
                    cmd.ExecuteScalar();

                if (value != null &&
                    value != DBNull.Value)
                {
                    return Convert.ToInt64(value);
                }
            }

            return 0;
        }

        private static long GetProductionOrderDetailIDByCompanyAndSlipNo(
            SqlConnection con,
            SqlTransaction tran,
